/* 令和3年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r03.committeeSessions.push(...[{"id":"r03-20210707-9","meetingId":"r03-cm07","date":"2021年7月7日","dateIso":"2021-07-07","committee":"文教委員会","time":"午前１０時００分～午後 ０時２３分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を46件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"はじめに、(1)学校改築の進捗","agenda":"はじめに、(1)学校改築の進捗","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"あわせて、随時、小学校の学級編成も全学年３５人になっていくわけですけれども、これを踏まえて改築計画を立てている学校というのは、今日、１枚目の資料で提示された学校で言うとどこになるのか、伺いたいと思います。","respondent":"有馬庶務課長","answer":"３５人学級への対応ですけれども、鮫浜小学校、浜川小学校、第四日野小学校、浜川中学校につきましては、いわゆる３５人学級にという話を受けて計画をしたものではありません。","voiceIndex":5,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"分かりました。今後の改築計画を立てるに当たって、これらの少人数学級の流れ、少なくとも中学校は、恐らくこうなるだろうという、こういう流れを踏まえるべきだと思うのですけれども、いかがでしょうか。","respondent":"有馬庶務課長","answer":"今、品川区の学校では、文科省の基準から言えば、１人当たりの校庭の面積が非常に狭くなっているという現実もありますので、運動スペースを確保しつつ、有効な校舎も建てていきたいというふうに考えておりますので、そこは慎重にいろいろ検討して進めていきたいと考えております。","voiceIndex":7,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"やはり、校庭の話もありますけれども、教室に４０人詰め込んだら、それは１人当たりの日常的に過ごすスペースがものすごく狭くなるので、やはり、児童・生徒の環境というのを考えると、もう見越して、区独自で少人数学級を進めていくという気構えで、私は、新築・整備のときには、そういった少人数学級も、今からきちんと視野に入れて計画をしていくことが必要だと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-003"},{"speaker":"吉田委員","kind":"質問","question":"今は改築の計画概要ということなので、この段階でどの辺まで決まっているのかの認識がなくて申し訳ない、今質問するべきかどうか分からないのですけれども、学校のトイレに関して、結構今までいろいろな委員の方から、洋式とか和式とか、洋式がいいという方もあるし、やはり一定和式は残すべきというご意見もあって、トイレはすごく大事かなというふうに思うのですけれども。","respondent":"小林学校施設担当課長","answer":"当然、雨水につきましては、雨水槽を設けて、便所の排水に利用したり、植栽の散水に使用したり、検討して設置するように努力してまいります。","voiceIndex":11,"id":"exchange-004"},{"speaker":"吉田委員","kind":"質問・要望","question":"できるところではぜひ取り入れていただいて、やはり子どもたちが、その意義が分かるような形の設備にしていただきたいなというふうに思います。それから、先ほど１つ忘れました。どうなのでしょう。あったのでしたら、ぜひ継続をお願いしたいのですが、いかがでしょうか。","respondent":"小林学校施設担当課長","answer":"学校については、屋上に降った雨をそのまま集めますので、大きな水槽が必要になってきます。２０トンから３０トン、それは地下のピットに入れて、雨水槽ということで設けるのが一般的です。","voiceIndex":13,"id":"exchange-005"},{"speaker":"松澤委員","kind":"質問","question":"大きくというか、学校改築の考え方についてお聞きしたいのですけれども、１年に１回ずつ学校改築が計画として繰り広げられていくのですけれども、それの根拠といいますか、老朽化なのか、人口推移なのか、地域バランスなのか、何かそういったものの考え方があると思うのですけれども、それを教えていただけますか。","respondent":"有馬庶務課長","answer":"改築の進め方、考え方ですけれども、今、松澤委員が言われたとおり、老朽度、これをまず優先はしますけれども、最近では就学人口がかなり急激に増加しており、受け入れていかなければならないということもありますので、就学人口の動向、それから、当然、地域バランスということ。","voiceIndex":17,"id":"exchange-006"},{"speaker":"松澤委員","kind":"質問","question":"それで３５人学級になれば、なおさらいろいろ教室も増やさなければいけないという部分について、今、戸越公園の駅前が開発だという話になってくると、そういうところには今度また人が集まってきますよね。そうするとやはり、人口の推移、そういったものと、要は教育委員会との連携というのですか、そういったものというのはしっかりとれているのでしょうか。","respondent":"有馬庶務課長","answer":"まさに学校の規模、改修するに当たってどの程度の教室が今後必要になってくるかですので、今もマンション開発等がどういう状況なのかということは、都市計画課なり、都市開発課なりと情報をやり取りして、いつ頃こういうマンションの計画があります。","voiceIndex":19,"id":"exchange-007"},{"speaker":"つる委員","kind":"質問","question":"いろいろな課題も各地域では言われている中で、この辺のプールが見える状況なのかどうかという、まずそこで、目隠しとかそういうものというのはある程度、配慮されたつくりになっているのか、その辺を改めて教えてください。","respondent":"小林学校施設担当課長","answer":"第四日野小学校のご質問にお答えします。いろいろな検討の中で、配置計画などをいろいろやりまして、その中で、この敷地についてはこのような配置が一番ベストといった考え方で計画はしたものです。","voiceIndex":24,"id":"exchange-008"},{"speaker":"つる委員","kind":"質問・要望","question":"当然、設計の規制とか制約とかいろいろとある中で、例えば、後に設備として、それは公の学校としてはなかなか制度上難しい部分もあるのかもしれないのですけれども、できる範囲の中で、ご答弁の中にもあったお互いの配慮が、後にいろいろなお声として上がってきたときに、できないと言うよりも、事前にそういう用意もできるということが大事かなと思ったので確認をさせていただきました。","respondent":"有馬庶務課長","answer":"まだ残り半分あるかなというところですが、地元の人にとっては、うちの学校はいつになるのかということにだんだんなってくることは、我々も認識しているところではありますけれども、今のように。","voiceIndex":26,"id":"exchange-009"},{"speaker":"つる委員","kind":"質問・要望","question":"ですけれども、今の就学前の子どもたちがどこへ行こうかなという声が、今、伺う中で、校舎がきれいであるとか、新しいとかということではない部分の魅力というところで、後地小学校についても、そこのところをしっかりてこ入れをしていただいた中で、校舎もきれいになったというのはあるのですけれども、ぜひ周辺の学校も、人口の関係もあるので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-010"},{"speaker":"吉田委員","kind":"確認","question":"私が、図面の見方が決して得意ではないので誤解かもしれないのですけれども、縦横で見ると、特別支援学級などが、すごくほかの教室からは行きにくいというか、そういうところに、断面図を見ても、ここだけが体育館の下のところに入り込んでいてというふうに見えるのですけれども、やはり、特別支援学級については考え方がいろいろあって、私たちとしては普通のクラスで障害児もというふうに思うのですが。","respondent":"小林学校施設担当課長、矢部教育総合支援センター長","answer":"いろいろな考え方がありますが、当然、特別支援学級もそれぞれの子どもさんの程度とか、いろいろな考えの設計条件をいただいて、このように少し離すとか、近くにするだとか、委員がおっしゃった交流の場は。教員の考え方もありますので、今、コロナ禍なので、通常でもなかなか難しいのですけれども、交流をこちらとしても推進しておりますので、教室は、あまり高い階ではなく、これは２階になっていますかね。","voiceIndex":30,"id":"exchange-011"},{"speaker":"吉田委員","kind":"質問","question":"分かりました。保育園までは一緒ですので。いろいろなお考えがあるということは分かりました。ぜひ、今後もいろいろな方のご意見を聞きながら、ただ一方で、やはり社会に出たら一緒に暮らすのですから、その辺のことは教育委員会としても、ぜひ重く見て、学校の設計もしていただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":33,"id":"exchange-012"}]},{"id":"topic-02","title":"令和４年度新入学者の受入枠","agenda":"令和４年度新入学者の受入枠","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"学校施設やハード上の制約もあるのか伺います。私としては、初めから加配の選択というのを前提に想定するというのではなくて、３５人ということの学級量の選択を想定して受入枠というのを作ったほうがいいのではないかと思うのですけれども、いかがでしょうか。","respondent":"勝亦学務課長","answer":"例えば、３０人ですとか３５人と小さく設定しますと、学校のほうで受け入れられますよという人数のほうが減ってしまいますので、まずは学区として入学想定される人数については最大限受け入れるということで、法律どおり設定しているものです。","voiceIndex":38,"id":"exchange-013"},{"speaker":"安藤委員","kind":"質問","question":"何となく分かったような、分からないような。学校の施設的条件を加味した学区のさらなる見直しも必要なのかなとか、区内どこの学校に通っても、この少人数学級というのを享受できる環境を作るべきなのではないかと思うのですけれども、こういう受入枠というのを示すというよりも、そういったところをしっかりと注力すべきなのではないかと思うのですけれども、あわせて伺います。","respondent":"勝亦学務課長","answer":"少人数学級との関係もありますけれども、課題は、いただいたように、あります。ここについては検討できるものは研究していきたいと考えております。","voiceIndex":40,"id":"exchange-014"},{"speaker":"安藤委員","kind":"質問・要望","question":"意見で終わりますけれども、こういう受入枠を提示して選択してもらおうというようなところで、毎年腐心をしているわけですが、そういうところで苦労をするのではなく、やはり、最大の使命である、全ての子どもにとって良質な教育環境、少人数学級をしっかりと環境を整えていくというところに、やはりぜひ、労力と時間と工夫、それを費やしていただきたいなというふうに私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-015"},{"speaker":"松本委員","kind":"質問","question":"この受入可能人数ということで、５人余裕を持たせているということだと思うので、それは区内転居者とか、区外転入者ということで、余裕を持たせているということだと思うのですけれども、小学校も中学校も５人ずつということで、一方で小学校は６年で中学校は３年ということで、どの程度の増減が発生するのかというのは、やや、小学校と中学校で違うのかなというふうにも思うのですけれども。","respondent":"勝亦学務課長","answer":"小学校６年間、中学校３年、後期課程３年間ということで、その課程の１年生、７年生でないときの転入ということで、先ほどもありましたけれども、新しいマンションが建つですとか、そういったことを含めて、転入の中には様々な学年の方が入ってまいりますので。","voiceIndex":44,"id":"exchange-016"},{"speaker":"松本委員","kind":"質問","question":"余りそこを詳しくは把握されていないということなのでしょうか。例えばタワーマンションが建つ場合というのは、大幅に増えるというのは分かると思うのですけれども、それ以外の一般的な、状況の中で大体傾向としては、推移で言うと１年間に入ってくるのが大体このぐらいなどというデータはどうなのでしょうか。お願いします。","respondent":"有馬庶務課長","answer":"年間でのデータというと特色がありまして、今、手元にある中で、例えば、昨年の１年生から６年生の人数は１学年こういう人数でした、それが今年の１年生はこういうふうになりましたということで、例えば、令和元年度の４年生が２,５７７人だったけれども。","voiceIndex":46,"id":"exchange-017"},{"speaker":"松本委員","kind":"質問・要望","question":"５人という枠、なぜ確認しているかと言ったら、受入れのゆとりの枠が広ければ広いほど選択肢が逆に狭まるというか、入りたくても入れないという子どもたちも生じ得るのかなというところで、そこは５人という、ある意味きりがいい数字にされているので、そこの部分は精査していただきながら、すぐに、では５人ではなくて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-018"}]},{"id":"topic-03","title":"その他のうち、(1)所管質問","agenda":"その他のうち、(1)所管質問","exchanges":[{"speaker":"吉田委員","kind":"質問・要望","question":"区長からのご答弁でしたが、区としてのお考えを求めた質問だったと思うのですけれども、区としてのお考えが結局はっきり聞き取ることができませんでしたので、改めて、学校としてどのようにお考えか、品川区の教育委員会としてどのようにお考えか伺いたいと思います。","respondent":"工藤指導課長","answer":"昨日、７月６日に都教育委員会から最終の意向調査の通知が示されたところです。それに合わせながら、私どもで今示された内容と、またその詳細について、さらに都教育委員会に照会・確認を行っているところでございまして、現在検討をしています。","voiceIndex":53,"id":"exchange-019"},{"speaker":"吉田委員","kind":"質問","question":"都教育委員会がそのような意向調査をするというようなお話は都のほうから伺っていて、前に品川区にお問合せをしたら、まだそのような調査はないということだったのですが、今検討中ということで、例えばそのときに、学校のＰＴＡの意見を聞くとか、学校の先生の負荷を現場ではどの程度考えているかとか、そういうことを考えた上で結論をお出しになるというふうに考えてよろしいのでしょうか。","respondent":"工藤指導課長","answer":"現状では、昨日示された都教育委員会からの情報を基にしながら、教育委員会として、安全・安心に行うというのが前提ですので、それらを含めまして、現在検討を行っているです。","voiceIndex":56,"id":"exchange-020"},{"speaker":"吉田委員","kind":"質問・要望","question":"一緒に聞いてしまいます。仕様の中身はこの情報だと分からなくて、仕様については教育委員会、所管が決められていると思うのですけれども、入札が進んでいってしまったとして、例えば中止となったときには、それを中止することができるような仕様にされているのかどうか、その辺についても確認させてください。","respondent":"工藤指導課長","answer":"仕様の中身について今お話しできる内容というのがどこまでかというところはありながらなのですけれども、そういったもので、契約のスケジュールが、契約の部署の方で進んでいるというのは、当然、私どもも把握していますので、そういったものがどこで。","voiceIndex":58,"id":"exchange-021"},{"speaker":"吉田委員","kind":"質問・要望","question":"１つ、先生方のことについては、ぜひ、よくよく、校長会を通してということですけれども、なるべく現場の直の先生方のお声も聞いていただきたいと思います。気になっているのは、どんどん進んでしまうと、予定価格１,４００万円になっていますよね。ただ、その仕様の中身については所管がきちんと決めていくということですので、そのことについて伺いました。","respondent":"工藤指導課長","answer":"それを進めている中では、その契約の時期、実際にスケジュールがありますけれども、それに伴いながら、様々な検討を今進めている中で、調整が可能な部分、また、どういったところで、場合によってはキャンセル料等がかかる、かからないということもありますので。","voiceIndex":60,"id":"exchange-022"},{"speaker":"吉田委員","kind":"質問・要望","question":"最後にします。前回、６月の委員会のときも申しましたけれども、都の意向とか、そういうことを勘案しながらということでしたが、ほかの区ではもう既に区として中止を決めたというところもあります。区として決められるのだと思います。これは意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-023"},{"speaker":"安藤委員","kind":"質問","question":"子どもの観戦を中止してほしいという区民の声は、現在何件ぐらい届いているのか伺いたいと思います。それと、子どもの安全に関わる重要な問題なので、教育委員会、ＰＴＡ連合会、校長会などには、先ほど校長会という話もありましたけれども、観戦の是非について意見を聞いたのか、聞いたとしたらどのような意見が挙がったのか、それぞれ伺いたいと思います。","respondent":"工藤指導課長","answer":"この実施に関してのところですが、私ども、今回の連携観戦プログラムですが、これまでも行ってきたオリンピック・パラリンピック教育の中で、様々な学習体験を、特にこの品川区の中でも積み重ねてまいりました。","voiceIndex":64,"id":"exchange-024"},{"speaker":"安藤委員","kind":"質問","question":"そこで３点大きく伺いたいのですけれども、今回の連携観戦で観戦を予定している子どもというのは、結局全部で何人なのでしょうか。そういった声も聞いたので伺いますが、会場でスポンサーがペットボトルを配るので水筒の持込みは禁止されているのだというような、そういう話もしている人がいたのですけれども、事実はどうなのでしょうか。その辺のルールがどうなっているのか伺いたいと思います。","respondent":"工藤指導課長","answer":"授業日ということで計画上位置づけられておりますので、そこでは様々なご意見もいただいて議論をしているという訂正をします。あわせまして、予定している人数ですが、区立学校、幼稚園の５歳児も含めまして、約２万２,０００人を予定しているところです。","voiceIndex":66,"id":"exchange-025"},{"speaker":"安藤委員","kind":"質問・要望","question":"細かいところを聞かせていただきたいのですが、ラッシュ時に移動してしまうというか、通勤ラッシュの時間帯に移動してしまうような午前中の観戦というのがあるのかどうか、その辺を後で確認させてください。","respondent":"工藤指導課長","answer":"最長でも１時間程度の観戦しかできないというところを勘案しながら、ラッシュ時を避けることも連絡していくところです。こちらも含めて、今検討の事項に入っているところです。","voiceIndex":68,"id":"exchange-026"},{"speaker":"安藤委員","kind":"確認","question":"区が定めたガイドラインでは、今、課長がおっしゃったようなことになっているのですよね。これが、確認なのですけれども、五輪期間まで延長継続された場合は、学校連携観戦は中止するという考えでよろしいのか伺いたいと思います。出席停止と欠席というのは何が違うのかなというのが分からなかったので、それも併せて伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-027"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、今の時点で、やはり私は、早い時期に決断をすべきだと思います。やはり、事実上できないということもあります。改めて、子どもたちの何を一番重要視するか。もちろん、苦渋の決断になると思うのですけれども、改めて品川区教育委員会として、中止に向けて必要な手続きをするよう求めますけれども、最後にいかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":73,"id":"exchange-028"}]},{"id":"topic-04","title":"区立児童相談所開設に向けた進捗状況","agenda":"区立児童相談所開設に向けた進捗状況","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"細かいところからなのですが、子ども家庭支援センターは、児童相談所の開設後は同じ建物に入る計画なのでしょうか。その辺を確認したいと思います。それと、別紙資料なのですけれども、これは６月２日の検討委員会の議論を経て作成されたものなのか、それとも、当日検討委員会に出された資料なのかというのが分からなかったので、お伺いします。","respondent":"加島児童相談所移管担当課長、山下子ども家庭支援センター長","answer":"こちら、会議の中ではこれ以上のご意見というのはございませんでしたが、区として受け止めておりますところでは、児童相談所と子ども家庭支援センターの役割分担をしてケース対応を行ってまいりますので、そういった進行管理の面。代表者会議である品川区虐待防止ネットワーク推進協議会、実務者会議としまして２層目で地域分科会、こちらは１３地域センターそれぞれで実施をしております。","voiceIndex":81,"id":"exchange-029"},{"speaker":"安藤委員","kind":"質問","question":"子ども家庭支援センターなのですが、これは現在の建物がありますので、そこで別建物として継続していくというお考えなのか伺います。いろいろ視察などしますと、職員がやはり心身ともに疲弊してしまうというケースが多いと伺いました。３つ目は、この運営計画検討委員会が非公開という、委員会にはこういった形で報告があるのですが、その理由は何かというのを伺いたいと思います。","respondent":"山下子ども家庭支援センター長、加島児童相談所移管担当課長","answer":"今、二葉のほうに所在しておりまして、子ども家庭支援センター、設置・運営をしているのですけれども、今後につきましては、状況としましては、新庁舎も含め移転をするような形での考え方をしております。２点目以降の質問にお答えいたします。職員の心身の疲弊につきましては、私どもも視察等で、視察先の職員からそのような状況が起こり得るということを聞いております。","voiceIndex":84,"id":"exchange-030"},{"speaker":"安藤委員","kind":"質問・要望","question":"分かりました。それは、児童相談所の担当児童福祉司ということになると考えてよろしいのか、伺いたいと思います。もう１つ、最後ですけれども、ある意味、虐待発生を未然に防ぐ家庭支援というのが最も大事なのかなと思うのですね。その点において、児童相談所と子ども家庭支援センターはどのような役割を果たしていくのか、改めてそちらについてのお考えを伺いたいと思います。","respondent":"加島児童相談所移管担当課長、山下子ども家庭支援センター長","answer":"子育て中の保護者の方、子どもご本人、それぞれが悩み事があったときに気軽に相談できるような体制をというところで、現在、子ども家庭支援センターは区が、児童相談所は都が担っておりますけれども、先ほどご説明申し上げましたとおり。今後、（仮称）品川児童相談所ができた場合でも、そちらの調整をしっかり担いまして、運営委員会の委員からもご意見いただきましたけれども、両機関の狭間に落ちるケース等々が発生しないように。","voiceIndex":87,"id":"exchange-031"},{"speaker":"安藤委員","kind":"質問・要望","question":"相談しなかったのが悪いのではというふうにはもちろん言わないでしょうけれども、そういうふうになってはいけないわけで、そういう意味で、児童相談所を置く、独自で作るということで、悩まなくていい、本当に相談してくださいと、行政は味方ですよと言うような体制を作る上でも、ぜひさらに頑張っていただきたいと思いますし、あと、子どもの権利条約という観点が子育て支援に非常に重要というか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":90,"id":"exchange-032"},{"speaker":"松本委員","kind":"質問","question":"先ほど安藤委員からもお話があった、この運営計画検討委員会が非公開のところなのですけれども、やはりこれは公開はしていくべきだと私は考えています。","respondent":"加島児童相談所移管担当課長","answer":"個別のケースですけれども、確かにそういったケース検討を行っているわけではないのですが、議題を示す中で、委員のほうから過去に関わったケースですとか、あとは理事者のほうからそういった発言が出ることもありますので、今の段階では非公開としています。","voiceIndex":92,"id":"exchange-033"},{"speaker":"松本委員","kind":"意見","question":"今、調べたところだと、恐らくこの検討委員会が開かれていること自体は特にウェブサイトに記載がないようにも思われるのですが、そのあたりも、現状どういうふうに区民に対する公開がされているのかというところも踏まえてご答弁をお願いいたします。","respondent":"加島児童相談所移管担当課長","answer":"２点目からのお答えになるかもしれませんが、現在、有識者会議につきましては、確かに委員ご指摘のとおり、ホームページ等には掲載しておりません。","voiceIndex":94,"id":"exchange-034"},{"speaker":"松本委員","kind":"質問","question":"委員長という単語が重複するので、なかなか。私の頭の中のことですが。例えば、弁護士１名となっていますけれども、私も弁護士ですが、弁護士と言っても専門性はいろいろなのですね。そういう意味では、やはりきちんと委員の構成、委員の専門性とか、どういう方たちを選任しているのかというところはきちんと公開されたほうがいいのではないかと思いますが、その点はいかがでしょうか。","respondent":"加島児童相談所移管担当課長","answer":"現在、この委員についても構成、お名前等、公開はされておりませんけれども、この委員会を通じて区立児童相談所設置・運営計画を完成していくに当たり、有識者のお名前等も公開していけるよう、会議の中で調整を図ってまいりたいという。","voiceIndex":96,"id":"exchange-035"},{"speaker":"松本委員","kind":"質問・要望","question":"ありがとうございました。ちなみになのですが、この６月２日に行われた会議ですけれども、会議の開催時間、どのくらい時間が使われたのかというところもお願いいたします。","respondent":"加島児童相談所移管担当課長","answer":"会議の開催時間について、６月２日は１５時から始めまして、１時間半強ほどご意見をいただいたところです。","voiceIndex":98,"id":"exchange-036"},{"speaker":"松本委員","kind":"質問・要望","question":"最後は本当に要望で。できるだけ、このあたりの情報というのは公開していただきたいと考えていますので、引き続き、ここは検討委員会の委員長と相談していただきながら、在り方を考えていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":100,"id":"exchange-037"},{"speaker":"吉田委員","kind":"質問・要望","question":"そのご意見が、区としての考え方に反映されたかをフィードバックする機会は、もう最後の案のところでしかないのでしょうか。次のことになって、これからということだと思いますけれども、これからということであるならば、ぜひそういうことをここで深く議論していただきたいと思うのですけれども、その辺についていかがでしょうか。","respondent":"加島児童相談所移管担当課長","answer":"権利擁護の部分につきまして、これから議題としてどのような提案の仕方をしていくか委員長と話しますので、まだまとまったものがあるわけではないのですけれども、一般質問等でいただいたアドボケイト制度、意見表明支援の件につきましても、今現在。","voiceIndex":101,"id":"exchange-038"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひそのように進めていただきたいと思います。最後に、先ほどの松本委員からのご意見がありましたので、一応、意見だけ言わせていただきたいのですけれども、やはり会議の公開というのは進められるべきかなというふうに思います。ですので、ぜひそこは、ご懸念がおありでしたら一歩ずつでもいいので進めていっていただきたいと思います。最後は意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":103,"id":"exchange-039"},{"speaker":"松澤委員","kind":"質問","question":"２層性というか、併存型というのは、これはやはり連携をとるのがとても難しいという課題が多く、私も勉強会などに行かせてもらうと、お聞きしています。そういった中で、やらないということはないでしょうけれども、どういった部分でそういう連携評価をいうのを図っていくのかというのを教えてください。","respondent":"加島児童相談所移管担当課長","answer":"世田谷区のほうでは、両機関の共通の認識といたしまして、リスクアセスメントの基準を明確にしていたり、両機関で定期的に情報共有する会議を合同開催するなどの機会を設けていると聞いておりますので、私どももそういったものを参考にしながら。","voiceIndex":105,"id":"exchange-040"},{"speaker":"松澤委員","kind":"質問","question":"先行事例の世田谷区さんなど、そういうのを見るのはとてもいいことだと思いますので、お願いいたします。特別区での設置になると、今までは東京都が管理していますので、東京都がやっている中で、そういう情報が全くつながらなくなったり、要は都と区の連携というのですか。","respondent":"加島児童相談所移管担当課長、山下子ども家庭支援センター長","answer":"先行区の例になってしまうのですけれども、都と区で同行で訪問していたりというような取組を行っていると聞いております。我が区においても、その取組につきましては実施に向けて検討が必要と考えているものです。私ども子ども家庭支援センターとしましては、実際に一時保護に至った後、また地域に戻られてくるときに、その児童であったり、またその保護者の方々を支援するという役割がありますので、今現在、私どもとしましては。","voiceIndex":107,"id":"exchange-041"},{"speaker":"松澤委員","kind":"質問","question":"最後に、職員の異動と言いますか、児童相談所の職員というのは、行政の中にあると、ある程度、数年たてば異動してしまう、そういう流れだと思うのですよね。ただ、ここがすごく課題だと。そうすると、職員の異動の周期、これは今話すことではないのかもしれないのですけれども、そういった部分も少し長く見るということも検討の１つなのかなと思っているのですけれども、その辺はどうでしょうか。","respondent":"加島児童相談所移管担当課長","answer":"そういったスーパーバイザーをこの区職員の中から輩出していくためにも、長期的な育成とともに、先ほど申し上げました、様々な職場で業務経験を蓄積していくということ、少し対立に見えるかもしれませんが、そういった道を両立させていくようなことも、今後。","voiceIndex":110,"id":"exchange-042"},{"speaker":"つる委員","kind":"提案","question":"進捗状況ということで、ありがとうございました。会派としても、福岡などいろいろな先行自治体の事例も視察させていただきながら提案もさせていただいて、いろいろな人材の面であるとか、そういったところも伺いながら、また提案をさせていただいて、今、こういう進捗を教えていただきました。","respondent":"加島児童相談所移管担当課長","answer":"３つ目といたしましては、最後になりますが、地域、関係機関、庁内関係部署、区として顔の見える関係がありますので、そういったつながりを生かしながら、緊急対応の前段階から、子どもと家庭に支援が届くよう、児童虐待の防止・早期発見をより強化していけると考えております。","voiceIndex":113,"id":"exchange-043"},{"speaker":"つる委員","kind":"質問","question":"ありがとうございました。そういう意味では、この別紙２の図もありますけれども、これをさらにもう一重、二重、重ねていくのがその重層だと思うのですが、このイメージで言うと、重層と児童相談所、子ども家庭支援センターの役割分担と言いましょうか、連携の在り方というのですか。このあたりというのはどういうイメージを今後持って進めていくのか教えてください。","respondent":"加島児童相談所移管担当課長","answer":"そういったものとして、重層的支援体制整備事業のネットワークの中にかかってくるご家庭、子どもに対してきちんと児童相談所が掲げている業務の役割を果たしていけるよう、今後、庁内で意見、認識を共有してまいりたいというふうに考えております。","voiceIndex":115,"id":"exchange-044"},{"speaker":"つる委員","kind":"提案","question":"個人的には、この重層的支援体制整備事業については、特別委員会を設けて本当に多角的な議論をしていかなければいけないなというふうに、今年度、会派の中で提案させていただいた部分もあるのですけれども、今ご答弁いただいて、本当に複雑に絡み合ったものを、適切に、まさに１人１人に合った形で、制度に人を合わせていくのではなくて、困っている人に制度を当てはめていくと言いましょうか、形作っていく。","respondent":"加島児童相談所移管担当課長、山下子ども家庭支援センター長","answer":"児童精神科医、非常に母数が少ないので、確保が難しいところですけれども、職員のメンタルケアにも関わっていただけるような方をこちらできちんと確保してまいりたいと考えているところです。今現在の時点で、虐待の通告の件数等々、相談の件数等々というのは伸びを示している状況ですけれども、やはりそちらの体制を整備することで、児童相談所の円滑な運営につながる部分もありますので、子ども家庭支援センターの役割として。","voiceIndex":117,"id":"exchange-045"},{"speaker":"つる委員","kind":"質問・要望","question":"ありがとうございました。人材のところについては、本当に大事な部分かなと思います。ＯＪＴではないですけれども、やれるような、それだけの課題が濃いと思うのですね。愛称がいいか、悪いかという、両方側面があると思うのですけれども、例えば品川区でやっていくときに、この子ども家庭支援センターも含めてなのでしょうけれども、そういう愛称みたいなものをつけていく考えというのはどうでしょうか。","respondent":"加島児童相談所移管担当課長","answer":"江戸川区の児童相談所のほうでも、区民公募を図りまして、はあとポートという愛称をつけておりますので、そういった試みについても、今後区のほうで研究してまいりたいというふうに考えております。","voiceIndex":120,"id":"exchange-046"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5038#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":45037,"voices":128}},{"id":"r03-20210707-5","meetingId":"r03-cm07","date":"2021年7月7日","dateIso":"2021-07-07","committee":"総務委員会","time":"午前１０時００分～午前１１時１３分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を34件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"説明に入る前に、各所管委員会における審査結果","agenda":"説明に入る前に、各所管委員会における審査結果","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"そのことで、何といいますか、感謝申し上げるというか、ご苦労さまですというふうに申し上げたいと思います。そのためには、ワクチンの迅速な接種に努めなければいけないし、また、ワクチンだけでコロナを抑え込めるわけではないですから、ＰＣＲ検査を十分にやって、感染者を発見して、それを保護していくということも、依然としてやっていかなければならない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":5,"id":"exchange-001"},{"speaker":"おくの委員","kind":"意見","question":"さらに加えて、事業者の受ける打撃が耐え難いものになっている。そのため、事業者に対する補償もやっていかなければならない。そういう観点が必要になってきていると思います。それで、１つは、ワクチンの接種、例えば６０歳から６４歳の方に関しては、７月２日が予約開始日ということになっているのですけれども、その予約開始日になっても接種券が到着していなかったという声を聞きました。それで……。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":7,"id":"exchange-002"},{"speaker":"おくの委員","kind":"質問","question":"それで、その迅速な接種というところで、十分なことができたのかというところ、その点を伺いたいと思います。それから、ＰＣＲ検査に関して、今の区のやり方というのは、基本的には感染者が出てから、周辺の無症状者を検査するというものだと思います。あるいは、介護・障害者施設の新規入所者に限定した、６月に２回やるとか……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-003"},{"speaker":"おくの委員","kind":"質問・要望","question":"３つ目、事業者の受ける打撃が耐え難いものになっている現状からすれば、持続化給付金や家賃支援給付金の第２弾を、今こそ強く国に対しても求めるべきだし、区としても何らかの形で、区にできる範囲ででも、支援金のようなものを考えてしかるべきだと思うのですけれども、この点、考えなかったのでしょうか。いかがでしょうか。その点を質問したいと思います。","respondent":"黒田財政課長","answer":"３点目の、いわゆる事業者への対応ですが、こちらは、商業・ものづくり課のほうでも様々対応を行っておりますが、区にできることについては対応していきたいと思ってあります。","voiceIndex":11,"id":"exchange-004"},{"speaker":"おくの委員","kind":"意見","question":"電話だけではなくて、接種券を郵送することについて、郵送に一定の日数がかかるにもかかわらず、その郵送にかかる日数を計算しないで予約開始日を設定したというところに、不備があったのではないかという区民のお問合せだったのです。要するに、細かいことになりますが、６月２９日に……。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":13,"id":"exchange-005"},{"speaker":"おくの委員","kind":"質問","question":"ではこれは省略します。それで、４点目、コロナを封じ込めるという戦略目標を持った上で決めるべきではないかと私は思っているのですが、その点はいかがでしょうか。その点にお答えください。","respondent":"古巻総務課長","answer":"コロナを封じ込めるですけれども、区では、ワクチン接種関係、７月から２名の職員を異動で追加しておりますし、また兼務発令で３名の職員を兼任させております。そういった意味で、コロナ対策についてはしっかりと進めていると認識しております。","voiceIndex":15,"id":"exchange-006"},{"speaker":"田中委員","kind":"質問・要望","question":"まず総合審査ということです。どういった議論があって、皆さんが賛成されたのかといった報告を欲しいと思いますが、今後の委員会運営の上で少し検討していただきたいということを、要望したいと思います。質問します。その増設というのは、やはり予約のための増設という、それだけの機能ということで間違いないのか、確認をさせてください。","respondent":"黒田財政課長","answer":"いわゆるコールセンターについては電話番号が１つというところで、そちらのほうを５０回線、５０人体制でやっていたところ、１００回線大丈夫ということで、予約に限らず、コールセンターで対応できる内容については、コールセンターのほうで受けられるというところで。","voiceIndex":17,"id":"exchange-007"},{"speaker":"田中委員","kind":"質問・要望","question":"そういうのもこのコールセンターで受けられるのか、それはまた別なのかというところをお知らせいただきたいのですが、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-008"},{"speaker":"田中委員","kind":"質問・要望","question":"今のご答弁で大分安心しました。ただ、この中に、また今も少しずつされていますが、相談窓口を周知するようなポスターの掲示とかというのは、含まれていないのでしょうか。そこの確認をさせていただきたいのと、要望として、今、自死を止めるための相談窓口の周知が、連絡先、相談窓口がこんなにありますというふうな電話番号がたくさんあるのですけれども、それだと自分がどこに当たるのかが分からない。","respondent":"黒田財政課長","answer":"１点目のポスターの掲示の経費のお尋ねですが、いわゆる自殺予防対策事業につきましては継続的に行っている事業でありますので、そういった周知は、いわゆるＳＯＳカードの配布等を含めまして継続的な事業で行っておりますので、今回の補正予算では。","voiceIndex":22,"id":"exchange-009"},{"speaker":"田中委員","kind":"質問・要望","question":"これは要望でとどめます。今回の補正の自殺企図者支援事業、このインターネットゲートキーパー事業については、子どもたちに対して何かしらのお知らせをするのか、それとも……。具体的になってしまうと答えられないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-010"},{"speaker":"田中委員","kind":"確認","question":"そのバナーでということですが、この事業の契約先というか、この方たちはこれまでの実績とかがあって、そのバナーによって、これまで子どもたちや自死を考えていた方たちとつながって、ケアというか、次につなげることができたという、そういう実績があるのかというところの確認はできますでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-011"},{"speaker":"渡部委員","kind":"質問","question":"一番肝となるのは、住民サービスの低下を起こしてはいけないわけで、例えば接種券が届かないだとか電話がつながらないだとか様々なことがあって、例えば瞬間的に何か手を打たなければいけないときというのは、一般財源から充ててでも、僕は少しやる必要もあるのかなと思ったりするのだけれども、その辺はどういうやり取りがあって、どういう考え方の下で。","respondent":"黒田財政課長","answer":"そういった意味では、区として必要な事業を編成しておりますので、財源については、もしいわゆる特定財源がないとすると、その場合については、必要な事業は一般財源を取り崩して行うというような考え方で予算編成をしています。","voiceIndex":32,"id":"exchange-012"},{"speaker":"渡部委員","kind":"質問・要望","question":"大事なのは本当に区民サービスの低下を、そこを遠慮してと言ったらおかしいけれども、ここまでやって、これ以上行ってしまったらとかでも、何か手を当てられることがあったら手を当ててほしいと思います。電話の台数がどうこうとかという話では全くないのですけれども、しっかりと、使うべきところというのは一般財源の活用も考えた上で、この難局を乗り切っていただきたいということは、要望だけします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-013"},{"speaker":"須貝委員","kind":"質問・要望","question":"このように振り回されて、しょっちゅう、では、足りない、接種券がどうだ。これは、結局全世界でこのワクチン接種を６割、７割の人が受けるまでは、抗体ができるまでは収まらないと私は思いますので、まして変異ウイルスを考えたら、相当長い期間かかると思いますので、その辺、対応をよろしくお願いしたいと思います。意見だけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-014"},{"speaker":"たけうち副委員長","kind":"質問","question":"すみません、手短に。選挙費の寄附金２０万円ですが、これは私の記憶が間違いなければ、同じ方に、もうかなり長年にわたってやっていただいていると思うのです。もちろん全部、この方に限らず、寄附をしていただいている方等しく尊いわけですけれども、長年たしか同じ金額をずっとやっていただいているような気がするので、そういうことに対する考えが何かあれば教えてください。","respondent":"齋藤選挙管理委員会事務局長","answer":"投票率に寄与したかどうかにつきましては、少し分からないところもあります。表彰につきましては、１００万円を超えると功労の表彰をするという基準がありますので、昨年度表彰させていただいたところです。","voiceIndex":36,"id":"exchange-015"},{"speaker":"たけうち副委員長","kind":"質問・要望","question":"分かりました。特定のというあれではないけれども、やはり本当に尊いなと考えています。ぜひ大事にしていただいて、しっかり対応していただければなと思います。要望だけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-016"},{"speaker":"おくの委員","kind":"意見","question":"コロナについての品川区の一番の問題点は、先ほども言いましたけれども、コロナを抑え込んでいくという戦略を持てていない点にあると思います。それが、ワクチンの接種や検査、それから十分な補償、あるいは生活支援という点についてのコロナ対策の内容が、非常に不十分なものになっているという点に表れていると思います。しかし、それぞれの事業自体は必要なものだと思いますので、賛成いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":43,"id":"exchange-017"}]},{"id":"topic-02","title":"冒頭に申し上げましたとおり、取り上げる順番を変更し、(8)令和３年７月４日執行東京都議会議員選挙の結果","agenda":"冒頭に申し上げましたとおり、取り上げる順番を変更し、(8)令和３年７月４日執行東京都議会議員選挙の結果","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"不在者投票のところで、先ほどご説明がありました、感染された方が郵便等で投票を行ったということですが、そこを具体的に教えていただきたいと思いまして、感染者にどうやって郵便……。ごめんなさい。具体的な投票方法を教えてください。","respondent":"齋藤選挙管理委員会事務局長","answer":"感染されている方は、私どもで１５１人ということで、その期間に投票できそうな方が１５１人ということは、保健所から確認しております。その方に、投票用紙の請求方法や手順をご案内しております。","voiceIndex":51,"id":"exchange-018"},{"speaker":"田中委員","kind":"確認","question":"投函に行くということですか。そこのところを確認します。","respondent":"齋藤選挙管理委員会事務局長","answer":"したがいまして、ご家族に感染させたくない、友人・知人にも感染させたくないし、知られたくないというお気持ちもあって、少し投票率がよくなかったのではないかと考えております。","voiceIndex":53,"id":"exchange-019"}]},{"id":"topic-03","title":"伊藤学園屋内運動場空調設備設置その他機械設備工事請負契約","agenda":"伊藤学園屋内運動場空調設備設置その他機械設備工事請負契約","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"こういうふうにガス式ヒートポンプエアコンを導入したのは、どういうことからなったのか、教えてください。それから、全熱交換器更新工事で、普通教室３３教室を更新するとありますが、まだ新しい学校だと思うのですが、これは更新しなければいけないのか、それとも、今回ヒートポンプエアコンに関して、これを導入するからこちらも交換器を更新するということなのでしょうか、教えてください。","respondent":"小林施設整備課長","answer":"私から、一般的なガス式といわゆる電気式について、メリットとか違いとか、その辺のところかと考えていますけれども、やはり室外機の大きさも異なりますし、あるいは、電気ですと受変電設備の状況がございまして、既存の受変電設備でそのエアコンを動かすことができるかどうか。","voiceIndex":62,"id":"exchange-020"},{"speaker":"須貝委員","kind":"確認","question":"ということは、最初のガス式ヒートポンプのほうですが、こちらのほうが、いざとなったら空調機を動かす能力があるということで、費用等は結構かかると思うのですが、取りあえず、いざというときに使えなければどうにもならないので、こちらを導入したということですよね。その辺の確認だけお願いします。","respondent":"小林施設整備課長","answer":"電気式につきましては、やはり霜取り運転というのがございまして、家庭用のエアコンもそうだと思いますが、いわゆる暖房が止まってしまって、暖房効率が落ちるということも聞かれているところですので、一概に費用だけ考えた中では。","voiceIndex":64,"id":"exchange-021"}]},{"id":"topic-04","title":"品川学園屋内運動場空調機設置機械設備工事請負契約","agenda":"品川学園屋内運動場空調機設置機械設備工事請負契約","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"すみません、さっき少し聞き忘れたのですが、今回、こういうふうにヒートポンプ式でやるというお話で今進んでいますけれども、ほかの学校で、もう既にヒートポンプ式ではないものを設置してしまっていると思うのですが、その辺はどうなのですか。それとも、そちらもやはり近々に……、近々というかこれから、設置したのですが、変えていくという方向性なのですか。それだけ教えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-022"},{"speaker":"須貝委員","kind":"確認","question":"今まで、いろいろな学校の体育館云々でつけているではないですか。それも全部ヒートポンプ式でしたか。それだけ確認してください。分かる範囲で教えてください。","respondent":"小林施設整備課長","answer":"私の知る限りでは、ヒートポンプ式が入っているところです。","voiceIndex":73,"id":"exchange-023"},{"speaker":"田中委員","kind":"意見","question":"答えられる範囲でいいのですが、工期が９月３０日とあるのは、「まで」なのかというところと、あと、子どもたちへの影響というのがどうなのかといったところ、これをお知らせいただけますか。","respondent":"小林施設整備課長","answer":"所管に話を聞きましたところ、武道場につきましては８月中に工事を終わらせて、アリーナにつきましては、９月の中旬頃までどうしてもかかってしまうという話ですので、その辺は学校行事等に支障がない中で、学校等と調整をして。","voiceIndex":75,"id":"exchange-024"}]},{"id":"topic-05","title":"順番を変更して(6)に参ります。(6)大原小学校外壁改修その他工事請負契約","agenda":"順番を変更して(6)に参ります。(6)大原小学校外壁改修その他工事請負契約","exchanges":[{"speaker":"田中委員","kind":"確認","question":"これもまた工期が９月３０日ということで、そこの確認と、あと、やはり子どもたちへの影響の部分を少し教えてください。夏休み中でも、子どもたちはすまいるスクールで学校に行ったりなどもありますので、そういうところへの影響についてお知らせいただければ。答えられる範囲で構いません。","respondent":"小林施設整備課長","answer":"所管に確認したところ、外部足場を設置して外壁を塗ったり屋上の防水をやったりする、いわゆる窓が開けられない時期の工事につきましては、夏休み期間中にやるという話を聞いておりますので、授業が始まるときには、外部足場はなくなっている状況と聞いております。","voiceIndex":81,"id":"exchange-025"}]},{"id":"topic-06","title":"台場小学校空調設備改修工事請負契約","agenda":"台場小学校空調設備改修工事請負契約","exchanges":[{"speaker":"田中委員","kind":"確認","question":"すみません、台場小学校も同じく、工期と、あと子どもたちへの影響の部分についてだけ、確認させてください。答えられる範囲で。","respondent":"小林施設整備課長","answer":"こちらも今までと同様でございまして、９月１７日はあくまで検査が含まれる期間です。学校運営に関わる教室の部分につきましては、夏休み工事期間中に行うと聞いております。","voiceIndex":87,"id":"exchange-026"},{"speaker":"田中委員","kind":"確認","question":"３７ページを見たときに、今回工事範囲というのが幾つかあって、でも、工事しないところもあるということで、そこをすまいるスクールの子どもたちは利用するという考え方でいいのか。答えられる範囲でいいのですが、危惧していることは、夏休み中にエアコンとかが使えず、熱中症になったりしないかということとかを心配していまして、そうではないと思うので、そこら辺の確認をさせてください。","respondent":"小林施設整備課長","answer":"こちらの台場小学校の空調方式につきましては、今回、工事を行う部分と、いわゆる普通教室の部分が別の系統と聞いておりますので、すまいるスクールをどこでやるかということは把握しておりませんが、エアコンが効く部屋は、工事中であってもあると認識しております。","voiceIndex":89,"id":"exchange-027"},{"speaker":"たけうち副委員長","kind":"意見","question":"このフード付ガラリ改修工事、防音型となっているのですが、分かればで結構ですが、いわゆる近隣から少し声がとか、何かそういうのがあってやっているのか、それとも逆に、外からの音が気になるのでやっているのかとか、何か分かれば。","respondent":"小林施設整備課長","answer":"特に近隣の皆様から何か苦情があるという話を聞いているところではございませんが、メインは外からの音だとは聞いております。","voiceIndex":91,"id":"exchange-028"}]},{"id":"topic-07","title":"続きまして、再度順番を変更して(5)です。(5)豊葉の杜学園・二葉すこやか園校庭整備工事請負契約","agenda":"続きまして、再度順番を変更して(5)です。(5)豊葉の杜学園・二葉すこやか園校庭整備工事請負契約","exchanges":[{"speaker":"田中委員","kind":"確認","question":"お答えいただける範囲でいいのですが、契約の中で、人工芝については、マイクロプラスチックなどの環境負荷の影響についても、きちんと考えられた上での契約だったのかというところが１点と、あと、人工芝には、夏場になると熱くなってやけどしそうになるといった声だったり、静電気が発生するといった声が子どもたちからあったのですけれども、そういったものも改良された人工芝の契約なのかという部分を。","respondent":"小林施設整備課長","answer":"ですので、今回の発注についても、同様なことかと考えております。","voiceIndex":97,"id":"exchange-029"},{"speaker":"田中委員","kind":"質問","question":"区として、やはりこれからも人工芝化をしていく方針なのかどうかというところ、そこのところをもし教えていただけたら。","respondent":"渡辺委員長、小林施設整備課長","answer":"多分学校のことを想定されていると思います。「区として」と最初にあったので、公園等もいろいろありますが、それはそれぞれ所管がありますので、それを踏まえて、施設整備課長で答えられる範囲で。やはり各所管で考えもありますので、その所管の考えに基づいて我々は工事発注をしていますが、やはり、何でしょう、いろいろと近隣からの要望とか、あるいは、生徒の活動時の足腰の身体面の負担軽減とか、様々な理由がある中で。","voiceIndex":99,"id":"exchange-030"},{"speaker":"須貝委員","kind":"質問","question":"未満というのは、結局、入札予定価格、区で下限幾らということで、それ以下のところは落札できませんよということなのでしょうが、この会社の実績というのは、そういうものはあるのでしょうか。そこは調べたのでしょうか。別に意図してやっているわけではなく、決まっている最低価格があるのですが、その辺について少しご見解と、この会社の実績の有無というのを、もし分かれば教えてください。","respondent":"東野経理課長","answer":"こちらの会社につきましては、制限付き一般競争入札の公告の段階では、類似工事実績５０％以上ということで、予定価格の５０％以上ということで募集をしておりますので、それなりの実績があった会社ということになります。","voiceIndex":102,"id":"exchange-031"},{"speaker":"須貝委員","kind":"質問・要望","question":"意見だけなのですが、何かそういうふうに努力しているところが、逆に報われなくなるような状況……。コストというのは、やはりそれぞれ企業努力によって様々変動されると思うので、何かその辺についても、もし今後、何か検討されるようならば、私は、できるようならばしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":104,"id":"exchange-032"},{"speaker":"渡部委員","kind":"質問","question":"例えば人工芝だとすれば、人工芝の耐用年数はどれぐらいで、どういうふうに更新していくのだみたいなのがある程度決まっていて、動いていっているものなのかだけ、教えてください。","respondent":"小林施設整備課長","answer":"特に人工芝につきましても、やはり劣化の状況、学校で使う場合もありますし、地域の方が使うこともありますので、そちらの劣化の状況を見ながら、それに応じた改修を進めていると考えております。","voiceIndex":105,"id":"exchange-033"}]},{"id":"topic-08","title":"品川区東五反田五丁目付近再構築その２工事請負契約","agenda":"品川区東五反田五丁目付近再構築その２工事請負契約","exchanges":[{"speaker":"田中委員","kind":"質問","question":"３社のうち２社も辞退されているというのに何となく違和感を持ってしまったというか、偶然なのかもしれないですけれども、その何かタイミング的なものとか、どういう経緯だったのかというところを教えていただければと思います。","respondent":"東野経理課長","answer":"その後、期日を決めまして、入札期日に札入れをしていただくという形になるのですが、そのタイミングで、辞退届という形で出していただくというところになりますので、入札金額を入れている会社と、辞退届という形で出された会社とが、同じタイミングであったという形になります。","voiceIndex":111,"id":"exchange-034"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2204#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":24921,"voices":120}},{"id":"r03-20210708-14","meetingId":"r03-cm07","date":"2021年7月8日","dateIso":"2021-07-08","committee":"行財政改革特別委員会","time":"午前１０時００分～午前１１時３１分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"今回いろいろな会議体もあるので、ちょっと立て分けが難しいのですけれども、まだちょっと伺っていないことがあって、今日、理事者の方もいらっしゃるので、もし分かれば教えていただきたいのですが、私、議員になってまだ１０年なので、ちょっと成り立ちがよくわかっていないのですけれども、今、４階、５階、６階というふうに議会の機能が分かれているのですが、どうしてこういうふうな形になったのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":5,"id":"exchange-001"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ちょっと実態はわからないですけれど。ですから、そのためには、やはりワンフロアに集結しなければいけないのかなと思っているのですけれども、ちょっとほかの自治体もやはりそういう形、また階層についても上、特に議会の独立というところからそういうふうに、いろいろなものが、機能が混在してしまうと、ちょっとそういうところが失われるのかなというのがまず１点、その点を申し上げたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":8,"id":"exchange-002"},{"speaker":"あくつ委員","kind":"質問","question":"ではついでに、会派の諸室のことについても。川崎市の基本計画を見ると、諸室の面積については総務省の基準だと「議員１人あたり５０m2（議場を含む）」となっているのですが、川崎市の場合は５０m2掛ける６０人いらっしゃるということで、３,０００m2。もし把握されているのであれば、今、議会の面積というのは足りているのか、足りていないのか、わかれば教えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":10,"id":"exchange-003"},{"speaker":"あくつ委員","kind":"質問・要望","question":"わかりました。別の会議体等でも多分これからいろいろな検討をされると思うのですけれども、そのあたりの基準、生きているのか、生きていないのかわかりませんけれども、そういうのもあればぜひお示しをいただきたいなと、１つの議論の材料としていただきたいなと思っています。では、ついでだからもう一つだけ。いっぱいあるのですけれども、１つだけ言います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-004"},{"speaker":"須貝委員","kind":"質問・要望","question":"この中で、中野区が施設の長寿命化ということを取り上げています。今回新庁舎を造ったら、やはり目標として８０年から１００年は使えるような仕組みづくりを考えていただきたいと思います。そして、１３ページですか、世田谷区の側面図がありますけれども、議会機能が上層階のほうに設けられております。以上、要望というか、感想といいますか、一応意見だけ言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-005"},{"speaker":"あくつ委員","kind":"確認","question":"確認なのですけれども、上層階に議場が置いてあるところが多いというのは、先ほどのご説明でもありましたけれども、要するに区民の方が行政機能を使いやすいように行政機能は下層階にして、独立という意味もあるのですけれども、そんなに議会のほうにはお越しにならないから上層階にしていると、こういう意味でよろしかったのですか。ちょっとそこのところだけ確認を。どうして上層階にしているのか。","respondent":"濱中庁舎計画担当課長","answer":"建物ゾーニングにおきまして、こういったある程度の階層になっていく中で、区民の窓口というものを低層階に置いて、さまざまな福祉の方や子育ての方、またライフサイクルコストで急いでやりたい方ですとか、そういった来庁者の方が窓口に多く来られるという調査を見て。","voiceIndex":15,"id":"exchange-006"},{"speaker":"塚本委員","kind":"質問","question":"電源については今でも非常用の電源というのは設置されていると思いますけれども、発電力というのですか、どのぐらいあればいいのかということも含めて、災害対策時にしっかり対応できるような整備というのが必要なのではないかと思うのです。インフラ系のところについての、電源とか水とかの考え方というのをお聞きしたいというのが１つ。その２点をお伺いしたいと思います。","respondent":"濱中庁舎計画担当課長","answer":"そうした意味では高い耐震性を持ちまして、また浸水対策など、まず建物性能をしっかりと確保していく。非常用電源のバックアップ機能というものも確保しまして、区民の安全・安心を支える庁舎としていくことが防災機能として重要なことだと認識しております。","voiceIndex":17,"id":"exchange-007"},{"speaker":"塚本委員","kind":"意見","question":"しっかりご検討していただけるというご答弁だったと思いますので、期待をするではないですけれども、ある意味最新鋭というか、なるほどと言えるような形にしていっていきたいなというふうに私も思っておりますので、今後ともよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":19,"id":"exchange-008"},{"speaker":"芹澤委員","kind":"提案","question":"３点お伺いします。最初に、６ページの豊島区のところで、防災拠点機能の強化というところに、「災害と同時に機動力を発揮できる新庁舎」というのが書いてあって、機動力を発揮するというのは、どういった内容なのかが、もしわかれば教えていただきたいのが１点。もう一点、これは要望に近いのですけれども、今の庁舎で議会活動でもそうですけれども、応接室が結構広過ぎるかなというのがあって。","respondent":"濱中庁舎計画担当課長","answer":"いろいろ柔軟に動かしたいということであれば、パーテーションや何かで、可動式ではないですけれども、部屋の設計が柔軟に変えられるようなことも想定できるかなというところを、今後検討していきたいと考えています。","voiceIndex":20,"id":"exchange-009"},{"speaker":"西村委員","kind":"質問","question":"いろいろな区の状況を教えていただき、すごくわかりやすいのですが、２０ページの江戸川区の来庁者の要件に応じた窓口のところで、品川区でもご検討いただいているかどうかお伺いしたいのです。","respondent":"濱中庁舎計画担当課長","answer":"窓口のあり方につきましては、昨年度ワンストップ窓口ＰＴ等でも現状の課題等を洗い出しまして、基本計画に向けてどういった窓口がよいのかというものを、他自治体の先進事例を見ながら今後検討していきたいと考えています。","voiceIndex":22,"id":"exchange-010"},{"speaker":"せお委員","kind":"質問・要望","question":"２点お伺いしたいのですけれども、まず基本構想とかを見ていて、例えば区民にとってわかりやすいとか、防災機能だったり、環境にやさしいというところというのは、他区でも必ずやられていて、ちょっと言葉は悪いのですけれども、当たり前というか、私が言うまでもなく、必ず機能として入れてくださると思ってはいるのですが、それとは別に品川区らしさというか、品川区らしい機能だったりとか。","respondent":"濱中庁舎計画担当課長","answer":"豊島区の中でどういった意見があるのかというのは、ちょっとわからないところですが、上にマンションができることによって費用負担を抑えられたというところが豊島区の中の特徴としてあるかなというふうに認識しております。","voiceIndex":25,"id":"exchange-011"},{"speaker":"せお委員","kind":"質問","question":"豊島区のほうは、これを品川区でやられるとちょっとなと思ったので、何かご意見があるのかなと思ってお聞きしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-012"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"その段階、段階が。そういうことが構想なのか、どこの段階というのがあるではないですか。それから中小企業センターだって、どこの段階でどう入れ込むのかとか、入れ込まないとか、判断するのか、あるではないですか。この地域の全体を見渡すと、必ずそういうことも頭の中には入るのでしょうから、それはどこの段階でそういうことを判断しなくてはいけないのかというところも教えていただきたい。","respondent":"榎本総務部長、濱中庁舎計画担当課長","answer":"いろいろな構想、計画の段階があるのですけれども、例えば、今、委員に事例として挙げていただいた別棟にするという話になると、今現在、もうちょっとなかなか難しいかなという感じはあるのですけれども。議場の設計の構想段階、計画段階、また基本設計段階の内容ですが、自治体によってまた変わってくるところですが、一例ですと、基本構想段階では議場は多目的な利用を検討していくという方針を出されて。","voiceIndex":28,"id":"exchange-013"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それは構想の段階で打ち合わせをしておかないと多分できないだろうから、これは構想の段階でいいのですかというのが質問。結構昔だと、例えば法務局の移転の話もあったり、鵜の木に１つにするみたいな話もあったし、それこそ税務署が来るという話もあったりというのもあるではないですか。議会だって法務局はなくならないでくれと毎回要望を出したりしていた時期もあるではないですか。","respondent":"榎本総務部長","answer":"要は、希望する機能とか耐過重とか、いろいろ問題がありまして、かなり大きな面積が必要だというふうに聞いておりますので、そういった意味では、ちょっと難しいかなと思っていますけれども、それも基本構想の段階できちんと素案の中に盛り込んでいきたいと思っています。","voiceIndex":31,"id":"exchange-014"},{"speaker":"石田（秀）委員","kind":"質問","question":"そうすると、あとは、議会機能のさっきの部分は、構想はある程度一緒の中で、どうしても上層階になるのだろうな、吹き抜けがあるし、希望を言えば多分上層階しか取れないのだろうなと思うけれども。そういう理解でいいのですか。","respondent":"榎本総務部長","answer":"そういう理解で結構です。","voiceIndex":33,"id":"exchange-015"},{"speaker":"大倉委員","kind":"質問・要望","question":"その点については、今回は新庁舎のことなので、そこまでは考えていないのかもしれないのですが、その辺を含めて少し検討されたらいいのかなと思ったので、それについて教えていただきたい。その辺については、そのように検討されるということだったので、意見として言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-016"},{"speaker":"大倉委員","kind":"意見","question":"いろいろ検討していただいて、やっていただけるということで。例えば、先ほどの品川区らしさのところで、商店街が多いというところでは、そういう商店街の方と連携してマルシェではないですけれども、飲食店が定期的に何々商店街の何々物産展みたいなことができてもおもしろいのかななどというのも、お話を聞きながらちょっと思ったので。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":39,"id":"exchange-017"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"初めに、１回目が行われました品川区新庁舎整備基本構想・基本計画策定委員会の傍聴の件なのです。区民の皆さんが使いやすい、利用しやすい、また職員の皆さんが働きやすいということと、環境問題や防災の拠点ということは、やはり区役所としてはやっていくべき、リードしていくべきところでもあると思いますので、そういったところは進めていただきたいというふうに思います。","respondent":"榎本総務部長、濱中庁舎計画担当課長","answer":"この土地を有効活用して区のためにどう使うかという形でずっと検討してきておりますので、そういった意味でこの土地区画整理事業を使って隣に建てられるというのは絶好条件だと考えています。情報公開ということで、今回区民のアンケートを取らせていただくのと、また今後、新庁舎整備ニュースも発行しまして、区民の方に見ていただけるホームページの公開、また図書館や地域センター、また庁舎でもニュースを置いて。","voiceIndex":42,"id":"exchange-018"},{"speaker":"石田（秀）委員","kind":"確認","question":"すみません、もう一点だけ。ちょっと先ほどのことで確認なのだけれども、食堂と言っていいのか、レストランと言っていいのか、そういう部分と、コンビニとカフェ。例えば、食堂というとバックヤードがすごく広くなってしまうから、すごく広いスペースが必要になるではないですか。カフェとコンビニだったらスペースが要らないではないですか。","respondent":"濱中庁舎計画担当課長","answer":"食堂やレストランやカフェについては、区民協働の交流の機能であったり、その他の機能という形で分類している自治体が多いところですが、大体そういったところは、構想段階ですとそういった機能は大体これぐらいだろうというふうに出しまして、計画段階で実際に食堂が必要だ。","voiceIndex":45,"id":"exchange-019"},{"speaker":"須貝委員","kind":"質問","question":"そちらは有識者をはじめ、今検討を、さまざま議論しながら進んでいく。今、この行財政改革特別委員会において今日を含めて４回議論をするということなのですが、こちらでも深くいろいろなことを取り上げて議論していっていいのですか。３回あるのですが、どのようなお考えで進めていかれるのか、またまとめていかれるのか、どこまで議論していいのかというのを教えていただければありがたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-020"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6112#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":28446,"voices":53}},{"id":"r03-20210709-19","meetingId":"r03-cm07","date":"2021年7月9日","dateIso":"2021-07-09","committee":"災害・環境対策特別委員会","time":"午前１０時００分～午後 ０時３３分","status":"正式会議録","sourceType":"formal","overview":"災害・環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を67件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"おくの委員","kind":"意見","question":"言ってみれば、ＣＯ２の排出の原因になっている部分に建物があるというその分析と、それから原因部分を分析するときに一応念頭に置いているのは、対策をどうするかということと両にらみで原因部分を見ていくことになると思うのです。その趣旨をご説明願えればと思います。","respondent":"河内環境課長","answer":"そういったことから、身近な点が１つある点。それから、建物ですが、設備は例えば１５年程度だとか、建物そのものについては３０年程度だとか、一定に寿命が来ます。その際に、こういった高効率の機器などに買い替えるチャンスが生まれます。","voiceIndex":5,"id":"exchange-001"},{"speaker":"おくの委員","kind":"質問","question":"なるほど。例えば、５番の(1)では、低公害車買換え支援事業が対策に上がっているわけですよね。これは建物ではないですよね。そうすると、原因において建物というものを抽出しておきながら、対策においては、原因において抽出した建物というカテゴリーがあまり生かされていないのではないかというふうにも思ったのですけれども、いかがでしょうか。","respondent":"河内環境課長","answer":"そういった意味で、多様な施策を用いながらＣＯ２の削減に向けてという点で、こういった例示をさせていただいたという点です。","voiceIndex":7,"id":"exchange-002"},{"speaker":"おくの委員","kind":"質問","question":"建物は１つの手がかりになるとは思います。思いますが……、分かりました。ＺＥＢについては、私、今のような発想をしているのですけれども、原因と対策というのは対応関係にあって、明示していなくても、原因を考えるときには対策も念頭に置きながら考えられているのだろうというようなことなのですけれども、ＺＥＢについては、原因との関係、どういう位置づけで考えられているのでしょうか。","respondent":"河内環境課長","answer":"そしてＺＥＢという用語自体は聞き慣れないものかと存じますが、その集合体として全体を見て、建物としての効果を上げるというふうな仕組みのものとして理解していただければ、ＣＯ２の削減に向けて有効なツールであることがご理解いただけるのではないかと考えております。","voiceIndex":9,"id":"exchange-003"},{"speaker":"たけうち委員","kind":"質問","question":"１ページの３番の区有施設における再生可能エネルギーへの切り替えについてということで、これは、いわゆる再生可能エネルギーを使った電気への切替えということで、今までもいろいろ学校とかで、一部やってきたと思うのですけれども、そうすると、このコスト的には、電気代ですか、これがやっぱりちょっと上がってしまうものなのかどうなのかというところ、それから。","respondent":"河内環境課長","answer":"これは容量に応じて消費電力が違うと思いきや、一番いいのは、大型の５００ｌ以上のものの方が消費電力が少ないとか、そういった情報も併せて、買った後の維持費も含めまして、そういった情報を環境交流館なども含めまして区民の皆さんに情報発信、それから。","voiceIndex":12,"id":"exchange-004"},{"speaker":"たけうち委員","kind":"質問","question":"そうすると、家庭の省エネ家電について、ちょっと私の質問の仕方が悪かったのかもしれないですけれども、委託業者に委託をして実態をあらあらつかんでいくということですけれども、国とか都のほうから、例えばこういった部門については、こういった更新が随時進んでいくので、これくらいの係数をという、何かそういう示しがあるのかどうか、決まりがあるのか、そういうものがなくて。","respondent":"河内環境課長","answer":"どういう電気を使われているかという点につきましては、今後の把握に努めたいですが、一定ボリュームも把握していますので、そういった目標に向けまして進めていきたいと考えています。それから、ＺＥＢの説明で、紛らわしくて申し訳ございませんでした。","voiceIndex":14,"id":"exchange-005"},{"speaker":"吉田委員","kind":"確認","question":"私から、最初、細かいところですけれども、区有施設における再生可能エネルギーへの切り替えについての、上から３番目の施設名が「防災センター」というふうになっておりますが、これは第二庁舎全体、防災センターというと、その一部、第二庁舎はなぜ切り替えができたのかと伺ったときに、本庁舎の分のサーバーとかが全部第二庁舎にあるので、電力の使い方が安定しているということだったので。","respondent":"河内環境課長","answer":"そういったところを用いまして、交流館の中では、講座や説明会などを含めまして、事業者や区民の皆様に対しまして、しっかりとこういった有効策について周知徹底を図りたいです。","voiceIndex":17,"id":"exchange-006"},{"speaker":"吉田委員","kind":"質問・要望","question":"品川区の契約は、ごみ発電を１０％以下に抑えるという内容になっているのを確認しておりますが、その会社の選定の仕方とか、そういうことも今後はぜひ進めていくべきだと思うのですけれども、今、その先の東品川文化センターから先は契約書の中身を確認していないので、どういう方向、ＲＥ１００で大丈夫ですよねというのと、それから、その辺の会社の選定の仕方、先ほどいろいろな。","respondent":"河内環境課長","answer":"発電システムにおけます、今、パーム油の話も出ましたが、発電のやり方によりましては、輸送や、それからやり方について、二次的なＣＯ２の発生を要するものも出てこようかと思いますので、そういったものを精査しながら、全体的に正味のＣＯ２削減に向けて。","voiceIndex":19,"id":"exchange-007"},{"speaker":"吉田委員","kind":"質問・要望","question":"最後に意見ですけれども、本当に難しいことで、品川区単体だけでできることではないと思いますけれども、ぜひその方向で進めていっていただきたいと思います。これは意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"４番の太陽光発電システムについてですが、買取価格の問題とかもあると思うのですけれども、令和２年度は、家庭用が若干増えているのですけれども、この背景とかが何かありましたらお聞かせいただきたいと思います。それから、業務用というところは、ほとんどないような状況。令和２年度も１件だけということですが、これが進まない理由は何なのか伺いたいと思います。","respondent":"河内環境課長","answer":"今後、区有施設におきましても、こういった検討を進めながら、全体のＣＯ２の削減に向けて取組んでまいりたいというふうに考えているところです。","voiceIndex":23,"id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それから助成がすごくがくっと下げられて、私はこれは国の原発政策によって太陽光発電が抑制されたということから来ているものだと思うのですけれども、改めて、これから原発を抑えて再生可能エネルギーのほうに変えていくという点では、太陽光発電を区の戸建住宅のところもどんどん進めていくことが大事だというふうに思っていますので、ぜひ補助金の復活とかも、さらに元に戻していただいて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-010"}]},{"id":"topic-02","title":"請願・陳情審査","agenda":"請願・陳情審査","exchanges":[{"speaker":"鈴木（博）委員","kind":"質問","question":"今、課長からのご説明を伺ったのですが、品川区の環境対策、環境基本計画は、国よりもむしろ進んでいるのではないかというような印象を持ったのですが、その具体的な国との違いとか、品川区は今、いろいろと積極的に非常に高い数値目標を掲げて、一生懸命対策とかをされていると思うのですが、もう少し具体的な内容と、今後のさらなる取組みについてもう少し詳しいご説明を、要するに。","respondent":"河内環境課長","answer":"見直しの段階におきましては、これをさらに国、都の状況を踏まえまして精査をしてまいりたいというものです。現状の達成率との見合いで考えますと、大変高いハードルではありますが、社会的に果たすべき役割といたしまして、４０％はまずクリアしていきたいです。","voiceIndex":31,"id":"exchange-011"},{"speaker":"おくの委員","kind":"質問","question":"国が２０１３年度比で２６％の目標を掲げているときに、品川区は４０％の削減目標を掲げた、だから国より高い目標を掲げていると。それに対して、この請願には、菅首相が、２０１３年度比で４６％の削減目標を掲げたというのが、この請願にあらわれている話で、来年度以降、品川区も、多分これを踏まえて考えていくというような理解でよろしいのでしょうか。","respondent":"河内環境課長","answer":"おっしゃるとおりです。","voiceIndex":35,"id":"exchange-012"},{"speaker":"おくの委員","kind":"質問・要望","question":"ですから、この請願は、本当に私としては当たり前のことを述べていると思うのですけれども、来年から審議される品川区の環境基本計画についても見直しということになっているのですが、そういうことも考慮されて、要するに、もともと国の上をいっていたような計画ですから、そういうことも考慮しながらということはもちろんお考えになっていると思うのですけれども、その点いかがでしょうか。","respondent":"河内環境課長","answer":"ＣＯ２の削減に向けまして、そのような結果が用いられますように、基礎自治体としての役割を果たしてまいりたいと考えています。エネルギー政策などにつきましては、自治体としての役割の中でとらまえているものです。","voiceIndex":37,"id":"exchange-013"},{"speaker":"おくの委員","kind":"質問","question":"そうすると必然的に、既に目の前で展開されて実証されているような原子力発電を即刻廃止するとか、ＣＯ２を出すような石炭火力発電はもうやめようというような、世界の流れになっているものは当然廃止していくというような意見書を出す、意見書を出すというか、そういうものはなしにしてしまおうよというような誰もが言っているような流れというのは、当然踏まえるということになるのであって。","respondent":"河内環境課長","answer":"ＣＯ２の削減に向けまして、品川区環境基本計画の中でしっかりと取組みを進めてまいりたいというふうに考えているところです。","voiceIndex":39,"id":"exchange-014"},{"speaker":"おくの委員","kind":"質問・要望","question":"地方自治体の役割というのは、私の申し上げた福祉の増進だということを地方自治法どおりに解釈して、踏まえた上でやっていただきたいということを申し上げておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-015"},{"speaker":"渡辺委員","kind":"質問・要望","question":"ゼロカーボン達成に向けての考え方をお聞きしたいと思います。こちらは、陳情の文面にもあるように、ゼロカーボンシティ宣言を求められていますが、宣言というものも１つの手段ですが、大事なのは、やはり中身の実効性であったり、同種の取組みだと思うのです。この辺、別に、多分相違はないと思うので確認のために伺います。","respondent":"河内環境課長","answer":"今、委員がおっしゃられたとおりでございまして、国などの動向も踏まえまして取組みを進めてまいりたいというふうに考えているところです。","voiceIndex":43,"id":"exchange-016"},{"speaker":"たけうち委員","kind":"質問・要望","question":"それと、今、渡辺委員からもあったとおり、ゼロカーボンのほうの陳情の、ここに１から３まで出ている内容については、これはもう今までも品川区は心がけてやってきたし、国のいろいろな方向を受けて、これからもこれを推進していくということでいいのかどうかということと、それから、陳情者の方が区外の方で、この方について、私のほうには直接何かお話があったりとか、なぜかというと、区外の方なので。","respondent":"河内環境課長","answer":"宣言されている区が９区ほどありますが、そういったところの達成値などと見合いましても、品川区は十分な実績値を上げているところですので、そういったところも踏まえまして、今後進めてまいりたいと考えております。","voiceIndex":46,"id":"exchange-017"},{"speaker":"たけうち委員","kind":"確認","question":"分かりました。我々のほうで確認すればよかったのかもしれませんけれども、あえてしていませんけれども、今のお話でいくと、この宣言云々ということは、これからどうなるかは別にしても、いずれにしても、ここに載っていることはもう既にやっているし、これからもやっていくということで、この陳情者の方にそこをご理解いただけたのかなと、ちょっと思いました。これは意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-018"},{"speaker":"吉田委員","kind":"質問","question":"今さらで本当にお恥ずかしいのですけれども、品川区環境基本計画で国より高いＣＯ２削減目標を掲げて、それの実効施策として、区庁舎への再生可能エネルギー導入を進めるという認識に至った、何かそこの時点での議論とか経緯とかを把握していらしたら教えてください。","respondent":"河内環境課長","answer":"はっきりした経緯というようなデータはございませんが、それ以前、環境ＩＳＯの取組み時点から、グリーン電力の購入などに向けまして、ＣＯ２排出に向けた取組みなどを進めてきたところです。","voiceIndex":52,"id":"exchange-019"},{"speaker":"吉田委員","kind":"質問・要望","question":"調査報告会は品川区にも参加をしていただきました。そういう意味で今質問をしました。この間、一般質問でもいたしましたが、前向きなご答弁のようにも聞き取れたし、もう少し強い決意もいただきたかったなと思うのですけれども、その辺、改めて今の環境基本計画のＣＯ２削減を再生可能エネルギーの推進で進めるというお考えについて、確認をさせてください。","respondent":"河内環境課長","answer":"再生可能エネルギーの件です。ＣＯ２の削減におきまして、再生可能エネルギーの利用というのは大きなポイントだというふうに認識しています。","voiceIndex":54,"id":"exchange-020"},{"speaker":"吉田委員","kind":"意見","question":"分かりました。品川区の見解としては、そういう方向であるということで理解をします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":56,"id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それと、第６次エネルギー基本計画は、今年の夏ぐらいまでに策定されるという方向で議論が始まっていると書かれていたものがあったのですけれども、具体的に、いつ頃までに、国のことなので分かったらということですけれども、いつ頃までに、どういう会議体でこれが策定されるのかというところが分かったら、教えていただきたいと思います。","respondent":"河内環境課長","answer":"脱石炭といたしまして、現在、火力の約半数が石炭火力ですが、そういったところの低減に向けてというところは情報としてつかんでいるところです。そのほかにつきましては、ＣＯ２の削減に向けて有用なところについては取り入れてまいりたいです。","voiceIndex":58,"id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"今この日本でも、水害、豪雨災害が、何十年に一度というふうに言われていたものが、毎年様々なところで発生するというところでは、やはりこのＣＯ２削減が待ったなしの課題だというのが、全会一致で確認されるという、そういう時代になっているというところがまず前提にあると思うのです。そのような中で、では、それを具体的にどうするのかというところで出されてきたのが、今回のこの請願だと思うのです。","respondent":"河内環境課長","answer":"国のエネルギー政策ですので、区としてそのような考えを示す予定はございません。","voiceIndex":64,"id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"残念ながら今の自公政権の中で、原発が９基再稼働されていますよね。そのところについて、ぜひ自公の皆さんからもご意見をいただきたいと思います。それが１点です。だけど、日本だけが出していないのです。そういうところに対しても、私は出すべきではないかと思うのですけれども、その２点について、自民党、公明党のほうから、どのような思いなのか、ご意見を伺えたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":66,"id":"exchange-024"},{"speaker":"渡辺委員","kind":"意見","question":"今、委員長がおっしゃられたように、請願・陳情の審査を私達はやっているので、そこの個々の見解というよりも、この請願の審査に集中して、それに沿った形で意見表明をするのが今の役割だと思っています。そうご理解いただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":68,"id":"exchange-025"},{"speaker":"たけうち委員","kind":"質問","question":"意見ということですが、ご存じだと思いますけれども、今これだけの経済大国になった日本が、工場だとか、我々もよく知っている冷暖房、いろいろな便利な生活を維持するのに、どれだけのエネルギーが必要かという中で、いきなりこの原発を全部止める、石炭エネルギーを全部止めたらどうなるのですか。ただ、そう簡単にいかないということだけは指摘したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":69,"id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"１００％という目標を立ててやっているところもあります。しかも、原発ほど高コストになるものはないわけですから、私はそういうことを皆さんと議論を進める中で、エネルギー政策、これだけの災害を起こしている、これをストップさせるためにどうあるべきなのかということを議会の中で議論していくというのはすごく大事なことだと思うので、ぜひ皆さんと意見を交換し合いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-027"},{"speaker":"鈴木（博）委員","kind":"確認","question":"今、請願の審査をしているので、私は請願の審査を行いたいのですけれども。議会で行いたいと、これは議会ではなくて特別委員会ですから、今出ているその請願の審査に関して、前向きな討論というか、質疑を行って、それで賛否を問うということが当然の進行だと思うので、委員長は、その辺のことを確認しながら運営をお願いしたいと思います。","respondent":"安藤委員長","answer":"これは特別委員会で、私たち議員が設置している委員会であり、なおかつ、請願・陳情審査なので、委員同士の議論というのも認められておりまして、しかも、今回は、区議会から意見書を提出してくださいという内容になっておりますので、私としては、全然問題ない質疑というか。","voiceIndex":71,"id":"exchange-028"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"この請願には、再生可能エネルギーに関して意見書を求めると書いてあるので、原発を廃止しろというような意見書ではないような気がするのですが、いかがでしょうか。原発を廃止するということで意見を交換するということが今のこの委員会の委員同士の議論の対象になるのでしょうか。委員長のお考えを伺いたいです。","respondent":"安藤委員長","answer":"お尋ねなのでお答えしますけれども、請願項目を見れば、意見書を提出してくださいと。その基本計画の中には、脱原発も入れてください、主眼にしてくださいということを書いているので、大きく外れていると私は思っておりません。","voiceIndex":73,"id":"exchange-029"},{"speaker":"たけうち委員","kind":"質問・要望","question":"いずれにしても、先ほど意見は申し上げましたので、もうこれ以上、うちの会派は議論をしたいと思っていませんので、結論を出していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-030"},{"speaker":"吉田委員","kind":"質問・要望","question":"区議会としては、区にも働きかけてほしいという請願です。ただ、やっぱりこれは区民の方の思いですので、それを国に対して求めてほしいというところでは、先ほど質疑をいたしましたけれども、品川区は再生可能エネルギーでＣＯ２削減を目指しているわけです。ぜひこれについては、私としては、採択というふうに、後の態度表明のときになりますけれども、進めていっていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":78,"id":"exchange-031"},{"speaker":"渡辺委員","kind":"意見","question":"自民党は、結論を出す、そして不採択で。理由に関しましては、先ほど来、議論の中でも、原子力発電の即刻廃止、脱原発社会等が強調されています。これに関しては国のエネルギー政策である点が１つ。それと、品川区の立場からしたら、先ほどの環境基本計画にも記載のように、国や都の計画との整合性を図りというのが大前提だと思いますので、ここには難しさがあると。よって、不採択という考えです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":81,"id":"exchange-032"},{"speaker":"たけうち委員","kind":"意見","question":"本日結論を出すで、不採択でお願いします。先ほども述べたとおり、原発の即刻廃止、これは国の電力行政の在り方、電源構成にかかってくることで、今、国で検討するということになっておりますので、我々のほうでそれを先んじる考えはないかなと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":82,"id":"exchange-033"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"結論を出す。不採択でお願いします。再生可能エネルギーのさらなる活用を求めるということに関しては、私たちの会派も全くそのとおりだと思うのですが、品川区も既に先進的な事業をたくさんされておりますので、それをしっかりとしていただくように要望して、この件に関しては不採択で、もう既にやっていることですからということでお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":83,"id":"exchange-034"},{"speaker":"おくの委員","kind":"意見","question":"結論を出すで、採択でお願いします。脱炭素社会に向けて再生可能エネルギーを主力電源化する。そのために原子力発電を廃止する方針とともに、石炭火力発電を縮小していくというのは非常にもっともなことだと思います。こういうエネルギー政策を根本的に転換していく戦略をとることによって、脱炭素政策が具体的に実現していくのだと思います。採択でお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":84,"id":"exchange-035"},{"speaker":"吉田委員","kind":"質問・要望","question":"本日結論を出してください。理由は、繰り返しになりますけれども、先ほどから品川区が再生可能エネルギーでＣＯ２削減を目指すということで進んでいるということで、これはとても評価しているところですけれども、こういう意見書を出せるのは、先進的に頑張っている自治体だからこそできることではないでしょうか。品川区の姿勢をさらに推進するためにも、国に対して意見書を提出していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":85,"id":"exchange-036"},{"speaker":"渡辺委員","kind":"質問","question":"結論を出す、そして不採択でお願いします。陳情の要旨、１番、２番、３番とある中で、まず１番、先ほどの質疑のご答弁の中で、ゼロカーボンへ向けての品川区の高い意欲が見受けられたこと。そして、２番、３番については、周知啓発や、あるいは環境学習の点、環境行動の支援は、品川区環境学習交流施設、こちらが大きな象徴であり、あるいは起点になると、これが高く見込まれること。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":89,"id":"exchange-037"},{"speaker":"たけうち委員","kind":"質問","question":"本日結論を出す、不採択でお願いします。それで、そうしたものについて、いろいろなこの陳情者の方の思いの中で、場合によっては趣旨採択とするケースもありますけれども、今回の場合、区外の方、また、その辺の情報がこちらにもない部分がありますので、出てきたもの全てを採択というわけにいかないなという、そういう理由も含めて不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":90,"id":"exchange-038"},{"speaker":"おくの委員","kind":"意見","question":"本日結論を出すで、採択でお願いします。国会で宣言を出したことは、単なる気候変動の問題ではなく、危機だという宣言、認識を持ったということ、それから、それを法律にまで高めたこと、非常に高い意義を有するものだと私たちは思っております。同様に区でも宣言を出すことは非常に高い意味を持つと思います。採択でお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":92,"id":"exchange-039"},{"speaker":"吉田委員","kind":"意見","question":"本日結論を出す、採択でお願いいたします。若干繰り返しになりますけれども、品川区はゼロカーボンに向けて意欲的に取組んでいます。意欲的に取組んでいないところは宣言は出せません。意欲的に取組んでいるところだからこそ、ゼロカーボンシティ宣言をして、さらにその姿勢を示して、区民にも啓発を進める必要があるというふうに思っています。ということで採択でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":93,"id":"exchange-040"}]},{"id":"topic-03","title":"もったいないレシピコンテストの開催","agenda":"もったいないレシピコンテストの開催","exchanges":[{"speaker":"湯澤委員","kind":"意見","question":"１点だけ。ただ、これ、目的としては、食品ロス削減意識を高めるというところであると思うのですけれども、その部分が、このチラシの右下に「日本では、年間約６００万トンの食品ロスが発生！そのうちの４６％が家庭から出ている、そして国民１人当たり、１日茶わん１杯分をロスしているというふうに消費者庁でもうたっているかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":100,"id":"exchange-041"},{"speaker":"吉田委員","kind":"質問","question":"経費が１５２万円というふうになっております。もう少し内訳とか、今、お手元で分かるようでしたら教えてください。","respondent":"河内環境課長","answer":"委員会の運営経費が大部分を占めておりまして、詳しい資料が手元にないものですから、主に委員会の開催経費が占めるものです。副賞については、表記のとおりですので、それほど経費はかかっていない状況です。","voiceIndex":102,"id":"exchange-042"},{"speaker":"吉田委員","kind":"質問","question":"分かりました。経費については、そういうことですね。ただ、このもったいないレシピのレシピの工夫とかを評価できる人というと、環境の視点とはまたちょっと違う人があってもいいのではないかというふうに思ったのですけれども、その辺については、いかがでしょうか。","respondent":"河内環境課長","answer":"主婦の目線や学生の目線、いろいろな目線を持ちまして、こういったものの評価を進めていくという予定です。","voiceIndex":104,"id":"exchange-043"},{"speaker":"吉田委員","kind":"意見","question":"あまりがちがちに環境問題と打ち出してしまうと、それはそれで楽しみながら参加していただくというところが難しいのかなと思うのですけれども、この自分たちがやった活動がどうつながるかというところを、この活動のコンテストの中で、もう少し表現していただけると、参加意欲が高まる、ただおいしく食べるだけではなくて。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":106,"id":"exchange-044"},{"speaker":"松澤委員","kind":"質問","question":"周知のことで１つ質問なのですけれども、区民への周知の中でＳＮＳ等とありますけれども、これは要は、インスタで発信するとか、フェイスブックであるとか、具体的に発信することなのでしょうか。","respondent":"河内環境課長","answer":"区のホームページはもとより、ツイッターなどでも発信させていただきまして、紙しかご覧になれない世代以外の方にも、こういったところに触れていただきますように、しっかり啓発をしていきたいというふうに考えているところです。","voiceIndex":107,"id":"exchange-045"},{"speaker":"こんの委員","kind":"確認","question":"基本的なところを確認させてください。取組みの１つとして、これは非常に大事な取組みの１つだというふうに考えております。そうしたときに、これまで、もったいないという観点で、これは食をしていますけれども、レシピを応募してもらうという、こういう取組みというのを過去やっていたかどうかという基本的なところの確認と、今後これを続けていくということが１つ大事かなというふうに思うところです。","respondent":"河内環境課長","answer":"今まで、いわゆるフードドライブ向けの取組みが長くあったのですが、一定数の周知も進んできたことから、次はやはり取組んでいただきます一般家庭の方に向けて何かというところで、特に家庭の中にあるもので、買ってはいたのだけれど使わなかったとか。","voiceIndex":111,"id":"exchange-046"},{"speaker":"こんの委員","kind":"質問","question":"ぜひこうした取組み、教育委員会とも少し連携をとりながらというところで考えるわけなのですが、いわゆる家庭科の教育というところでも、やっぱり学校の取組みとして、給食を残さないというところにもつながっていく、こうした考え方を連動していけると、また、学生、生徒、児童から家庭へという、こうした１つの流れもできるのかなというふうに考えるところですけれども。","respondent":"河内環境課長","answer":"レシピコンテストをスタートしてみようですので、まだ連携のところまで具体的なところにはいっていない状況ですが、特に給食などを含めまして、食の大切さというところは、現在は、環境問題、ＣＯ２問題についてフォーカスしていますが。","voiceIndex":113,"id":"exchange-047"},{"speaker":"こんの委員","kind":"質問","question":"そうすると、学校に対しては、お手紙というか、学校に通知、今はそこら辺のところぐらいですか。その辺はいかがでしょうか。","respondent":"河内環境課長","answer":"チラシなどの配布も学校側のほうにやっているところですので、今後、特別なものは何かというのは検討しながら進めてまいります。","voiceIndex":115,"id":"exchange-048"},{"speaker":"吉田委員","kind":"質問","question":"揚げ足を取るわけではないのですけれども、今、こんの委員から、教育委員会との連携というようなお話も出ました。だから、何かそういうことでもったいないことになっているものが結構あると思うのです。そういうことも、このもったいないレシピコンテストの、ちょっと豆知識みたいなところで、さりげなく啓発とかを進めていただけたらいいと思うのですが、その辺について、いかがでしょうか。","respondent":"河内環境課長","answer":"表現が不適切で申し訳ございませんでした。委員のおっしゃるとおりでございまして、そのような考えを基に、食に無駄がないように進めてまいりたいというところが考え方の本質的なところです。","voiceIndex":118,"id":"exchange-049"}]},{"id":"topic-04","title":"品川区災害時受援計画の策定","agenda":"品川区災害時受援計画の策定","exchanges":[{"speaker":"小芝委員","kind":"質問","question":"自衛隊・警察・消防からの受援ということで、都知事に要請する時間がない場合、また、通信の途絶等により都知事に対する要請ができない場合に、区の災害対策本部長から自衛隊に通知をする。そういった場合に練馬の第１師団のほうから派遣されるというところで、１９ページに、その受入先が大井ふ頭中央海浜公園となっておるのですけれども、まず、この場所を決めたその理由を教えてもらえますでしょうか。","respondent":"山本防災課長","answer":"活動拠点場所の指定ですけれども、こちらは東京都が区内何か所かの指定をしてございまして、品川区に関して言うと、こちらの大井ふ頭中央海浜公園というところで、東京都が指定をしているものです。","voiceIndex":124,"id":"exchange-050"},{"speaker":"小芝委員","kind":"確認","question":"イメージだと、中央海浜公園から西側のほうに移動するとなると、品川区だと、多分橋が２本、人道橋もありますけれども、２本かかっていて、そこから入っていくのかと思うのですけれども、それ以外にも、例えば京浜運河を渡って、陸地といいますか、西側のほうに入っていって活動を展開されるということを想定されているのかどうか、確認をお願いします。","respondent":"山本防災課長","answer":"実際の活用方法は、災害が起こって、その被害状況等に応じて少し変わってくるのかなというふうに思っているのですけれども、今、委員がおっしゃったとおりの方法が基本的なところになるというふうに考えてあります。","voiceIndex":126,"id":"exchange-051"},{"speaker":"吉田委員","kind":"質問","question":"そうすると、そういう方たちは、今はもう携帯とか、いろいろなものがありますので、走っている過程で、どこなら通れるとか、どこに行けばいいということが大体は把握できて、今のところは実現できているのですけれども、受援計画という場合には、その辺を受ける側としても、一定その体制を整えておく必要があるのかなというふうに思うのですけれども、それについては。","respondent":"山本防災課長","answer":"受援の部分に関する考え方ですが、こちらの計画につきましては、基本的には、国や都、それから自治体からの応援の受援に関する計画になっているところです。","voiceIndex":129,"id":"exchange-052"},{"speaker":"吉田委員","kind":"質問","question":"でも、そういうことが起きることは想定しておいたほうがいいのかなと。大体は、東京都で考えれば、都とか何とかに先に連絡が行って、そこから、では、あそこに行ってくださいというような指示が出るのだとは思いますけれども、そういう東京都との連携も含めて、もし何か今、進行形でも考えておられることがあったら伺いたいと思います。","respondent":"山本防災課長","answer":"ボランティアの受入れに関しましては、今年の１月、社会福祉協議会と災害時ボランティアセンターの設置運営に関する協定を結んでおりまして、区の福祉部と社協のほうでボランティアセンターを立ち上げて、そこで一般的なボランティアの受入れ。","voiceIndex":131,"id":"exchange-053"},{"speaker":"吉田委員","kind":"質問","question":"分かりました。せっかくの思いだけれども、こういう言い方は失礼だけれども、来ていただいて、そこの受入れができていないと、かえって、中には結果としてちょっと迷惑に感じてしまったり、そういうこともあるというふうには伺っております。これは意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":133,"id":"exchange-054"},{"speaker":"たけうち委員","kind":"質問","question":"一番最後のページの第４章３番のタイムラインの表の中で、その前にもちょっとありますけれども、国からのプッシュ型支援、それからカウンターパート団体の決定通知、この辺の流れ、特に国からのプッシュ型支援というのが、熊本地震だったか、どこかその辺りから始まったのか、いわゆる要請がなくても駆けつけるみたいなイメージだったような気がするのですけれども、その辺のご説明を教えてください。","respondent":"平原防災体制整備担当課長","answer":"物的受援のところの国からのプッシュ型支援ですけれども、これまでの大きな災害で、被災した自治体が混乱いたしまして、必要量を国に伝えることができないという反省から、熊本地震を契機といたしまして、国が被災自治体の意向を待たずに。","voiceIndex":135,"id":"exchange-055"},{"speaker":"たけうち委員","kind":"質問","question":"何かそれについて、もしあればということと、それから、恐らくそれに類するというか、場合によってはそれ以上に頼りになる災害の協定を結んでいる山北町、早川町、宮古市とか、いろいろなところと友好関係、また協定を結んでいるので、そういうところと、なかなか疎遠になっているところもあるかなという思いもあるのですけれども、その辺を年に１回とか、年に２回とか、数年に１回とか。","respondent":"山本防災課長","answer":"災害時の協定を結んでいる自治体との関係ですけれども、こちらは直接お会いして何かというのは行っておりませんで、年１回、少なくとも連絡先の確認であったり、担当者の確認というようなところでの体制というところはあるのですけれども、今後、災害の協定の内容とか。","voiceIndex":137,"id":"exchange-056"},{"speaker":"たけうち委員","kind":"質問・要望","question":"要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":139,"id":"exchange-057"},{"speaker":"こんの委員","kind":"質問・要望","question":"第５章の受援計画の実効性の確保というところをお聞きしたいと思います。具体的にどういう訓練をするのか、そこら辺を教えていただきたいのと、また、その訓練をどれぐらいの頻度で計画としてやっていき、職員の方にも周知を徹底していくのか、その辺を教えてください。","respondent":"山本防災課長","answer":"内容としましては、机上であったり、シミュレーションして、具体的に避難所を開く部署がありますので、そういった部署と、あと本部、そことのやり取りをどう進めていくかとか、物資のところも、仮想にはなりますけれども、どういったルートで。","voiceIndex":141,"id":"exchange-058"},{"speaker":"こんの委員","kind":"質問・要望","question":"これからだということですが、どうしても計画をつくった後の具体的な動きがどうなされていくかというところが非常に大事になっていくというふうに思いますので、そこら辺のところを、頻度としてどれぐらいなのかというところもご答弁いただきたいと思いますけれども、より実効性のあるというところの確保の訓練はどうしたものがいいのかも考えていっていただければ、何かご答弁がありましたら、お願いします。","respondent":"平原防災体制整備担当課長","answer":"私から、現在考えております物資の受援の今後の訓練といいましょうか、練度の向上につきまして、ご説明します。","voiceIndex":143,"id":"exchange-059"}]},{"id":"topic-05","title":"新防災ラジオ","agenda":"新防災ラジオ","exchanges":[{"speaker":"松澤委員","kind":"確認","question":"１個だけ確認させてください。この防災ラジオ、防災行政無線から緊急情報が放送されると自動受信して流れるという話ですよね。これは、先ほど、ちょっと前の受援計画でも訓練というお話が出ましたけれども、要は、緊急時だけではなくて、定期的に、１年に１回でも、そういう受信の訓練というか、テストというのはやったりするのでしょうか。","respondent":"平原防災体制整備担当課長","answer":"訓練といいましょうか、実際に自動起動するかの確認ですけれども、新しい防災ラジオでは、現在考えているところでは、月に一度程度、日付を決めまして放送するということを考えてあります。","voiceIndex":149,"id":"exchange-060"},{"speaker":"吉田委員","kind":"質問・要望","question":"今のご質問に関連するのですけれども、そのことも併せて周知されるのでしょうか。それから、今まで購入された方たちが、皆さん、それを買い替えるということを想定しておられると思うのですけれども、そうすると、今までのラジオは、機能も落ちてしまうわけだし、廃棄、その回収とかを考えておられるのか、ぜひ回収していただきたいなと思うのですけれども、その辺については、いかがでしょうか。","respondent":"平原防災体制整備担当課長","answer":"先ほどの定期的な通信に関する周知ですけれども、大変失礼いたしました。もちろんこちらにつきましては、あらかじめ日を限った形でさせていただこうと考えていますので、広報しながわをはじめ様々な媒体を用いて事前周知に努めたいと考えています。","voiceIndex":153,"id":"exchange-061"},{"speaker":"吉田委員","kind":"質問","question":"テストの広報というのもすごく大事だと思います。広報しながわとか、そういうところを使われるということですけれども、そもそもお知らせが個別に行くわけですから、毎月何日には試験放送がありますみたいなことも一緒に個別にお知らせがいったらいいのかなというふうに思います。ぜひその辺まで配慮をしていただけたらと思いますが、それについてもしお考えがあれば伺いたいと思います。","respondent":"平原防災体制整備担当課長","answer":"それぞれお持ちのラジオを、その後、不必要というようなご判断に至ったような希望者につきまして、どうするかといったところにつきましては、まだ何か決まったというところではございませんけれども、あっ旋の際までには、その辺のところを決めていきたいなと思いますが。","voiceIndex":155,"id":"exchange-062"},{"speaker":"おくの委員","kind":"質問・要望","question":"こういう方にとって、本当に手に入れやすいようなお値段で配布していただきたいと思います。総務委員会でも申し上げたのですが、前回の配布は、高齢者、障害者、住民税非課税世帯の方が２,０００円で、一般の方が４,０００円だと伺いました。中央区では、そういう方に限らず、一般の区民に１台１,０００円で配布されている。その点いかがでしょうか。お伺いいたします。","respondent":"平原防災体制整備担当課長","answer":"次年度予算というところの枠組みで検討が進められる形になるのですけれども、今お話のございました他区の実例ですとか、あるいは、どのようなところに重点的にこちらが配布といいましょうか、広まっていただきたいというところもありますので。","voiceIndex":158,"id":"exchange-063"},{"speaker":"おくの委員","kind":"質問・要望","question":"今、コロナ禍でもありますし、障害者の方や住民税非課税世帯のような非常に低収入の方というのは、私どもの想像できないような負担感を持たれることだと思います。防災ラジオというのは命にも直結するようなお話ですので、そこのところを考えていただいて、無償ということも、よくよく考えていただきたいと思います。お願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":160,"id":"exchange-064"},{"speaker":"たけうち委員","kind":"確認","question":"総務委員会でもあったので確認ですけれども、いわゆる防災ラジオで流れる同じ情報が、スマートフォンとかで、私などもそうですけれども、区の防災行政無線のものとか、いろいろ流れてきますよね。スマホで、文字で、メールとかで。ツイッターもそうでしょうけれども。ああいうもので同じものが流れてくるのは、何が流れてくるのでしょうか。","respondent":"平原防災体制整備担当課長","answer":"スマートフォンにつきましては、先ほど言いましたとおり、令和２年度から緊急放送を中心に、テキスト配信をさせていただいているところです。","voiceIndex":162,"id":"exchange-065"},{"speaker":"たけうち委員","kind":"確認","question":"そうすると、比較的スマートフォンを日頃から使われて、よく見ていらっしゃる方は、防災ラジオがもちろんあるにこしたことはないのですけれども、なくても文字で確認できると、こういうことでいいのかということと、あと、前回、防災ラジオを同じぐらいの台数販売していただいて、その後に、結構我々の下にも、知らなかったので欲しいというような声があったときに、たしか、これは５,０００台ですけれども。","respondent":"平原防災体制整備担当課長","answer":"それで、今後ですけれども、もしその台数でというようなことになりましたら、まだ具体的には何台からできるというところは、ちょっとそこまでの話はいっていないのですけれども、先ほど委員からご指摘がありましたとおり、１台、２台というのはなかなか難しいところですが。","voiceIndex":164,"id":"exchange-066"},{"speaker":"たけうち委員","kind":"意見","question":"先ほどあれしたとおり、スマートフォンで文字放送を、ラジオもそうですけれども、同じ情報を得られますよということを併せて周知していただいて、本当に必要な方には手元に届けていただくのですけれども、それを知らないで、買ったはいいのだけれども、あとで、何だ、スマートフォンでも同じ情報を聞けるのかとなる方がいてもあれなので、必要な方に回らないといけないので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":166,"id":"exchange-067"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6598#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=19&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":48432,"voices":170}},{"id":"r03-20210713-10","meetingId":"r03-cm07","date":"2021年7月13日","dateIso":"2021-07-13","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時１３分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を6件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和３年第２回定例会","agenda":"令和３年第２回定例会","exchanges":[{"speaker":"中塚委員","kind":"提案","question":"なぜならば、手話言語条例ということで、耳の聞こえに不自由な方が傍聴にいらっしゃることが考えられる。もちろん皆さんのご理解が得られたらということにはなりますけれども、第４０号議案の品川区手話言語条例の採決方法について、起立採決を提案させていただきたいと思いますけれども、皆さんのご意見をお伺いできたらと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":30,"id":"exchange-001"},{"speaker":"渡辺委員","kind":"提案","question":"ご提案ということなので真摯に受け止めたいのですが、課題があるという点で、頭からの否定というよりは、難しさがあるというふうに思います。というのは、地域行事の経験で、配慮をしたつもりが、やはり特別視する形になって、当事者の方から異論が出たというケースを経験したことがあります。意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":32,"id":"exchange-002"},{"speaker":"大沢委員","kind":"意見","question":"今、渡辺委員のご発言のように、課題が大きい問題だと感じます。委員長がさっきおっしゃったように、最終的には議長のご判断、そこら辺の課題を十分に加味しながら、議長の判断を仰ぎたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":33,"id":"exchange-003"},{"speaker":"たけうち委員","kind":"意見","question":"委員会でもそういうふうにされたということを聞いていますし、委員会でも起立採決ではなかったと、委員会では起立採決はないですけれども、そういった面では、さっき渡辺委員からもあったとおり、当事者の方々から、たっての何かということがあれば、またそれはそれで、それもまた課題はあるかと思いますが、そういったことは特に聞いておりませんし、特にそれで何か不都合があるということではないのかと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":34,"id":"exchange-004"},{"speaker":"須貝委員","kind":"提案","question":"中塚委員の提案は、すごくいいことだというふうにまず思いました。ですが、今、渡辺委員からもお話があったとおり、手話通訳者がそこにいらっしゃって、きちんとお伝えもできるということならば、やはり従来の方法で進めるということでいいのではないかと私も思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":35,"id":"exchange-005"},{"speaker":"中塚委員","kind":"提案","question":"議長の発言の前に失礼いたします。皆さんのご理解が得られればということで提案させていただきました。皆さんのご意見も拝聴させていただきまして、しっかり受け止めたいと思います。一言、今後とも、採決も含めて、分かりやすい議会になれればということを述べて、多くの方が普通どおり簡易採決ということでありますので、それはそれで受け止めさせていただきたいと思います。","respondent":"本多議長","answer":"全会一致の賛成ということですので、やはり原則どおりかと、あとは、傍聴席の分かりやすいところに手話通訳者を置いて傍聴者に対してリアルタイムで伝えられますので、今回も簡易採決で進めさせていただきたいと思います。","voiceIndex":37,"id":"exchange-006"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5420#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":13559,"voices":67}},{"id":"r03-20210729-10","meetingId":"r03-cm07","date":"2021年7月29日","dateIso":"2021-07-29","committee":"議会運営委員会","time":"午後 １時００分～午後 １時１２分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を4件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の１、新庁舎整備基本構想における議会機能に関する意見","agenda":"の１、新庁舎整備基本構想における議会機能に関する意見","exchanges":[{"speaker":"渡辺委員","kind":"提案","question":"先般も述べたように、今の議長のご提案に、賛成ということで進めていただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":6,"id":"exchange-001"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"一言意見を述べさせていただきたいと思います。予想したとおり、昨日も都内の感染者が過去最悪ということで、今後も感染者の拡大が心配されるところであります。併せて、オリンピック・パラリンピック準備課からは各位ということで、各区議会議員に求められているので、その判断はそれぞれで構わないと思いますけれども、品川区議会として協力をするというものではないということだけは指摘します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-002"},{"speaker":"あくつ委員","kind":"質問","question":"しながわフラッグ一枚と書いてあります。泊るところが一緒、練習する部屋に応援メッセージのフラッグを掲示したいと書いてあるのですが、一枚で足りるのですか。今までは競技別でやってきたのですけれども、２つの競技になっているのですけれども、各１枚という意味なのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-003"},{"speaker":"あくつ委員","kind":"質問","question":"例えば２つに分けても構わないですし、同じ場所に泊まるとか、それを見て皆様が頑張ろうということであれば一つでも構わないと思うのですけれども、いかようにもしますよという意味で質問しました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-004"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5422#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":3413,"voices":22}},{"id":"r03-20210818-6","meetingId":"r03-cm08","date":"2021年8月18日","dateIso":"2021-08-18","committee":"区民委員会","time":"午後 １時００分～午後 １時５８分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を21件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和３年度地域振興基金を活用した区民活動助成制度の審査結果","agenda":"令和３年度地域振興基金を活用した区民活動助成制度の審査結果","exchanges":[{"speaker":"横山委員","kind":"質問・要望","question":"３点ほど確認させていただきたいと思います。２点目なのですけれども、プログラミング教育とあるのですが、こちらプログラムを学ぶという内容なのでしょうか。３点目が、成果の確認の仕方なのですけれども、こちら４番、審査方法の7)番ですかね、こちらに成果の具体的な数値、指標、状態などが示されているかというところで質問します。","respondent":"川島地域活動課長","answer":"不選定のところの団体へのアドバイスというか、事前相談のところでどういうふうなやり取りがあったかということなのですが、こちらは区のほうのアドバイスというか、なかなか聞いていただけなかったというか、説明の中でもちょっとかみ合わないようなところが多くて。","voiceIndex":5,"id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"つまり、引き続き地域の中で様々な活動、課題の解決に継続して取り組んでいただきたいなという願いもあるのですけれども、助成が終わった後の取組へのフォローはどういう仕組みがあるのか、どういう状況にあるのか、それは全てがうまくいくということは願いながらも、様々な団体の事情もあるでしょうけれども、状況をご説明いただけたらと思います。","respondent":"川島地域活動課長","answer":"助成が終わった後の活動を、例えば、区の委託事業につなげていただいたりだとか、様々活動を追っていく方法はあると思うのですが、一応１つは、昨年度、中止にはなってしまいましたが、しながわ地域貢献活動展などに参加していただくですとか、それから。","voiceIndex":7,"id":"exchange-002"},{"speaker":"中塚委員","kind":"意見","question":"当初の制度設計と多少変わったところはあるのだけれども、趣旨としては、基金を活用して資金助成をしていこうということで、地域の中で引き続き様々な団体が熱意を持って取組を広げていますので、制度の周知や丁寧な説明をよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":9,"id":"exchange-003"},{"speaker":"くにば委員","kind":"質問・要望","question":"結局お金が出ている間だけできるということになってしまうので、そこに関して、把握なさっている範囲で、例えば、こういった事業は３年間の助成金が終わった後結局継続できなかったであるとか、そういった事業があったら教えていただきたいのと、そういったことを防ぐためという意味もありまして、伴走的なアドバイスをその後、例えば、借入れであった場合は。","respondent":"川島地域活動課長","answer":"かなり踏み込んだご指摘とかアドバイスもいただきますし、それから、先ほどもお話しさせていただいた、最後にお伝えしました、委員の皆様にご出席くださいと言いました公開報告会の中でも、ＮＰＯサポートセンターの方のコメントというか、講評みたいなものをいただくのですが。","voiceIndex":10,"id":"exchange-004"},{"speaker":"くにば委員","kind":"質問","question":"そのタイミングで、全ての方々に、こういった形でオンラインでやれば申請できると思います、事業を実施できると思いますみたいな形で、全てのご相談者の方にアドバイスをしているのかお伺いしたいです。","respondent":"川島地域活動課長","answer":"そういった中で様々な活動の支援ができればというふうに思っているのですが、今おっしゃったとおり、もう少しオンラインに特化したような形のやり方のスキルアップというか、こういう活動もできるのではないかという提案につきましても。","voiceIndex":12,"id":"exchange-005"},{"speaker":"中塚委員","kind":"質問","question":"８月１７日現在までに１,４７７件の発行があるというご説明でしたけれども、発行した方の、目的と言ったらいいのでしょうか、海外に渡航する理由などは発行時に聞くのか、把握するのか、あるのか、どういう傾向にあるのか。ビジネスが多いのかなというふうに何となくは感じますけれども、それとも、目的を聞くことなく発行事務をやられているのか、そこをちょっとご説明いただけますでしょうか。","respondent":"久保田地域振興部長","answer":"この申請に当たりましては、渡航先を書いてもらうというのと、大体いつぐらいに行くかというようなことをたしか書いてもらっていると思いますので、目的を書けというようなことは、ちょっと今申請書が手元にないのですけれども。","voiceIndex":22,"id":"exchange-006"},{"speaker":"中塚委員","kind":"質問","question":"なぜ聞いたのかというと、やはり新型コロナウイルスの感染が広がっている中、かといって、海外に行くことが必要な方ももちろんいらっしゃるので、それは日本の政府の方針や相手国の政府の方針も十分加味しながら、全部が全部駄目というふうには決してならないし、かといって、コロナの中今までどおり海外に行くような状況には決してないわけであって。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-007"},{"speaker":"新妻副委員長","kind":"質問","question":"このワクチンパスポートの発行につきましては、厚生労働省が決めているその国に行くという方にのみ発行されていると思うのですけれども、これは、国が定められている１８の国と地域だけなのかというところと、また、区民の中にはこの地域以外にも渡航を必要とする方がいらっしゃるかと思いますが、そういう場合に品川区の対応としてはどのように対応されているのか、ちょっとお伺いしたいと思います。","respondent":"久保田地域振興部長","answer":"パスポートを発行する際には、この１８か国に限らず、例えば、実際にアメリカですとか、フランスですとか、この１８か国にない国を渡航する目的の方にもパスポートは発行していますので、将来に向けて念のためにとっておくというような方もいらっしゃいますので。","voiceIndex":26,"id":"exchange-008"},{"speaker":"新妻副委員長","kind":"確認","question":"ありがとうございました。柔軟な対応をされているということが確認できました。これは基本パスポートを持って、海外に行くという前提があって、そこはいずれということも今ご答弁にありましたので、具体的に決まっていなくてもそこは柔軟に、パスポートがあって、いずれ海外に行くのでということであれば申請は受けていただけるということでよろしいですね。","respondent":"久保田地域振興部長","answer":"申請書には海外渡航の予定日等を記載していますので、一応海外に渡航する予定があるということが前提です。ただ、すごい何年も先の将来に行くとかいいますとまた別の話になるのでしょうけれども、一応今の時点で予定がある方を対象に発行させていただいています。","voiceIndex":28,"id":"exchange-009"},{"speaker":"藤原委員","kind":"質問","question":"１点だけお伺いしますが、（３）の手数料・送料なのですが、何で無料になっているか、その根拠を教えていただけますか。","respondent":"久保田地域振興部長","answer":"これは国のほうが発行する国のほうの事業ですが、実際発行は各市区町村が担ってやっております。国のほうでこれにつきましては無料というようなことを決めてありますので、品川区におきましても無料で発行しているというものです。","voiceIndex":30,"id":"exchange-010"}]},{"id":"topic-02","title":"東京２０２０オリンピック・パラリンピック関連事業等","agenda":"東京２０２０オリンピック・パラリンピック関連事業等","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"新型コロナウイルスの感染が広がる中、前回の委員会でも安全・安心に東京オリンピックを開催すると説明がありました。重症患者も増え、病棟が足りなくなるという深刻な状況も発生しております。お伺いしたいのは、オリンピックの開催が感染爆発の要因だと、私はそう思っているのですけれども、オリンピックの開催が感染爆発の要因だと区は思うのか、その点について伺いたいと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"ただ、テレビ等で専門家の方が言うには、人の心は少し緩んだのではないかとか、直接的な関係はないというような意見ですとか、いろいろな意見が出ているところなのですが、それは、開かなかった場合、有観客だった場合。","voiceIndex":37,"id":"exchange-011"},{"speaker":"中塚委員","kind":"質問","question":"オリンピックの開催によって間違ったメッセージが国民に流され続けたことによって感染爆発を作ってしまった。やはり今の危機的状況をまず共有するには、危機的状況だということを共通認識にしなければいけませんから、今からでもパラリンピックは中止をと品川区側から発信するべきだと思うし、それぐらいの今緊急事態が発生しているのだということを示す必要があると思いますが、最後にいかがでしょうか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"今回オリンピックが無観客になって、実際見に行く予定をしていた方とか、非常に残念な思いをした方もいらっしゃると思うのですね。","voiceIndex":39,"id":"exchange-012"},{"speaker":"中塚委員","kind":"意見","question":"確かに、私の周りにもオリンピックの観戦チケットを手に入れて、今回見られなかったという方と直接お話をしました。それはしっかり目を向けるべきだと思います。やはりオリンピックの掲げた目標や目的や様々に照らしても、人の命を奪っていい、そんなイベントは決してあってはならないと思いますので、今後とも意見を交わしていきたいなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":41,"id":"exchange-013"},{"speaker":"くにば委員","kind":"質問・要望","question":"１点だけ確認したいのですけれども、こちら同じ日程で同じ会場で開催される予定だったキャナルフェスは中止になりました。こちらが、キャナルフェスは中止になったけれども、キャナルアートモーメント品川は開催するということになった理由をお教えいただきたいのですけれども。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"その観客に関しましても今調整中ということで、オンラインになれば人は入りません。配信のみということになりますので、それは安全性は担保できるのかなというふうに認識しております。","voiceIndex":42,"id":"exchange-014"},{"speaker":"くにば委員","kind":"質問","question":"１点だけ、最初にこのイベント、１,７００人規模ですか、現地で、観客を入れる予定だったのが、今現在は４００名規模に縮小予定である。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"１点訂正させていただきたいのが、１,７００人ぐらい入るスペースというのがありまして、東京都の基準で言いますと、５０％以下ということになりますと、８００人ぐらいかなというところなのですけれども、最初から入場は４３０人前後の予定で組んでいます。","voiceIndex":44,"id":"exchange-015"},{"speaker":"くにば委員","kind":"意見","question":"ありがとうございました。最後に、先ほど申し上げたキャナルフェス、これは区のほうが関与していないので、その把握はしていないというふうなご答弁でした。ですので、同会場で行われることにリスクがあるというふうに判断されるべきかなというふうには思うので、人流抑制ということを念頭に置いて、ぜひとも区として調整をする中で、お立場をとっていただければという意見で終わらせていただきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":46,"id":"exchange-016"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"くにば委員","kind":"質問・要望","question":"もし後者、満たなかった場合は、私個人的にはその全日程に参加するというのは多少ハードルが高いと思うのですね。全日程に参加できない方でも参加できるチャンスがあればというふうに思うので、定員の１６名ずつを下回った場合は、そういった方も補欠という形で申込みを受けてみるというのはいかがなものかというふうにお伺いしたいのですけれども、ご見解をお聞かせください。","respondent":"中元スポーツ推進課長","answer":"前段です。実はこの事業、令和２年度に実施を当初予定していた事業です。ところが、昨年度、新型コロナウイルスの感染拡大の状況が大変厳しいところもありまして、また、国や都との様々なガイドラインもありましたので、昨年度ちょっと実施ができなかったのですね。","voiceIndex":52,"id":"exchange-017"},{"speaker":"くにば委員","kind":"質問","question":"丁寧なご答弁ありがとうございました。今ご答弁があった中で、今回託児サービスを設ける、そこの部分、一応、南大井文化センターとかに念のため託児のスペースがある部分について伺ったのですが、ふだん託児のスペースはあるけれども、こういった区のイベントで託児サービスが設けられるときだけ使っているというふうに伺いました。","respondent":"中元スポーツ推進課長","answer":"こちらの東品川文化センターのほうを場所として予定をしておりますが、託児につきまして、既にほかの課でこのような事業をされているときに、保育者登録というのをされていらっしゃる方がおられますので、こちらといたしましては有資格者の方。","voiceIndex":54,"id":"exchange-018"},{"speaker":"くにば委員","kind":"意見","question":"なので、ぜひともその託児というのを、イベント等を区内で行うときには、例えば、もうそれがスポーツと関係ない何かしらのイベントでもぜひともそういった託児というのを利用して、子育て世代の方がふだんは楽しめないような形に参加できるような制度というのを区内で、区の事業としてどんどん広めていっていただければなというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":56,"id":"exchange-019"},{"speaker":"くにば委員","kind":"質問","question":"そういった行政視察について、例えば、オンラインで先方の担当者の方と我々をつないで、いろいろお話を伺ったり、意見を交わしたりという形で、ある意味補完的に実施ができる部分も、側面もあるのではないかというふうに思うのですが、そういったオンラインで先方の担当者の方とお話しするというのは、何かお考えというか、そういった検討というのはされているのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-020"},{"speaker":"鈴木（真）委員長","kind":"提案","question":"委員長会でその話は出ておりません。１つの提案として議長にお話を伝えることはあると思いますけれども、これはまだ正副委員長で打ち合わせするほどでもないと思うのですけれども、一応確認はした上で、私としては今の中でやりようはないと考えていますけれども、正式なお答えはまた改めて、議長としてのお考えを聞いた上でお答えをまた別の場でさせてもらえばと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":61,"id":"exchange-021"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2906#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":20546,"voices":66}},{"id":"r03-20210818-7","meetingId":"r03-cm08","date":"2021年8月18日","dateIso":"2021-08-18","committee":"厚生委員会","time":"午後 １時００分～午後 ４時３８分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を53件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"指定管理者候補者の選定","agenda":"指定管理者候補者の選定","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"この３番の指定管理者候補者の選定というところで、今回公募によらず、今までの事業者を選定するという方向で行くということだと思うのですけれども、その場合の設置目的や事業内容などに特別な理由がある場合ということなのですが、この具体的な中身を教えていただきたいということが１点です。","respondent":"宮尾高齢者福祉課長","answer":"続きまして、選定委員会につきましては、委員構成ですが、委員長は福祉部、所管部以外というところで企画部長、それから委員は、施設を所管する部長ということで福祉部長、それから外部の方ということで有識者委員を２名、行政経験者、学識経験者。","voiceIndex":10,"id":"exchange-001"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それは高齢者福祉課のほうですよね。もう一つのほうも同じメンバーでやるということなのでしょうか。そして、その方はどのような方なのか、また、お名前も教えていただくことができるのであれば教えていただきたいと思います。それと、選定するにあたって、これまでの事業者の評価をすると思うのですけれども、その評価というものはどのような形で行うのかについても教えてください。","respondent":"宮尾高齢者福祉課長","answer":"今回施設としては２課にまたがるわけですけれども、委員会につきましては、同じ委員会で一括して審議をするという予定です。","voiceIndex":12,"id":"exchange-002"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"選定方法の特定の事業者を選定するということでの、先ほどの特別な理由なのですけれども、特別な理由というのは連続性というただ１点だけで、今回は継続するというようなことになったのかということと、それからモニタリングの評価というものは、この委員会にモニタリングの結果報告というものを毎年いただいていますが、あれが全てではなくて。","respondent":"宮尾高齢者福祉課長、菅野高齢者地域支援課長","answer":"評価の方法ですけれども、こちらはまだ、まさに詳細を詰めているというところもありますが、基本的にはそれぞれの、こちらの資料にあります選定基準に沿って、それぞれ評価をいただくということを基準に考えているところです。そういった関係性を継続させたいというところもあって、公募によらずという、まず１つ目の理由と、あと２つ目の理由は、大井林町高齢者住宅のところに在宅介護支援センター等が入っている複合施設となっておりますので。","voiceIndex":14,"id":"exchange-003"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"これからこのスケジュールでいくと、第４回定例会のときに議案として出てきて、議会で決めていくということになっていると思うのですけれども、なぜそのような形で継続にしたのか、なぜこの事業者がいいと判断したのかという評価の基準のあたりなど、そこのところではしっかりと議会としても。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":17,"id":"exchange-004"},{"speaker":"高橋（し）委員","kind":"確認","question":"ただその一方で、必ずしもそうではなく、福祉施設でも公募をして、このように今回の方法ではなくて変えていくということも当然あり得るということで、そこの確認がしたいのですけれども。","respondent":"寺嶋福祉計画課長","answer":"先ほどのご質問の中で、公募によらずといったところの特別な理由というところを両課長からご説明させていただいたのですけれども、逆に言いますと、例えば指定の内容に大きな変更等があった場合につきましては。","voiceIndex":19,"id":"exchange-005"},{"speaker":"高橋（し）委員","kind":"確認","question":"改定のルールもご説明いただきありがとうあります。このルールは、基本的にはその施設について今後どうしていくかということをきちんと考えて、それで公募か、連続性かということで、大本はその施設をどうしていくかということがあって、この指定管理をどうするかという選定をしていくというところの確認だけ、１点お願いします。","respondent":"寺嶋福祉計画課長","answer":"ずっと長く継続している施設、福祉施設は特に多いのですけれども、やはりその都度、毎年のモニタリングもそうですが、それを行うにあたりまして、そもそもこの施設が今の時代に対してこのままでいいのかどうかといったあたり、その見直しも含めて。","voiceIndex":21,"id":"exchange-006"}]},{"id":"topic-02","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"石田（秀）委員","kind":"質問","question":"その中で１つ伺いたいのは、認知症かなという家族の気づきがあったときに、ご本人が、例えば総合病院等に行くときがありますね。検査を受けてもらおうとするときに、これというのは普通は何科に行くのですか。なってからの穏やかというのはいいのだけれども、その気づいたときどうするということがあまりないような感じなのです。その辺はどうしたらいいのですか。行政の対応として、どうしたらいいか。","respondent":"宮尾高齢者福祉課長","answer":"そこがポイントとして１つあるかなと思います。それから、かかりつけ医をお持ちでない方というのは、例えば、今考えているのは認知症サポート医ありますが、そちらにも検診のご協力を依頼するという予定です。","voiceIndex":27,"id":"exchange-007"},{"speaker":"石田（秀）委員","kind":"質問","question":"この検診のことは分かるのだけれども、今の話は、そうではなくて、必ず検診に行くと、最終的には、ＭＲＩをやってくれとなるではないですか。そこを受けたがらないわけです。そのようなことをしっかりやらないと、これ、早期に認知症検診を実施するといっても、多分なかなかうまくいかないような気がしてならないのです、と思っているのですけれども、どうですか。その辺のところ。","respondent":"宮尾高齢者福祉課長","answer":"具体的に、例えばＮＴＴ東日本関東病院ですとか、それから昭和大学病院、そういったところもセットで、その後のつながせていただくというところも考えているところですので、そこを段階的にうまくリンクさせていければというふうに考えているところです。","voiceIndex":29,"id":"exchange-008"},{"speaker":"石田（秀）委員","kind":"質問","question":"すみません。繰り返しになってしまうから、ここはもうこれでやめますけれども、長谷川式というのですか、１００から７を引くものとか、いろいろ簡易の検診はやってくれて、それで今言ったＮＴＴ東日本関東病院へ行きましょうというと、例えばそれで認知症が進んだとしても、いろいろ来ていただいて、要介護だ要支援だなどとやっても、その方はそのときに元気になってしまうのです。なかなか抵抗があって。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-009"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"その中の１万４,０００人となると、もう認定を受けているほとんどの方は認知症状があるというような捉え方でいくのですかということと、認定者数が１８％ちょっとで、そのうち１７％ということなので、１,６００人ぐらいしか認知症状がない人がいないというような、そのような状況なのでしょうかというところが。","respondent":"宮尾高齢者福祉課長","answer":"３点目の拡充する事業の方向性、取組等々ですけれども、まず認知症検診というのはとにかくすぐ、早期に発見して早期に対応していくというところが一番の目的です。","voiceIndex":37,"id":"exchange-010"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"本当に認知症になりたくないというような思いが皆さんにすごくあって、もうなったとしても認めたくないということがあると思うのです。相談は区役所の相談窓口でお受けします」ということになっているのですが、具体的にどのようなチームで、どれくらいの方に対して、何名ぐらいされているのか、実績や状況を教えていただけたらと思います。","respondent":"宮尾高齢者福祉課長","answer":"品川地区と荏原地区でそれぞれ１チームずつ設置をしておりまして、それぞれ医療職の方、それから福祉職の方、医師会の方にもご協力をいただきまして、医療職、福祉職の方が入って、それで。","voiceIndex":39,"id":"exchange-011"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"例えば、先ほど申し上げた地域の中で、周りの人で本当にすごく大変な思いをしているような方に対しても継続的に相談をして、このチームを編成して対応していただくとか、そのようなことが可能だという、そのようなチームなのか、その点も伺いたいと思います。","respondent":"宮尾高齢者福祉課長","answer":"実際にその対応ケースにつきましては、まず基本的には在宅介護支援センターが中心となって、そこでいろいろな事例をキャッチした中で、この方はこのチームで対応していくことが適切であるというように判断したものを主に対応させていただいているです。","voiceIndex":41,"id":"exchange-012"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"分かりました。もう一つ、この“くるみ”認知症ガイドには認知症ケアマップとあります。各地域、荏原地区だったら荏原地区で「近くの相談先・活動先を確認してみよう」ということで、ずっと医療機関が案内されているのですけれども、ここの先生のところは基本的に認知症を診断していただいて、お薬や治療もしていただける、そのような医療機関だということでのマップだと考えていいのでしょうか。","respondent":"宮尾高齢者福祉課長","answer":"２点目のケアマップにつきましては、委員のご指摘のとおり、基本的に認知症の対応に特化したといいますか、得意なドクターにご協力をお願いして、こちらに掲載をさせていただいているです。","voiceIndex":43,"id":"exchange-013"},{"speaker":"若林委員","kind":"質問","question":"施策でやっているのは大変ありがたくて、レールを敷いていただいて、介護保険等々でしっかり支えていくということ、これはもうさらに充実をさせていっていただいて、実は実感としては、そのようなところにすごく、いわゆるグレーゾーンというのか、だからそのような方が８５％のうち何％ぐらいいらっしゃるのか、多分統計というのか、あまり目に触れたことはないのですけれども。","respondent":"宮尾高齢者福祉課長","answer":"そういった介護保険外のサービスというものも、トータルでしっかりと地域包括というシステムの中で推進していく必要があるというふうに考えているところです。","voiceIndex":46,"id":"exchange-014"},{"speaker":"若林委員","kind":"質問・要望","question":"ある方のところに１日に何回も同じ話で、繰り返しで、１回説得して、ではこのように頑張っていきましょうねと説得して、分かりましたと元気いっぱいの笑顔が出ても、また電話が来たり、また同じ話で、いや、実は、そうはいってもやはり考え直したらということの繰り返しがあちらこちらで毎日起こっているということが実態ですので、そのようなものを抱えながら、また一緒にというか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-015"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"これも目安で結構です。感覚として。家族とか、皆さんいろいろ家族会議などあるのはいいのだけれども、例えば要介護１とか、２とか受けてから、変な話、お亡くなりになるまでというか、介護を続けたご家庭の期間というものは、目安としてどれぐらいというものを把握されているかどうかというのがもしあれば教えていただきたいなということがあります。それが１つです。私は学校は１か所しか知らないから。","respondent":"宮尾高齢者福祉課長","answer":"具体的に、このぐらいの人数、ちょっと具体的な数値というところは特段決めてはいないというところがあるのですけれども、１回行ったところでも、１回行ったから、はい終わりではなくて、例えば行った先も年数が経てばメンバーが変わったりなどというところもありますので。","voiceIndex":50,"id":"exchange-016"},{"speaker":"石田（秀）委員","kind":"質問","question":"認知症カフェももしあれだったら教えてください。今、１万８,０００人と聞いて、これ、ちょっと私の記憶だけでしゃべっていてデータを調べていないのですが、私、結構前に認知症サポーターを受けて取ったのだけれども、結構年数が経っていると思うのです。それに対してどうかということと、認知症カフェも同じような気がしてならないので、それも併せてもう１回教えてください。","respondent":"宮尾高齢者福祉課長","answer":"ただ、やはりこれもしっかりと周知活動とセットでやっていく必要があると考えていますので、こちらもこれからも引き続き、１人でも多くの方に受けていただくという、そのような努力は続けていきたいと考えています。","voiceIndex":52,"id":"exchange-017"}]},{"id":"topic-03","title":"の(3)自殺対策強化月間における取り組み","agenda":"の(3)自殺対策強化月間における取り組み","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"内容及び目的のところで、自殺予防に資する相談先を記載したチラシ等の配布ということなのですけれども、この相談先というのは具体的にどこになるのか、教えていただきたいと思います。","respondent":"鷹箸保健予防課長","answer":"現在発行しているこころの電話帳に記載してある相談先につきましては、相談内容別に、経済的な問題であれば区の生活福祉課であったり、様々な相談内容別の相談先を記載しておりまして、そのチラシを配布すると同時に、当日ティッシュに挟み込む小さいタイプのものについては。","voiceIndex":59,"id":"exchange-018"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"やはり本当に周りが心配して一番に相談するところというのは保健所なのかなという思いがしていて、保健所に相談に行けばいいのですよということが、多くの区民に知れ渡るということがすごく大事なのではないかと思いましたので、ちょっと具体的に身近なところでそのようなことが起こりまして、保健所に相談してすごく丁寧にやっていただいてありがたいなと思っているのですけれども、そのようなところで。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":61,"id":"exchange-019"},{"speaker":"木村委員","kind":"質問","question":"この資料の中で「コロナ禍を受け全国的に自殺者数が増加している状況」ということですけれども、なぜコロナが増えると自殺者が増えるのでしょうか。コロナと自殺との関係というのですか、そのようなものは何かありますか。","respondent":"鷹箸保健予防課長","answer":"いわゆるコロナ禍を受けて自殺者が増えているという部分につきましては、明確な因果関係が全ての事例で明らかになっているわけではありませんが、自殺対策基本法制定後、ここ１０年は下がり続けていた自殺率が、実に１１年ぶりに今年初めて増加したという部分もございまして。","voiceIndex":63,"id":"exchange-020"},{"speaker":"木村委員","kind":"質問","question":"生活の困窮化というのですか、それが原因であろうということでありますけれども、これから、例えば行政としてはこのような生活困窮に対する、それをストップさせるためにはどのように見守っていくお考えがあるのか、お聞かせください。","respondent":"鷹箸保健予防課長","answer":"経済的な支援につきましては、私ども保健予防課の所掌ではございませんけれども、品川区独自の生活応援のための資金ですとか、様々な施策を昨年度のうちには実施をしたところですが、今年度もその他都の施策、国の施策などで。","voiceIndex":65,"id":"exchange-021"},{"speaker":"石田（秀）委員","kind":"質問","question":"これ、非常に大変難しい問題だと思っています。どこまでやればいいのかということも難しいのだけれども、これ、１日でいいのかということがまず１点です。配れるところというものが。そのようなところにはどれが届けばいいのか、電話帳なのか、ＳＯＳカードなのか、私もよく分からないけれども、そのような配れるところには全て配るというようなことはやらないのですか。","respondent":"鷹箸保健予防課長","answer":"その後、大学のほうでどのように学生に配っていただいているかというところまでは、現在のところ把握しておりませんが、これまで全生徒に個別にという発想ではなかったところ、小学生まではＳＯＳカードが全ての方に。","voiceIndex":68,"id":"exchange-022"},{"speaker":"石田（秀）委員","kind":"質問","question":"この年代別などというものが分かるのなら、年代別にどのようなところにどのようなことをしたらいいのかがあるではないですか。そのようなものとか、何か打ち出し方ってあるではないですか。せっかく東京都でやっているなら、東京都もそこの部分を本気でやるならある程度の予算はあるのだろうから、そのようなこともやったらどうですかとか。これ、例えば職員が配らなくても別にいいわけではないですか。","respondent":"鷹箸保健予防課長","answer":"その個別具体的な対象に、区として直接的な対応というところは、現時点のところでは考えられていないところですが、委員ご指摘のことは十分理解できる部分ですので、今後個別の干渉について検討するとともに、前回の委員会でもお話をしたところですけれども、最近の特徴として。","voiceIndex":70,"id":"exchange-023"}]},{"id":"topic-04","title":"新型コロナウイルス感染症に係る保健所・保健センターの対応","agenda":"新型コロナウイルス感染症に係る保健所・保健センターの対応","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"医療機関から発生届を保健所が受け取っても、感染者に最初の連絡を入れるまで３日間から１週間かかるという、そのような状況だというようなことも新聞の報道でもされていたのですけれども、その辺のところがどのようなことなのかということを具体的に教えていただきたいのと、あと保健所の体制というものも、今かなりほかからも応援を入れて体制を取っているというようなことも途中で伺ったのですが、今。","respondent":"鷹箸保健予防課長","answer":"具体的には、では、あなたは濃厚接触者になりますということで保健所がお伝えをしたら、申し訳ありませんが、検査はぜひお受けになっていただいて、検査を受けられる医療機関についてはご自分で探してください、あるいはコールセンターのほうに確認してください。","voiceIndex":76,"id":"exchange-024"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"テレビ報道などを見ると、救急車を呼んでも救急車の中で受入先の病院が見つからない、その救急搬送困難ということも、今最多の３,３６１件というものが新聞報道であって、東京でも東京消防庁で１,８３７件が１週間で緊急搬送困難ということの報道がされているのですけれども、品川区でもそのように、酸素飽和度が９０％を切ってしまって、救急車を呼んで本当にこれで助かるかなと思いきや。","respondent":"鷹箸保健予防課長","answer":"どんどん戻ってきたものをなるべく早くお届けするというような対応をしているのですが、なかなかそれも、まずお電話ができない状況も踏まえますと、例えば発生届が出た翌日には届けたいところなのですけれども、なかなかそうはいっていないというところで、ここを何とか。","voiceIndex":78,"id":"exchange-025"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"この往診体制というものが、具体的なところではどれくらいのところで、多分１,３００人の方皆さんを診ていただく、回っていただくというようなところというものは、なかなか難しいのかなと思うのですけれども、そのような往診体制というものはどれぐらいのところまでカバーできるような体制が取れるのか、その点についても伺いたいと思います。","respondent":"鷹箸保健予防課長","answer":"要は入院できないということは、かなり高齢で重症化しやすい方が家にいますけれども、その人は早く入院してほしいのですが、これまではそれほど重症化しやすそうではない２０代、３０代の症状がない方で、独り暮らしの方でも宿泊療養に頼むと入れていたわけなのですけれども。","voiceIndex":81,"id":"exchange-026"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"在宅での酸素療法というものも、本当に在宅酸素も今かなりコンパクトになっているようで、そのようなものを東京都からも、どれぐらいですか、あっという間になくなったというような形で報道されておりました。","respondent":"鷹箸保健予防課長","answer":"ＰＣＲ検査の件なのですけれども、先ほど濃厚接触者の対応を変えたこともありまして、これまではすぐに検査につながらなかった、あるいは風邪ですねと検査をしないで帰っていた方々も、先ほどの濃厚接触者の対応を変えたときに、聞き取りの中で医療機関に通っていたのだけれども。","voiceIndex":85,"id":"exchange-027"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"様々ご説明ありがとうございました。とにかく本当に今までにない感染爆発で、もう毎日４,０００人、５,０００人という新規感染者の中で、皆さん本当にご苦労されていると思います。とにかく職員の皆さん、お体に気をつけてしていただきたいというような思いと、あとはもう、やはり国や東京都に対してもしっかり求めていただいて、コロナを封じ込めていくというところで取組をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":87,"id":"exchange-028"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"往診のことをまず伺いたいと思います。","respondent":"鷹箸保健予防課長","answer":"それ以外に、区内で開業されている非常に思いのある先生が、ご自身で検査をして陽性になった患者が中心なのですけれども、その後具合が悪くなったということに気づいて往診してくださるという先生がお一人と、先日。","voiceIndex":89,"id":"exchange-029"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"確認なのですが、そうすると、６月から東京都が株式会社と契約をして、そこで医師、看護師、ここはそのような人を抱えているところと、抱えているというか、派遣ができる会社と契約をしたので、それは往診をしていると。必要な場合は。それから、その往診をするときに、防護服を来て行かれるのかどうかということも教えていただきたい。往診も、例えば２軒、３軒ある場合もあると思うのです。","respondent":"鷹箸保健予防課長","answer":"診療のときの装具ですけれども、もともと検査、あるいはコロナ陽性の患者についても、全ての患者に防護服対応が必要だというようには言われておりませんで、吸引をするとか、非常に飛沫が飛ぶような措置のときには必ず防護服を着るというような枠組みにはなっておりますけれども。","voiceIndex":91,"id":"exchange-030"},{"speaker":"石田（秀）委員","kind":"確認","question":"これで分かりました。そこは往診の場合の確認が大体分かりました。それで、これはもうしようがないことなのだけれども、今在宅にいらっしゃると、もちろん玄関で着替えるとか、そのようなわけでもないから、外で防護服を着る。個人情報が。それは陽性者だから致し方ないとして、１つ。そのヘルパーが。お忙しいと思うのだけれども、そのような連携というものは取れないものでしょうかという質問です。","respondent":"鷹箸保健予防課長","answer":"どのような経緯でそのような症例になったのか分かりませんが、基本的には高齢者で陽性になって、その方のおうちにヘルパーステーション等が入っているということが分かった場合には、我々はヘルパーステーションに連絡をすることもありますが、ご家族に了解をして。","voiceIndex":95,"id":"exchange-031"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それは一例なのかもしれないですが、介護事業者の方からそのような話があったのです。だから、もしそのようなことで行かざるを得ないのであれば、何かそのような手当てというものも、これは予算の話のようになってしまうけれども、そのようなことの予算化ではないですが、そのようなときは配布しますなどということをぜひ考えていただきたいなと思いますが、どうですか。","respondent":"鷹箸保健予防課長","answer":"先ほどの、今保健所から手配できているのは、陽性者の方を直接処遇する場合なのですけれども、高齢者施設等に関しては確かに必要で、そちらについては高齢者福祉課のほうと東京都のほうで連携をして、介護事業者に必要な数を配るのではないかもしれないのですが。","voiceIndex":99,"id":"exchange-032"},{"speaker":"せお委員","kind":"質問・要望","question":"ちょっと３点ほどお聞きしたいのですけれども、まず１点、先ほどの往診の答弁のところで、都と契約しているという２社や、医師会の先生のところに看護師がいるということなのですが、先ほどナースが一緒に行くというお話があったと思うのですけれども、それはナースだけで行く訪問看護とか、そういったものも症状によっては医師が行かなくても訪問看護で、言い方はあれですけれども、足りるというか。","respondent":"鷹箸保健予防課長","answer":"今非常に人数が増えていることもありまして、国がやっているＨＥＲ－ＳＹＳのシステムの中でＭｙ ＨＥＲ－ＳＹＳというものをＵＲＬでお送りすると、自分の番号で１対１でいい、悪いとチェックするようなものもあるので、そこで具合が悪いとこちらに連絡が来ると。","voiceIndex":102,"id":"exchange-033"},{"speaker":"せお委員","kind":"意見","question":"先ほどの職員の聞き取りのところ、もちろん重要な項目が上がってきたら保健師や看護師につなぐということで、ここの判断もなかなか医療従事者でないとちょっと難しかったりすると思いますので、そこのところもしっかり対応できるようにお願いしたいと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":104,"id":"exchange-034"}]},{"id":"topic-05","title":"品川区の新型コロナウイルス感染症にかかるワクチン接種状況","agenda":"品川区の新型コロナウイルス感染症にかかるワクチン接種状況","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"今後の見通しというものは、これ以外は全然、ちょっと見通しが立たないというようなことになっていくのか。アストラゼネカしか見通しは立たないという状況なのか、その点を伺いたいと思います。障害者のためのワクチン接種が対応されたという、７月２８日から開始されているということで、これはよかったと思うのですけれども、これはどこでどのような形でされているのか、伺いたいと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"ご質問の、現在１０月までの３４０箱、約３９万６,０００回分が区民の何％に当たるものかですが、５４.２％分です。","voiceIndex":109,"id":"exchange-035"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"国によっては年齢制限があるなどということもあったりしていると思うのですけれども、そのようなところはどう考えられて区としては接種をしていくのか、その点についても伺いたいと思います。そのようなことでいうと、ちょっと１０月以降の見通しが立たない中で、区としては対象の全世代に２回ワクチンを打ち終えるのはいつ頃かという見通しは全く立たないということなのか、その点についても伺います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"終了見込みですが、このままのペースでいけばという形でお話しすると、１１月から１２月の半ばぐらいではなかろうかという形にはなりますが、何分１０月の前半までのワクチンの供給しか現在は見通すことができておりませんで、足りないことも事実です。","voiceIndex":117,"id":"exchange-036"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"特別区長会としてもすごく強力に、国にワクチンの確保をというようなことで求めたということも報道されていますので、もう本当に区としてもそのように国のほうに強力に、区長も通しながら求めているという、それでもなかなかこのような状況ということだと思います。把握されているとしたら、やはり未接種の方がほとんどという状況なのかどうか、そこの点についても教えていただきたいと思います。","respondent":"鷹箸保健予防課長","answer":"ワクチンを接種しているか接種していないかということで、特段の統計を取っておりませんけれども、全体の傾向として、高齢者の方の届出が本当にすごく少なくなっているので、その意味でワクチン接種した方の発症は少ないのではないかというふうに考えています。","voiceIndex":121,"id":"exchange-037"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"保育士とか、子どもたちのところにも感染が広がっているという、若い人から子どもたちのところまでどんどん広がっているということが、このデルタ株の特徴だと思うのですけれども、そのような点では、保育園とか、学校職員の方々とか、エッセンシャルワーカーだとか、ワクチンの接種を、保育園などもキャンセルのところでできるというようなところは聞いていたのですが。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"集団接種会場のキャンセル枠の対応ということで、保育士などを優先的に打っておりました。一般事務職員を含めてではありますが、現時点でそうした保育士も事務職員も含めて６５７名の方が、打ち終わっております。","voiceIndex":123,"id":"exchange-038"},{"speaker":"石田（秀）委員","kind":"質問","question":"ワクチン接種で、今ワクチンが入ってくる、入ってこないという話は、この約３９万６,０００回分が１０月上旬までに入ってくるわけだけれども。２３日もどれだけか。そのような体制整備、その１万６,０００回にいつでも戻せるのであれば、これは終わりますというのか、１万６,０００回から減らしてしまったから１万６,０００回まで復活できないとか、その辺の感覚を教えてほしいのです。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"あくまでこれは試算の８０箱ですが、この８０箱に関しては、現状東京都から来る見込みのないものでございまして、当然この箱数が来れば、もちろん接種は進んでいけるのですけれども、現状ではその８０箱の見込みが立っておりませんで、この辺り、東京都にも強く要望を出して。","voiceIndex":126,"id":"exchange-039"},{"speaker":"石田（秀）委員","kind":"確認","question":"今、個別接種会場の準備ができたところから、だけれども対象を絞ってと資料に書いてあるように、それがあまりワクチンがないからということだと考えると、基本的には個別接種会場の新規予約はほとんど枠がないと理解する、我々が区民から聞かれたら、そう言えばいいということなのかというところだけ確認をさせてください。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"大体人数にすると、およそ３０名分ぐらいのワクチン、現状聞いているのはその程度のワクチンしかお渡しできない状態でありますので、新規の受付もその人数ぐらいしかお受けできないことに、現状ではなっております。","voiceIndex":128,"id":"exchange-040"},{"speaker":"石田（秀）委員","kind":"質問","question":"意味が分からない。私が勉強不足で悪いのだけれども、もう既にその分は個別接種会場の医師会を通じてなのですが、それというものは、これだけというのは決めてあるのではないですか。それで決めてあるから、それをどう分配するかということは医師会が決めることであって、先ほど絞ると言いましたね。そうすると、それまでの期間の予約が取れるのが、新規では１個別接種会場３０人。そういう理解なのですか。","respondent":"秋山保健整備担当部長","answer":"それはそれぞれの個別接種会場の診療所でお考えになって、今、医師会のほうに要求をしているというように聞いておりますので、個別接種会場でこの条件の方が大体１施設当たり何人できるのかということに関しては、正直に言うと、今。","voiceIndex":130,"id":"exchange-041"},{"speaker":"石田（秀）委員","kind":"確認","question":"もう１回確認だけさせてください。次は９月６日です。その確認をしたいわけです。大規模接種も終わってしまうとか、いろいろあると、もうあちらでも予約が取れないとか、みんなが言っているから、ではそのような人たちはどこで打ったらいいのですかといったら、今のところ打つ場所はないと言うしかないということに、我々が区民の方から聞かれたら、そう答えるしかないという理解でいいということですか。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"大変心苦しいのですが、委員ご指摘のとおりです。","voiceIndex":133,"id":"exchange-042"},{"speaker":"若林委員","kind":"質問","question":"そうしますと、８月２３日に次の予約が再開されて、先ほど５,２９２名分、これが集団接種会場と。個別接種会場分は何人分なのですか。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"個別接種会場には医師会に箱をまとめてポンとお渡しする形になりますので、医師会が各クリニックに幾つバイアルを出すかということは、現状、先ほどの担当部長の話ではありませんけれども、手挙げをした数が幾つになるかによって配分できる数も変わってまいりますので、現状。","voiceIndex":136,"id":"exchange-043"},{"speaker":"若林委員","kind":"質問","question":"でもこれは随時か。私なども含めて、区民はいまだに品川区には１２０箇所の、ホームページの地図にあるような、一覧表にあるような個別接種会場が存在をしていて、いずれ集団接種会場の予約も再開するのだから、あの１２０箇所の個別接種で予約が再開されるのだなと普通に思うではないですか。片や、両医師会にお渡しする箱数と掛ける１,１７０人分はということで、何人分と出るではないですか。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"今回１０月の最終クール、１５クールまで、もうまとめての箱数で医師会とは調整させていただきまして、両医師会にお渡しする箱数が１３箱となります。１３箱で人数に直しますと７,６０５名分です。こちらが個別接種で接種していただける人数となります。","voiceIndex":138,"id":"exchange-044"},{"speaker":"若林委員","kind":"意見","question":"そうすると、あとはバランスの問題ですね。集団接種が５,２９２人分。もうこれは決まった数なので、別に調整してくださいとか、そのような意味ではないです。それで個別接種が１２０箇所全部開くのかどうか分かりません。それはもう個々の医師会とクリニックの判断です。それでも７,６０５人分という、集団接種会場より大きな数字が出ています。このバランスというものはどのような。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"７,６０５名というのは、１３掛ける６掛ける１９５割る２で７,６０５なのですが、この７,６０５名は、今回の８月２３日で使えるものではなくて、もう８月２３日から１０月の最後の１５クールまで来るものも全部加味して。","voiceIndex":140,"id":"exchange-045"},{"speaker":"若林委員","kind":"質問","question":"だんだん分かってきました。そうすると、個別接種はこの第１５クール以降、第１６、１７クールが国から来たとしても、それは医師会にはお渡ししませんと。それは全部集団接種でやりますということですか。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"１６クール以降のことはまだ何も国から下りてきておりませんで、その辺りが分かりましたら、またそれは別途医師会の皆様とも調整させていただいて、個別接種のほうに、やるやらないも含めて調整をして進めていくというふうに、今は考えております。","voiceIndex":142,"id":"exchange-046"},{"speaker":"若林委員","kind":"質問","question":"いずれにしてもこれから１６クール、今、１６クールという言葉は出ていないのだけれども、当然１６、１７クールとワクチンが来ないと終わらないわけですから、来るということは自明の前提として、それ以降も、箱数は全然分からないけれども、集団接種、そして個別接種も品川区においてはやりますという理解をさせていただいていいのですねということが１つです。ただし、インフルエンザの季節になります。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"インフルエンザのワクチン等々につきましても、今後シーズンになってくるかと思いますので、毎週１回、両医師会とは調整会議を進めておりますので、その辺りも議題として挙げて、いろいろ検討させていただければというふうに考えております。","voiceIndex":144,"id":"exchange-047"},{"speaker":"石田（秀）委員","kind":"確認","question":"先ほど役割分担の話をしたではないですか。それで、７,６０５人は分かりました。だけれども、役割分担をしているので、この８月下旬からやるのは１２歳以上１６歳未満、それから集団接種会場で接種が困難な方。それを確認したい。この７,６０５人は一般の２０代、３０代の方に打ちませんよね。先ほど、それは絶対ないのですねという確認をしたのです。その確認だけ絶対にしてください。","respondent":"秋山保健整備担当部長","answer":"そこから先の、各診療所への配分の考え方については、これは各診療所の考え方というものも当然あります。最初に個別接種が始まったときに、かかりつけの患者しかやらないとか、誰が来てもいいというような、実際にそれぞれの診療所の方の考え方がございました。","voiceIndex":146,"id":"exchange-048"},{"speaker":"石田（秀）委員","kind":"質問","question":"これ、微妙な話で悪いけれども、我々の耳に入っているのは、クリニックでもこの先生のところに頼めば、うちには結構あるから何人でもいいよというような答えが来て、それで我々が、そこを予約してみたらどうですかと言ったら、あそこは受け入れてくれるとか、我々がお願いをして、ではここに聞いてみたらどうですかなどと言ったら、うちは数がないのですなどと言われたりとかという話が必ず来るわけです。","respondent":"秋山保健整備担当部長","answer":"今、ホームページでは１２０箇所がそのまま出ています。それは２回目をやっていますので、今の段階で削ることはできないということでしておりますけれども、その暁には、手を挙げてこの条件でやっているというところのリストに更新をして周知をしたいと考えています。","voiceIndex":148,"id":"exchange-049"},{"speaker":"石田（秀）委員","kind":"質問","question":"今接種ができない、どこに予約したらいいのだということはたくさんある。その答えられない中で、ではあとは勝手にどうぞというような話は、これから１２０箇所は２回目があるからと言われましたが、２回目の人はもう言われているわけです。いつと決まっているわけではないですか。新規予約を取っていないのだから、そのようなものは変えてもいいわけではないですか。それだけはお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":151,"id":"exchange-050"},{"speaker":"高橋（し）委員","kind":"質問","question":"ワクチン接種で今もいろいろお話がありましたけれども、大変な状況の中でそのように進めていただいて、本当にご苦労さまだと思っています。１つだけ。８のワクチン接種人数、接種率のところで、６５歳以上が８０％以上、数字は少し変わりましたけれども、それから１２歳以上がというものは区全体で４０％ですが、６４歳以下１２歳までの方々の数字は大体２０％台でよろしいのでしょうか。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"１２歳から６４歳までの数字は、現状では１回目の接種率が３０.６％、２回目が１８.４％という数字となっております。","voiceIndex":153,"id":"exchange-051"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"なかなか作業が手間がかかるのか分かりませんが、やはり非常に分かりやすくするという意味で、全体と１２歳以上という国に合わせるのも結構ですけれども、それにプラスして、やはり現状このような数字でこれだけの接種率、先ほどのワクチンの話があるので、だから早急にどうこうというのはなかなかあれですが、ただ皆さんに周知して、今これだけの接種率なのだということを理解していただくためには。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"出し方については、広報部門とも入念に調整させていただいて、今のご意見を参考に１０歳刻みでできるかどうか、出し方も含めて、検討させていただきたいと思います。","voiceIndex":155,"id":"exchange-052"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ぜひよろしくお願いします。ただ品川区が接種が遅れているなどという意味ではなくて、数字を見て啓発という意味で、皆さんへの接種に対する喚起といいますか。それでなかなかワクチンがないと厳しいところはあるのですけれども、皆さんにそのような啓発の意味で、今のことを検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":157,"id":"exchange-053"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3604#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":63510,"voices":166}},{"id":"r03-20210818-8","meetingId":"r03-cm08","date":"2021年8月18日","dateIso":"2021-08-18","committee":"建設委員会","time":"午後 １時００分～午後 ４時４５分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を70件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和３年陳情第３９号、「羽田空港のこれから」専用電話番号（０５７０－××－×××）（ナビダイアル～有料２０秒毎に１０円課金）をフリーダイアル（０１２０－××－×","agenda":"令和３年陳情第３９号、「羽田空港のこれから」専用電話番号（０５７０－××－×××）（ナビダイアル～有料２０秒毎に１０円課金）をフリーダイアル（０１２０－××－×","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"今回、羽田新ルートについての問合せの電話番号をフリーダイヤルにしてほしいということで陳情が出されました。陳情代表の方ほか１５名の方から出てきたということで、ナビダイヤルとフリーダイヤルの違い、先ほど少し説明がありましたが、さらに付け加えることや、詳しく説明できるところがあれば伺いたいと思います。もし聞いていなかったら、区の考えを伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"今回寄せられた陳情に対する国の考え方ですが、こちらについては、先ほど冒頭でもご説明いたしましたが、基本的には飛行時間が夕方の一定時間内というところで、実際、飛行を体感した人を中心に、その時間帯に一定集中して電話が寄せられるということもあって。","voiceIndex":6,"id":"exchange-001"},{"speaker":"のだて委員","kind":"質問","question":"それで、国の意見を聞いていなければ、区の考えを伺いたいということでしたので、そこについて伺いたいのと、あと、国の意見の中でも、ナビダイヤルにすると多くの方に対応できるということでしたが、それがどういう意味なのか、ちょっとよく分かりかねますので、多くの方に対応できるというのはどういう意味か、ご説明いただければと思います。","respondent":"鈴木都市計画課長","answer":"実際、国は、そうした時間帯での電話がやはり非常に多いとも申しておりますので、そうした中で、１件当たりの電話のお受けする時間の効率化を図って、それ以外の方の電話も広くしっかりお聞きするという意味で、この方法を採用しているというところで、例えばですが。","voiceIndex":8,"id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうした中で、フリーダイヤルにしてほしいという要望も出ているわけですから、やはり負担を心配せずに問合せができるようにしていくということが、住民の意見をしっかり聞いていくという姿勢にもつながるのではないかと思うのですけれども、いかがでしょうか。ナビダイヤルにすることで多くの方に対応できるということなのですけれども、やはり長時間かける方もいらっしゃる。","respondent":"鈴木都市計画課長","answer":"当然、先ほどから答弁させていただいている内容は、そうした声を切り捨てるということは全く申しているものではございませんで、国では、冒頭もご説明しましたが、それ以外にも様々、２点ほど、声を寄せていただける方法というのを設置しておりますし、そうしたところで。","voiceIndex":10,"id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"多くの方に対応できるようにするためにナビダイヤルにしているということですが、そう言うならば、人員を増やして対応すればいいことだと思いますので、そういったことも含めて、国にも要望していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":12,"id":"exchange-004"},{"speaker":"西本委員","kind":"質問","question":"ちょっと教えてほしいのですが、ナビダイヤルにかけるとどういう音声が出てきて、どういう対応をしていただけるのでしょうか。","respondent":"鈴木都市計画課長","answer":"具体的には、チャット機能を利用してご質問したい方、次に、よくある質問や新飛行経路の詳細をインターネットで確認したい方、３つ目がオペレーターと直接話がしたい方というところで、番号を押していただいて案内をするです。","voiceIndex":14,"id":"exchange-005"},{"speaker":"西本委員","kind":"質問","question":"多分、振り分けですから、お問合せがいろいろカテゴライズされていて、そこに番号でいくということで、でもそちらというよりは、オペレーターと話をしたいのでしょうね。この区分けというか、適用の考え方というのは、何かあるのでしょうか。こういう場合にはフリーダイヤル、こういう場合にはナビダイヤルということで、一応決まりというのはあるのでしょうか。","respondent":"鈴木都市計画課長","answer":"基本的には、やはり人権や消費者保護の観点、あるいは区民の生命など、そうしたところの安全に関わるような通報、本当に緊急を要するような通報といったところは、無料にして窓口を設置するというところは、国の一般的事例や区でも、そうした考え方の下。","voiceIndex":16,"id":"exchange-006"},{"speaker":"西本委員","kind":"質問・要望","question":"国は恐らく、効率化といいつつも、あまり聞きたくないのでしょう。こういったものというのはどういうふうに使われていて、一番は品川区は関与しているわけですから、品川区に対してフィードバックされているのか、されないのか。そして、こちらから要望しないのか。それによって、品川区民の方々のご意見を収集するための１つのツールになるかと思うのです。それはどういうお考えになるのでしょうか。","respondent":"鈴木都市計画課長","answer":"これは区でいただいたご意見の中で、例えばですが、電波障害など、それでテレビの映りが悪くなっているのではないかというところについては、具体的なところで区でもお伝えしていますし、国では、そうしたものに対して、例えば現地調査など。","voiceIndex":18,"id":"exchange-007"},{"speaker":"西本委員","kind":"質問・要望","question":"国でやっているのだとすれば、やはりそれは公開すべきだと思うし、それが礼儀だと思うのです。その結果どうなったのかというのは、やはり何かしらの形で示していくべきだろうと思います。なので、フィードバックというのは必ずいただいて、品川区としてどういう対応をしていったのか、いくのかということは、広く区民の方にお伝えしていただきたいと考えていますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-008"},{"speaker":"芹澤委員","kind":"意見","question":"内容として、フリーダイヤルにすることで、目的としては多くの方々から意見を聞いてほしいというのが根幹にあると思っていまして、それはそのとおりなのですが、今お話をいただいたように、ナビダイヤルでの振り分けもそうですし、より多くの方から声を聞くためには、今のところナビダイヤルのほうが有効であるというお考え、また無料での窓口として、メールであったり、はがきであったりという。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":22,"id":"exchange-009"},{"speaker":"塚本委員","kind":"意見","question":"本日結論を出すで、結論は不採択です。やはり、無料ということは、それに対する弊害というのは一定程度考えざるを得ないというのは、運営する側からすれば、理解できるところではあるので、今回の陳情については不採択というところでお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":23,"id":"exchange-010"},{"speaker":"大沢副委員長","kind":"質問・要望","question":"理由は、無料ということは非常に、料金がかからないわけですからいいことではありますけれども、その中で、先ほど来の説明にもありましたように、２点あると思います。それと、ここに、可及的に速やかにということですけれども、今までの話を伺っていたように、いろいろ課題があるので、これは可及的速やかは絶対無理な話なので、このところも承服することはできません。すみません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-011"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、採択を主張します。羽田新ルートの問題は区民の関心が高い問題です。やはり、有料化というか、電話料金を負担させることによって制限させるようなことは、やるべきではないと思いますし、住民が自由に問合せをできるようにするべきだと思いますので、問合せしやすいようにフリーダイヤルにすることは、住民の利益につながるものだと考えますので、採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":25,"id":"exchange-012"},{"speaker":"西本委員","kind":"意見","question":"なので、フリーダイヤルもしくはＬＩＮＥ電話など、いろいろと今、媒体が出てきておりますので、それらを利用して、お金がかかる、かからない、または回線の問題、多々ありますけれども、最大限、区民の皆さんの声をいかに集めていくかということは、やはり区議会としても、行政、区政においても、国に申入れをするということは当たり前であるし、私たちの責務ではないかと思いますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":26,"id":"exchange-013"}]},{"id":"topic-02","title":"令和３年９月区民住宅（空き室）入居予定者登録募集","agenda":"令和３年９月区民住宅（空き室）入居予定者登録募集","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"この間の申請数と、あと入居した数の実績を伺いたいと思います。","respondent":"竹田住宅課長","answer":"応募件数と入居者数、過去３年分についてご案内します。平成３０年度が、応募件数が９９件で入居者数が２３件、それから令和元年度が、応募件数が７６件で入居者数が９件、昨年度、令和２年度は、１２３件の応募に対して入居者数が３０件となっております。","voiceIndex":33,"id":"exchange-014"}]},{"id":"topic-03","title":"住宅確保要配慮者入居促進事業","agenda":"住宅確保要配慮者入居促進事業","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回、高齢者や障害者、ひとり親、低所得者を含めた住まいの確保の支援ということで、具体的にどういう方がこれを適用できるのかという要件というのですか、それはあるのかどうか伺いたいと思います。こうした住宅あっ旋の支援というのは、ほかにもあると思うのですが、そうした仕組みとの兼ね合い、どちらも利用できたりするのかなど、その辺を伺いたいと思います。","respondent":"竹田住宅課長","answer":"どれぐらいの不動産店の登録数を想定しているのかということですが、今、似た事業で、高齢者地域支援課で行っている事業は、約７０軒ほどの不動産店をご紹介しているということですので、私どもも当面は７０軒程度を目標にしていきたいと考えています。","voiceIndex":39,"id":"exchange-015"},{"speaker":"のだて委員","kind":"質問・要望","question":"対象なのですが、具体的には、そうすると、何歳以上とか、手帳を持っているとか、年収が２００万円以下とか、そういった具体的な指標は特にないということでよいのか、確認させていただきたいと思います。ほかの制度との兼ね合いですけれども、つまりは、どちらも両方利用することができるということでいいのでしょうか。","respondent":"竹田住宅課長","answer":"それから低額所得者については、今回の事業の基になる、いわゆる住宅セーフティネット法と言われる法律がございまして、そちらの定義としては、低額所得者は月収が１５万８,０００円となっていますので。","voiceIndex":41,"id":"exchange-016"},{"speaker":"大沢副委員長","kind":"質問","question":"今、課長がおっしゃった住宅セーフティネット法ということで、これの改正を受けてということで、国および都からという住宅の施策が打たれたわけですけれども、この間、もう二、三年経っていまして、もう既に二、三年前ぐらいから、国・都ではということで政策、事業が行われていたのですけれども、もう８年ぐらいということで聞き及んでおりますが、この中で、なぜ今、品川区がこれに踏み切ったのか。","respondent":"竹田住宅課長","answer":"法律ができてから、各自治体では居住支援協議会という協議会を立ち上げまして、まだ立ち上げ途中の自治体もありますけれども、各自治体で順次立ち上げて、要配慮者に対する支援というのを、今、検討している状況です。","voiceIndex":44,"id":"exchange-017"},{"speaker":"芹澤委員","kind":"質問・要望","question":"２点教えていただきたいのですが、住宅確保要配慮者ということで、これは賛否があると思うので、やってほしいという話ではないのですけれども、就労している外国人の住宅というのも確保がなかなか難しいというのが議論としてあると思うのです。","respondent":"竹田住宅課長","answer":"しかし、今回、初めての事業、２３区内でもほかに事例がない事業ですので、今回は、事業をスムーズにスタートさせるため、外国人の場合、言葉の壁がありますので、当初は外国人の方は対象外としてまずはスタートして。","voiceIndex":47,"id":"exchange-018"},{"speaker":"西本委員","kind":"質問","question":"今回のこの制度、一元化になるということはとてもいいことだと考えていますが、正直、各所管とのコラボレートというか、協力体制は取れていなかったのかというのがあって、比較的、住宅課と割と相談し合いながらやっていたような感じを受けたのですが、何かいけなかったところ、改善が必要とされていたのか。それで、改めてこれを進めるという、何か理由があったのでしょうか。","respondent":"竹田住宅課長","answer":"各部署との連携は、ご指摘のとおり、従来からも取ってきたところですが、住宅団体、こういう方に貸したいという意欲のある不動産店を募ることによって、協力していただける方を明らかにし、また住宅の所管課である住宅課から一斉にお願いするというようなことをもって。","voiceIndex":50,"id":"exchange-019"},{"speaker":"西本委員","kind":"質問・要望","question":"だけど、「協力金６万円をあげるからやってね」と言うと、ノウハウもない中でやることになるので、やはりいろいろトラブルが生じる要因になるのではないかと思うのです。そこまでこの登録協力店というのはお願いしていかないと、人の命を預かるようなものでありますから、やはりそこはきっちりしていただきたいと思うのですが、いかがでしょうか。","respondent":"竹田住宅課長","answer":"私どもも、そういったノウハウを、仕入れた情報があれば、ほかの不動産店にもご紹介する形で、対応のノウハウ等を広めていきたいと考えております。","voiceIndex":52,"id":"exchange-020"},{"speaker":"西本委員","kind":"質問・要望","question":"「いろんなことがあるな」と。だから、皆さんにご理解していただくためには、そういう対応策、「こういう方がいらっしゃったときに、こういう対応をしていますよ」とか、あとは、品川区としては、お金だけ協力するのではなくて、サポートということはきちんと打ち出していかないと、せっかくのこういう事業も広がっていかないと私は思いますので、そのノウハウ、問題の共有化は、ぜひお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-021"},{"speaker":"塚本委員","kind":"質問・要望","question":"今までの議論をいろいろ聞かせていただく中で、ちょっと確認をさせていただきたいのですけれども、高齢者、障害者、ひとり親、それぞれ相談窓口は、品川区内で所管が違っていて、福祉の部門があって、それぞれで住宅確保要配慮者というところで住まいを探すということを、これまでも支援はしてきた。","respondent":"竹田住宅課長","answer":"物件の管理ということですが、私どもが具体的に物件を管理するというよりも、登録事業店の一覧を作るなり、そちらと情報共有といいますか、協力関係を、体制をつくる中で行っていくと考えておりますので、実際の、どの物件がある、ないというのは。","voiceIndex":56,"id":"exchange-022"},{"speaker":"塚本委員","kind":"確認","question":"物件の管理はそのとおりで、そういうことを聞きたかったのではなかったのですけれども、ちょっと聞き方が悪かったです。そういうことを、もう全部、住宅課が一元的にやるのですと。それで、高齢者地域支援課などは、問い合わせれば、「こういう物件がありますよ」と住宅課からご紹介するということに、一本化されるということでよろしいのかという確認です。","respondent":"竹田住宅課長","answer":"ですから、ぜひ、この制度を軌道に乗せて、それで高齢者地域支援課の事業と一本化して、より有効なものにしていきたいと考えています。","voiceIndex":58,"id":"exchange-023"},{"speaker":"塚本委員","kind":"質問・要望","question":"この辺のノウハウというのは、高齢者地域支援課も、そこまで一人ひとりに寄り添って物件の紹介というところまでは、どこまでできているかというのはありますけれども、そういう課題もこの事業にはきっとあるだろうと思うので、そういったことは居住支援協議会などでももしかしたら課題として語られたりしているかもしれないと思いますが、そういった。","respondent":"竹田住宅課長","answer":"そういった２番目の目的を達成することによって、相談者が、より多くの選択肢の中から、ご希望に近いものを選んでいただけるような仕組みを構築していきたいと考えています。","voiceIndex":60,"id":"exchange-024"},{"speaker":"のだて委員","kind":"質問","question":"権利者数を伺いたいのですが、全体としては１６名ということですけれども、土地所有者や借地権者、建物所有者、借家人など、それぞれの人数を伺いたいと思います。それと、この間の経緯を伺いたいのですが、ここの地区の、いろいろ事業をやってきたという説明はあったのですが、住民間での話し合いの経緯を伺いたいと思います。計画内容が分かれば伺いたいと思います。","respondent":"森木密整備推進課長","answer":"防災街区整備事業につきましては、共同化するということがとりあえず決まって、あるいは個別事業区というものが設定されて、その中で事業を進めていくというところでございまして、建物については、今の用途地域の中で。","voiceIndex":66,"id":"exchange-025"},{"speaker":"のだて委員","kind":"質問","question":"借家人は１５人ですね。それと、今、事業協力者が決まったということで、どこになったのかということも伺えればと思いますが、資料の裏を見ると、事業区域というのが、ジグザグというのか、いびつな形をしているのですが、それはどういうことなのかということと、あと道の下に、防災施設建築物と、あと個別利用区ということが書いてあるのですが、これがどういうことなのか分からないので伺いたいと思います。","respondent":"森木密整備推進課長","answer":"ほかの３名の方につきましても、例えば建物所有者の方が亡くなっていて、今、相続の調整をしているというところもありまして、そういった方々も含めれば、ほぼ全ての方々が、基本的には前向きに考えていただいていると認識しております。","voiceIndex":68,"id":"exchange-026"},{"speaker":"のだて委員","kind":"質問・要望","question":"いびつな街区を見ても、賛同されていない方もいるということで、やはり、まちづくりというのは住民の合意が必要だと思いますので、そうした住民合意を図っていくように、区としても事業者に求めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-027"}]},{"id":"topic-04","title":"広町地区に関する都市計画案","agenda":"広町地区に関する都市計画案","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"権利者数を伺いたいのですけれども、土地所有者、借地権者、建物所有者、借家人など、それぞれの人数を伺いたいと思います。関係権利者にどんな方がいるのかも伺いたいと思います。それと、今回、Ａ３資料の裏面の「その他都市計画」のところで、一部、防火地域から準防火地域に変えたり、日影規制が指定なしと変わるところがありますけれども、そうした変更をする理由を伺いたいと思います。","respondent":"多並都市開発課長","answer":"これを、土地利用の観点から、やはり北側の準工業地域ということで、大井工場敷地の土地利用に合わせたほうがいいだろうということで、今回、土地利用の観点から変更するという考え方で行われてあります。","voiceIndex":75,"id":"exchange-028"},{"speaker":"のだて委員","kind":"質問・要望","question":"質問をして、１回回答があって終了ということで、やはり疑問や不安がある方は、やり取りをしたいということですので、そうした中で議論も煮詰まっていくと思いますので、そうした開催の仕方も含めて、きちんと住民の意見を反映するようにやっていっていただきたいと思いますけれども、いかがでしょうか。","respondent":"多並都市開発課長","answer":"説明会の住民の方のご意見ですが、今おっしゃっているのは、恐らく３月に行った事業者説明会、経緯の中で書いてある説明会の件だと思います。","voiceIndex":77,"id":"exchange-029"},{"speaker":"のだて委員","kind":"質問・要望","question":"それで、今回、土地区画整理事業の決定ということで、必要な都市計画という中で出てきておりますけれども、この決定をされるのがいつになるのかというのでしょうか、具体的な日程というのは調整中ということでしたが、この都市計画決定がされると、土地区画整理事業も決定されるということなのか、その辺りを伺いたいのと、今回、区の土地とＪＲの土地を交換するわけですけれども、等価交換というのか。","respondent":"多並都市開発課長","answer":"ＵＲ都市機構が、その中で土地評価については法律に従って、評価につきましても複数名、評価者を３名程度と聞いていますけれども、複数名の方を評価者としてやって、換地が適正に行われているかどうか、評価が正しいかどうかについても確認するということで。","voiceIndex":79,"id":"exchange-030"},{"speaker":"のだて委員","kind":"質問","question":"今回、Ｃ地区ということで、東急の線路上もこの地区計画の中に入っているわけですが、Ｃ地区にも大きな高層ビルなどが建ってくるということになっていくのか、伺いたいと思います。今回、この地区整備計画の中では、Ｂ地区・Ｃ地区については、名前、範囲、面積が載っているだけということになっておりますが、今後、これを誰が変更して、いつ決めていくのか、伺いたいと思います。","respondent":"多並都市開発課長","answer":"今後の土地計画の変更等の考え方ですけれども、これも段階的整備ということで、今回先行してＪＲのＡ街区を中心として都市計画の決定を行っていく予定ですけれども、今後は、区の新庁舎の計画に合わせて、また必要な都市計画の決定、また、その後。","voiceIndex":81,"id":"exchange-031"},{"speaker":"のだて委員","kind":"質問・要望","question":"今、実際、劇団四季を見る方が通っておりますけれども、やはり商店街は通り過ぎていくだけという状況になっていると思うのです。その中で、今回、高架下のところ、Ｃ地区が計画内に入っておりますけれども、高架下のところが計画内に入っているということは、ここも建て替えというのですか、そうしたことがあるのか。追い出されてしまうという可能性があるのではないかと思うのですが、いかがでしょう。","respondent":"多並都市開発課長","answer":"それも一つ、検討していかなくてはいけないかとは思っていますので、そういういろいろな方策を、これからハードの整備を進めながら、ソフトについても並行して進めて、出来上がったときには、より大井町の活性化につながるような方策というのは。","voiceIndex":83,"id":"exchange-032"},{"speaker":"のだて委員","kind":"質問","question":"そうしたら、最後に１点。今回、Ｂ－２地区のところが、にぎわい施設ということで書かれております。今まで、にぎわい施設等ということで書いてあったような気がするのですが、今回、にぎわい施設ということで、どういったことを、つまり何なのかということをお伺いしたいと思います。","respondent":"多並都市開発課長","answer":"表記といたしましては、これも説明のときに、大井町のまちづくり方針の中で、行政機能と、あと、にぎわい機能ということで、にぎわいの施設ということで書かせていただいていました。","voiceIndex":86,"id":"exchange-033"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、このにぎわい施設というのは、まだ具体的に決まっていないということですが、この間、アリーナという話もありますが、アリーナも含めて検討中ということですか。","respondent":"多並都市開発課長","answer":"おっしゃるとおり、まだ、アリーナも含めて全て、要するににぎわい施設を何にするか、Ｂ－２地区については、今後の施設計画については検討中です。","voiceIndex":88,"id":"exchange-034"},{"speaker":"本多委員","kind":"質問","question":"資料を見させていただきまして、気になったので質問いたします。りんかい線や東急線がどのように、影響が出なければいいと思うのですけれども、全く支障がないのか、ちょっと心配になったので、その辺を教えてください。","respondent":"多並都市開発課長","answer":"りんかい線が、ちょうどここの地区の下に、円を描くというか、曲がって、ずっと入っているところです。今回の施設計画については、Ａ－２地区という、ＪＲの開発、広場にするところなのですけれども、ここが一部、下にりんかい線が通っています。","voiceIndex":91,"id":"exchange-035"},{"speaker":"本多委員","kind":"質問・要望","question":"分かりました。進めていく中でも運行に特に支障がなければ、それで安心できますので。アリーナも当然含まれますので、その辺は、やはり品川区のまちづくりで目玉がないというところで、ぜひここは目玉を創設していただきたいと要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":93,"id":"exchange-036"},{"speaker":"西本委員","kind":"確認","question":"確認なのですが、これは品川区とＪＲ東日本によるということなのですけれども、役割分担というのはどうなっているのか。例えばＡ－１地区からＢ－２地区という形で総合的にやっていくというのは変わらないと思うのですが、最終決断というのはどちらに権限があるのでしょうか。","respondent":"多並都市開発課長","answer":"Ａ３の資料の裏面の右側を見ていただくと、これが開発で、今おっしゃったようなＡ－１・Ａ－２地区はＪＲ東日本の開発計画の敷地です。左側のＢ－１・Ｂ－２地区は品川区の開発になります。","voiceIndex":95,"id":"exchange-037"},{"speaker":"西本委員","kind":"質問","question":"敷地で権限が決まるということで、恐らく提携しているので、お互いの協力性というか協調性というか、何でしょうか、ここは全体、外から見た限りだと、Ａ地区であろうとＢ地区であろうと一体なので、ちぐはぐな状況になってはいけないという思いはあるわけです。そこはもちろん提携が組まれているわけだから、調整を図っているのだろうとは期待はしているのですけれども、その具合はいかがですか。","respondent":"多並都市開発課長","answer":"今おっしゃっていただいたことがないように、ＪＲ東日本と品川区で、お互いに各地区の整備を一体的にできるように、まず、まちづくり方針という形で区で示しました。","voiceIndex":97,"id":"exchange-038"},{"speaker":"西本委員","kind":"質問","question":"これだけ広いと、当然ながら、自転車は通りたくなります。それと、地上部については、Ｃ地区の脇の道路というのですか、広いところが、今、自転車レーンがありますが、そこがちょっと危険で、今の状況だとちょっと危なくて、歩行者のところを通るのも怖いし、この辺の工夫も同時に進行されているのかどうか、考えられているのか、自転車に対しての考え方を聞きたいと思います。","respondent":"多並都市開発課長","answer":"計画の今後の変更への対応、柔軟性ですけれども、おっしゃるとおり、例えばＢ地区でこれから開発を考えた際に、Ａ地区も含めて変更が万が一必要になった場合には、それは区だけの思いではできなくて、ＪＲの敷地の中のＡ地区の地区施設を変えることになりますので。","voiceIndex":99,"id":"exchange-039"},{"speaker":"西本委員","kind":"質問・要望","question":"こういう要望があって、議会も「いいね」と言っているにもかかわらず、なかなか進まないというような状況があるやもしれない。そういったときに必要なのは、やはりこういう理由で、ＪＲの考え方はこうであって、だから今、協議中であるなどというのを、やはり情報提供を、ぜひ区民の方にお伝えしながら、にぎわいゾーンのところは設定していただきたいと思いますが、いかがでしょうか。","respondent":"多並都市開発課長","answer":"もう一つの、情報共有で、今後のいろいろご意見なのですけれども、これについても、もともとのまちづくりを考える点で、今回の関係者の中で、みんなで周辺住民も含めて使いやすいまちにしていこうということで、理念としては一致して進めているところでありますので、また。","voiceIndex":101,"id":"exchange-040"}]},{"id":"topic-05","title":"（仮称）新ＴＯＣビル計画事業者による近隣説明会の開催","agenda":"（仮称）新ＴＯＣビル計画事業者による近隣説明会の開催","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"権利者数を伺いたいのですけれども、これまでの件と同じく、土地所有者、借地権者、建物所有者、借家人など、それぞれ人数を伺いたいと思います。それと併せて、この間、ＴＯＣの建替えに当たって、旧第一日野小学校の貸出しをしていたと思うのですけれども、今回こういった建替え案が出てきて、旧第一日野小学校は今後どうなっていくのか、どう活用していくのかというところを伺いたいと思います。","respondent":"多並都市開発課長","answer":"これにつきましては、昨年の１１月に行財政改革特別委員会の中でも報告させていただいているかと思うのですけれども、この中で今後の予定として、保育園および荏原複合施設、仮で施設を建てる敷地ということで活用予定ということで報告させていただいているかと思います。","voiceIndex":107,"id":"exchange-041"},{"speaker":"のだて委員","kind":"質問","question":"分かりました。それで、容積率の緩和のところでは、指定基準に沿ってということですが、緩和するための施設というのですか、一つは公園があると思うのですが、ほかに、歩道上空地などもあると思うのですけれども、そういった施設としてはどのようなものがあるのか伺いたいと思います。そういった方々は、今後、建て替えた後に残ることができるのでしょうか。伺います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":109,"id":"exchange-042"},{"speaker":"芹澤委員","kind":"質問","question":"すみません。何点か簡単な質問をお伺いしたいのですが、先ほど、区の補助がない民間の開発ということで、これは、民間の開発がそもそも議会に報告される判断基準というのは、都市計画か何かが出てくるからということなのでしょうか。","respondent":"多並都市開発課長","answer":"もう一つの公園ですけれども、これについては、現時点の考え方としましては、区に提供されて、公共の公園となる予定としておりますが、ただ詳細については今後、具体的に詰めていくということで考えております。","voiceIndex":113,"id":"exchange-043"}]},{"id":"topic-06","title":"品川区立環境学習交流施設の愛称決定","agenda":"品川区立環境学習交流施設の愛称決定","exchanges":[{"speaker":"西本委員","kind":"質問","question":"新しい愛称が決まったということなのですが、寺田さんに対しての発表というか、応募者の寺田さんなのですけれども、表彰や、何か告知は、全体的に告知はされるのですか。品川区民の皆様方に、こういう方が応募して選ばれましたというものをやるのでしょうか。","respondent":"河内環境課長","answer":"ご氏名などは公表する予定で、あと、込められた意味、趣旨につきましては公表いたしますが、そのほかにつきましては一応、個人情報というところで、伏せさせていただいているところです。","voiceIndex":120,"id":"exchange-044"},{"speaker":"西本委員","kind":"質問","question":"多分、１０歳だとすると、学校に行っているのですよね。区立なのか公立、私立なのかはあれですけれども。でも、そこはやはりお礼というか、何かできないのですか。","respondent":"河内環境課長","answer":"お礼は２つということで、１つは、こちらの、景品ではないのですが、地域の商品券ということで贈呈するとともに、現在、検討中、予定ではありますが、こちらの開設式のときに、先ほど親子の話が出ましたけれども、親子でご招待させていただきまして、ぜひというところで。","voiceIndex":122,"id":"exchange-045"}]},{"id":"topic-07","title":"品川区立環境学習交流施設指定管理者候補者の選定","agenda":"品川区立環境学習交流施設指定管理者候補者の選定","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"今回、指定管理者選定に当たって、選定委員会を設置するということですが、選定委員会のメンバーはどういった方になるのか、知識人というのか、専門家も入れてやるのかどうか、伺いたいと思います。","respondent":"河内環境課長","answer":"高い、低い、いろいろな考え方が内容によってありますが、同程度の建物を全国比率で考えまして、平米単価などを割り返し、また人件費の内容なども精査いたしまして、適正な価格において、こういったものがなされるかどうかを精査するという意味で。","voiceIndex":128,"id":"exchange-046"},{"speaker":"のだて委員","kind":"質問・要望","question":"経費の縮減というところで、同程度の施設と比較してということでしたけれども、何か特色のあることをやろうとするとお金がかかるということもあったりするので、そういったところは、やはり実態を見てというのでしょうか、住民の環境意識を考慮していくというところで、しっかりと経費はつけていくということでやっていただきたいと思いますが、いかがでしょう。","respondent":"河内環境課長","answer":"そういったところの運営を適切にやることによりまして、節減額の正確な積算でありますとか、そういったところを考慮いたしながら、運営に適切な事業者を選んでいくという趣旨です。","voiceIndex":130,"id":"exchange-047"},{"speaker":"西本委員","kind":"質問","question":"だから、公募型プロポーザル方式ということなのですけれども、当然これがベース、できて当たり前という方々が公募されてくるのだろうと思うのです。それをどういうふうに、選定する側としてどういう意識を持っているのか。選定する側にその意識がなければ、何だろう、選んだところが将来性がない場合も多々ある可能性もあるので、選定する側の考え方についてお聞きしたいと思います。","respondent":"河内環境課長","answer":"大きな特色と私が認識しておりますのは、狭山市の博物館ですが、元直営のところを、指定管理者を受けたところで、７５％の集客の向上を見たという点。","voiceIndex":133,"id":"exchange-048"},{"speaker":"西本委員","kind":"質問","question":"選定する側の意識というのは非常に大切だと思っているのですが、１点、もちろん実績というのは大切だと思います。ただ、実績だけではなくて、実績はあまりないが、いろいろな発想がある。指定管理者ですから、非常に管理者のほうの自由度というものを認めていただいて、それで環境という意味での認知度が上がっていくといいと思っているのですが、その辺はいかがですか。","respondent":"河内環境課長","answer":"私どもが押されるほどのアイデアをいろいろ出してくださっているところもございまして、今後また運営を進めて、仮にですけれども、運営をしていくにしたがって、区民の方から、いろいろな細々したところの便利な情報など、それから使い勝手など。","voiceIndex":135,"id":"exchange-049"}]},{"id":"topic-08","title":"東京港大井ふ頭（都有地内）において確認された「ヒアリ」","agenda":"東京港大井ふ頭（都有地内）において確認された「ヒアリ」","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"この間、ヒアリが度々確認されていると思うのですけれども、今までは区内に生息しているということはないというお話だったのですが、今回も海外から運んだ荷物にくっついてきたということでいいのかというところを確認します。","respondent":"河内環境課長","answer":"おっしゃるとおりでございまして、何か、くっついてきたと言い方はあれですけれども、付随してきたというところで、環境省の見解によりますと、日本への定着はないということで報告されているところです。","voiceIndex":141,"id":"exchange-050"}]},{"id":"topic-09","title":"その他","agenda":"その他","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回、調査掘進をするということで説明会がされるということですが、調査掘進というのはどういうものなのかということなのですが、具体的に言うと何ｍ掘っていくのかとか、どういうことをやられるのかということをちょっと伺いたいと思います。裏面に、家屋調査の実施ということで、これからやられるのですかね。もし進んでいるところがあれば、何件進んだのかなど、聞いていましたら伺いたいと思います。","respondent":"中道まちづくり立体化担当課長","answer":"調査掘進ですが、今、ＪＲ東海は掘進に伴いまして、使用する材料であったり施工管理の徹底、または地上部の隆起するか、しないかといった形の計測であったり、振動、騒音などの、やはりマシンに見合ったどのような計測をすべきかということを検討はしてきたです。","voiceIndex":147,"id":"exchange-051"},{"speaker":"のだて委員","kind":"質問","question":"家屋調査のほうは、実際にもう入ったところもあるということですか。実際にどこまで進んでいるのかというところを伺いたい。","respondent":"中道まちづくり立体化担当課長","answer":"ＪＲ東海から、まだ建物の具体的な調査というよりも、区民に対しての調整というのでしょうか、そういったビラを配って今現在調整中というところで聞いてあります。","voiceIndex":149,"id":"exchange-052"}]},{"id":"topic-10","title":"の３、所管事務調査","agenda":"の３、所管事務調査","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"そうした子どもたちの安全確保、先ほど通学路安全・安心プログラムということでご説明もありましたけれども、そうした対策をしっかりとやっていっていただきたいと思うのですが、これは通学路ということなので、保育園などの移動経路についての安全確保というのはどのようにされているのか、するべきだと思うのですが、そこはいかがでしょうか。伺いたいと思います。","respondent":"川口交通安全担当課長","answer":"その後、各個別の対策につきましては、それぞれいろいろご要望をいただいているところについては適切に対応しています。","voiceIndex":156,"id":"exchange-053"},{"speaker":"のだて委員","kind":"質問・要望","question":"未就学児のところでは、要望をもらったところでは対応しているということですが、区として安全対策のチェックというのはやられていないのかどうか。それと、生活道路の中でゾーン３０をやられているということで、実際、今、何か所というのが分からないのですけれども、どの程度指定されていて、区として効果がどれだけあるという評価をされているのか、伺いたいと思います。","respondent":"溝口道路課長、川口交通安全担当課長","answer":"未就学児の、整備の関係ですので、私からお答えします。令和元年に未就学児、かなりの、品川区全体でいきますと、２５２園ほどを対象に、全て安全点検を実施したところです。ゾーン３０設置後の効果というのは、具体的に区内の場所ではないのですけれども、一般的に、ゾーン３０が設置された場所につきましては非常に効果があって、例えば速度が低減されたことによる。","voiceIndex":158,"id":"exchange-054"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、ゾーン３０については、区内で具体的に、なかなか難しいですけれども、事故がここで、ゾーン３０にしたことで減ったなどといったことは、今のところないということなのですか。","respondent":"川口交通安全担当課長","answer":"具体的にそちらの部分について、警察から情報の提供等を受けているところではございませんけれども、今後そのような形で、効果等については警察等からの情報を聞いてまいりたいと考えております。","voiceIndex":161,"id":"exchange-055"},{"speaker":"のだて委員","kind":"意見","question":"子どもの安全の確保のところで、保育園などがチェックされて、対策は終わっているということで、そうすると、通学路は３年ごとにチェックするということですが、保育園も定期的なチェックというのはされていくのかどうか、いかがでしょう。","respondent":"川口交通安全担当課長","answer":"こちらにつきましても、今後、保育の部局等と連携しまして、どのような形でそのような対策が取れるかといったことは検討してまいりたいと考えております。","voiceIndex":163,"id":"exchange-056"},{"speaker":"のだて委員","kind":"質問・要望","question":"前回は、戸越三丁目交差点と、具体的なところを言いましたけれども、そこだけでなく、やはり要望のあるところ、必要なところに、ぜひ設置を区としても進めていっていただきたいと思いますけれども、いかがでしょうか。今回、この計画は、パブリックコメントを今やられているということで、今、コメントが何件来ているか、把握されているところがありましたら伺いたいと思います。","respondent":"溝口道路課長、川口交通安全担当課長","answer":"そういったものをできる限り受けた形で、整備できるところは整備していきたいとは考えているところではありますが、なかなか物理的に設置できないというところもありますので、そういったところは、よく団体ともお話をしながら。現在のパブリックコメントの状況ですけれども、お一人の方から複数のご意見をいただいている部分もありますけれども、現在まで１９件ほどいただいているところです。","voiceIndex":165,"id":"exchange-057"},{"speaker":"芹澤委員","kind":"質問・要望","question":"何点かお伺いしたいのですが、まず、安全講習、自転車のルールの徹底について、イメージ的には、よく小学校などで自転車のルールというか、教えているイメージがあるのですけれども、今、自動車の免許を取る人がどんどん減ってきて、大人になってからなかなか、車というか、道路交通法のマナーを学ぶ機会というのがどんどんなくなってきているように思えて。","respondent":"川口交通安全担当課長、溝口道路課長","answer":"主婦など、日頃、自転車をお使いになられる方が、自転車の講習の機会に参加していただくこともなかなか難しい部分がありますので、例えばなのですけれども、２枚目の（４）にありますような。これにつきましては、やはり一定以上の道路幅員がないと難しいというところがありまして、多分、特に自転車の専用通行帯という形での整備をしているのだと思いますが。","voiceIndex":169,"id":"exchange-058"},{"speaker":"本多委員","kind":"質問・要望","question":"すみません。簡潔に１点お聞きします。それで、自主返納というと、どうしても本人の意識になると思うのですが、本人に限らず、高齢者のドライバーの家族が背中を押すような、やはり啓発などが必要ではないのかと思いまして、警察が、ある程度効果が上がると、それほど積極的にやらなくなったりすると思うので、これは品川区として積極的に啓発していただきたいと思います。その１点だけ質問いたします。","respondent":"川口交通安全担当課長","answer":"いわゆる高齢ドライバーのご家族のための家族相談会等をやっているというところがありますので、そのような開催情報を収集しまして、品川区からも、このような相談会が実施されているのでということで、ご案内をしてまいりたいと考えております。","voiceIndex":173,"id":"exchange-059"},{"speaker":"塚本委員","kind":"質問・要望","question":"特にいろいろ交通安全対策ということであるわけですけれども、ここでも言われている、自転車の事故が増加していますというところで、これについてお伺いしたいのですけれども、非常に大きな伸びを、前年比と比べてもされているというところで、この原因です。やはり、交差点での出会い頭や、夜間に無灯火で運転している方など、そういうものが何かあれば教えていただきたいと思います。","respondent":"川口交通安全担当課長","answer":"自転車の関与事故の中で、自転車に乗っている側に法令違反があった数というのが、平成２８年のときに１１６件で、自転車側に違反がなかったものが１２９件だったのですけれども、令和２年になりまして、これは逆転してしまいまして、自転車側に違反があったものが２１９件で。","voiceIndex":176,"id":"exchange-060"},{"speaker":"塚本委員","kind":"質問","question":"ありがとうございました。そういうのはやはりすごく意味があるのかと思うのですが、そういったことというのは、今、区あるいは警察でどの程度やっているのかということと、また、今後活発にそういうものをやっていくということについてはどうなのか、いろいろな課題などというのはあったりするのかというところをお伺いしたいと思います。","respondent":"川口交通安全担当課長","answer":"自転車安全利用キャンペーンというふうに、（４）のところにもありますけれども、警察ですと、そこで実際のルール、マナー違反があった場合については、当然これは単なる啓発だけではなくて指導等も行われていることで、令和２年度中には。","voiceIndex":178,"id":"exchange-061"},{"speaker":"西本委員","kind":"質問","question":"非常に邪魔だと。それから、自転車も多分、どこを通るかということでは、自転車レーンのところを通るのだと思うんです。そうすると、このポールというのは、有効性は認めるのですけれども、有効性もありますが、ぶつかったり、いろいろ巻き込まれたりということがあるので、その辺の具合というのは、設置の条件というのは何かあるのでしょうか。","respondent":"溝口道路課長","answer":"今回、後地の交差点は、事故等の発生を受けた、また、いろいろ、未就学児など通学路にもなっているですので、そういった中で何を優先して整備していくのかというところの観点が１つありました。","voiceIndex":181,"id":"exchange-062"},{"speaker":"西本委員","kind":"質問・要望","question":"分かるのです。優先順位はいろいろあるかと思いますので。そうすると、大幅に道路のほうに出ないと走行できないという現状があって、何とかならないかというのが１つあるのです。その中で、例えばＵｂｅｒ Ｅａｔｓなど、あまりメーカーを言うといろいろあるのですけれども、自転車での配送業というのですか、そういうものがかなり品川区内も走っています。これは何とかならないのでしょうか。","respondent":"川口交通安全担当課長","answer":"というのは、例えば具体的に、品川区内に事業所があって、そこから配達する、特定の、いわゆるインターネットでアルバイト登録をしてやるという、なかなか難しいところがあるというところで、今、警視庁では、その運営会社の責任者を警視庁本部に招致しまして。","voiceIndex":183,"id":"exchange-063"},{"speaker":"西本委員","kind":"質問・要望","question":"事故などはないのでしょうか。その方が言っていたのは、自転車だったら電気をつけないといけないじゃないですか。あまり私も車椅子というのは頭になかったのですけれども、あと、夜もそんなに出歩かないだろうという思いもあったのですが、意外と、薄暗くなったときに非常に危険だという指摘を受けましたので、何か手だてみたいなものがあるかどうか、お聞きしたいと思います。","respondent":"川口交通安全担当課長","answer":"その辺の周知の方法をどうするかにつきましては、交通安全とはまた別に、そういうのはやはり障害者担当の部局などとまた連携を図って、何かそういう広報啓発など、周知できないかというところを検討していきたいと考えております。","voiceIndex":185,"id":"exchange-064"},{"speaker":"西本委員","kind":"質問・要望","question":"暗いと、よく見えない。それで、実際、低いので、なかなか見つけにくいという状況があるので、そこは反射板とか、電気をつけるなど、そういうのができるといいと思っているので、これはまた、いろいろなところで要望させていただきたいと考えています。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":187,"id":"exchange-065"},{"speaker":"大沢副委員長","kind":"意見","question":"さっきのママチャリの件で、周知徹底するという、課長からお話しいただいたのですけれども、周知の徹底などという甘ったるいことでは減らないですよ。ママチャリは、ご覧になってお分かりのように、重いし、電動アシストでもついていれば自転車ではないですよね。さっき、周知徹底などと、周知などという甘ったるいことを言っていては減らないと思うのだけど、そこをどういうふうにお考えになりますか。","respondent":"川口交通安全担当課長","answer":"確かに、電動アシスト自転車は、一方では当然、補助機能がありますので、危ないような状況もありますし、また、お母様方に日頃から、そのような形で周知するとお話をさせていただいたのですけれども、やはり具体的に、例えばこのような事故が発生したりしているなどということで。","voiceIndex":189,"id":"exchange-066"},{"speaker":"大沢副委員長","kind":"意見","question":"周知の中で、お母さんたちは余裕がないのですよ。だから周りが見えていないので、時間帯を見ればお分かりになるように、１０時から１２時だったり、１６時から、まさにお迎えの時間だったり、送っていく時間だったりと、こんな時間なのです。これは東京都のあれだから。だから、そこのところは、やはり指導方していかないと、この問題は済まないと思うのですけれども、もう一回お願いします。","respondent":"川口交通安全担当課長","answer":"当然、いわゆる生活に余裕がないというようなお話もいただいている中で、そのような方々にも、しっかりと指導できるような形を検討してまいりたいと考えております。","voiceIndex":191,"id":"exchange-067"},{"speaker":"大沢副委員長","kind":"質問・要望","question":"生活に余裕がないなどと、そんな失礼なことは私は言っていない。その余裕のない中でお母さん方はやっているから、その辺でも、ちょっと余裕を持って行くような、先ほど言っていた、指導ができないのだったら周知するような、何か言葉か何かあるのではないのですかという話なので、生活に余裕がないなど、今の日本国ではあり得ませんから、だから、そこのところは今、訂正していただきたいと思います。","respondent":"川口交通安全担当課長","answer":"そういうお母様方の生活スタイルなりを見て、例えば保育園側にも要請していただいて、安全利用に関するリーフレットの配布を依頼するなど、警察とも連携して、どのような機会を設けて安全教育等を行えるのかというところも、併せて検討していきたいと考えています。","voiceIndex":193,"id":"exchange-068"},{"speaker":"大沢副委員長","kind":"意見","question":"それと、もう一つですけれども、高齢者の方、交通事故の概況の年代層、高齢者が増えているというけれども、これは増えるよね。なぜかというと、人口のボリューム増が多いのだから。それをもって、全体的な人数と、割合のパーセンテージで論ずるのなら分かるけれども、ただ単に人数だけ出しているのでは、これは数字のマジックと捉えられてもしようがないのだけど、どう思いますか。","respondent":"川口交通安全担当課長","answer":"確かに今ご指摘のとおり、全体的な高齢者の人口も区内は当然増えておりますので、そのような形になってしまうのですけれども、やはり人口推計と高齢者の関与率なのですが、一応、品川区の現在の（第１１次品川区交通安全計画の）素案にも書かせていただいているのですけれども。","voiceIndex":195,"id":"exchange-069"},{"speaker":"大沢副委員長","kind":"質問・要望","question":"２番のところで、今度、第１１次交通安全計画というところもありますので、今お話ししたお母様たちの若年層、そして高齢者の両立てでお考えいただきながら、第１１次の計画について当たっていただきたいと思います。以上です。答弁は要らないです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":197,"id":"exchange-070"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4328#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":64257,"voices":200}},{"id":"r03-20210818-9","meetingId":"r03-cm08","date":"2021年8月18日","dateIso":"2021-08-18","committee":"文教委員会","time":"午後 １時００分～午後 ３時３４分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を48件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和２年度品川区立学校における体罰等の実態把握","agenda":"令和２年度品川区立学校における体罰等の実態把握","exchanges":[{"speaker":"松本委員","kind":"質問","question":"これは東京都からの調査依頼だと思うのですけれども、調査対象で、教職員、児童・生徒というふうになっているのですが、申告者別報告数で保護者が出ていたり、地域住民という枠があるのですけれども、イメージとしては、教職員に対しては校長先生から聞き取り調査、児童・生徒は質問紙を配っているというふうに思うのですが、保護者と地域住民という枠がある、そしてまた保護者からが１件となっているのは。","respondent":"工藤指導課長","answer":"例えば当該学校に対するお問合せなどが電話であった場合は、その当該学校に関して調査をするということですから、報告件数として上がってくるです。","voiceIndex":15,"id":"exchange-001"},{"speaker":"松本委員","kind":"質問","question":"今の点で、本調査というのは、品川区が把握していることにこれを加えているのか、それとも東京都への報告に対しても、今の地域住民とか保護者からというのを含めて報告するのか、そちらはどうなっているのでしょうか。","respondent":"工藤指導課長","answer":"例えば保護者からの報告は、当該児童・生徒の保護者からの声も含めて、東京都への報告も、品川区が把握しているものと全く同じものです。品川区教育委員会で把握したものは、全て東京都に報告をするです。","voiceIndex":17,"id":"exchange-002"},{"speaker":"松本委員","kind":"確認","question":"たしか以前確認したところだと、これは担任が児童・生徒に配って、記名式で回収するというふうになると、やはり抵抗があるのではないかと思うのです。お願いします。","respondent":"工藤指導課長","answer":"そういった課題があるということは、私ども東京都教育委員会のほうに情報提供しながら、実際にすぐ改善するかというところは、また協議をいただくことになりますけれども、声のほうは東京都教育委員会のほうにお伝えしています。","voiceIndex":19,"id":"exchange-003"},{"speaker":"松本委員","kind":"質問・要望","question":"これはいじめも同じだと思うのです。目安箱を置きましたというだけでは、じゃあ、何を届け出たらいいのか。なので、目安箱はどういうものを投函したらいいのかという具体化と、ＬＩＮＥ、スマホを使った通報システムの構築というものが必要になってくるかなと思うのですが、その辺り、これは要望も含みますが、ご見解をいただければと思います。","respondent":"工藤指導課長、矢部教育総合支援センター長","answer":"そういう意味では、現在、タブレットを使った活用というのを検討しているところもありますので、そういったものを含めて、子どもの声を拾うセーフティネットは広いほどいいと私どもも認識しておりますので。もう１点は、子どもたち１人１台配付させていただいていますタブレットに、相談機能、チャイルドライン、アイシグナル等をつけて、子どもが直接自分のタブレットからＳＯＳが出せるような仕組みにしております。","voiceIndex":21,"id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"ご存じのように昨年４月から、親などによる体罰禁止を明記した改正児童虐待防止法というものが施行されて、同じ年の２月、先立って厚労省が、体罰の定義や範囲などを取りまとめたパンフレットを出しました。法律の施行前と後で、何か変化があったのかというのを伺いたいというのが１点です。これを見てとても思うのですけれど、その辺りはどうなのでしょうか。伺いたいと思います。","respondent":"工藤指導課長","answer":"学校教育法第１１条で規定されている体罰の禁止に基づき、私どもで言えば、体罰の定義は、東京都教育委員会が作成するものに基づきながら行っているところです。ただし、これは許されるものではないという認識のもとで、私ども指導に当たっているというのは、体罰と変わるところではないというものです。","voiceIndex":25,"id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"それはぜひお考えを伺いたいと思います。ですから、ここはもう改善が必要だと、私も意見として言います。１年前のこの同じような報告のときに伺ったのですが、小学校の児童については、先生からされて嫌なことはありますかみたいな感じで、年齢に応じてソフトに聞いているという話を伺いました。子ども自身の申告、調査の仕方と併せて、ご見解を聞かせていただきたいというのが、次の質問です。お願いします。","respondent":"工藤指導課長","answer":"引き続き、そういったことを取り組んでまいりたいと考えているところです。","voiceIndex":28,"id":"exchange-006"},{"speaker":"安藤委員","kind":"確認","question":"やはり、最新の体罰、虐待という、社会問題が大きくなって法も変わったわけですから、そういう最新の世論の動き、国の知見というものを踏まえたものに、ぜひ改善していただくよう、そこは都に特に意見するというご答弁はありませんでしたけれど、ぜひ再度お願いしたいと思います。詳細を確認して臨めなかったので、不勉強で申し訳ないのですけれど。その活用の状況を伺いたいと思います。","respondent":"工藤指導課長","answer":"こちらにつきましては全学校に配付されてあります。ただ、毎年度、７月、８月は体罰防止月間ということで、特に重視して行ってありますので、その中においては適宜活用いただいて、見ていただくと。","voiceIndex":30,"id":"exchange-007"},{"speaker":"安藤委員","kind":"質問・要望","question":"やはり児童・生徒、保護者、学校、子どもに関わる全ての大人、社会が、体罰とは何なのか、それが子どもにどういう影響を与えてしまうのか。今後、私ももう少し詳しく勉強して、このＤＶＤの内容なども確認したいと思うのですけれど、そういう動きを全体でつくっていくことが必要だと思いますので、教育委員会としても、今後とも努力をいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-008"},{"speaker":"吉田委員","kind":"質問・要望","question":"ＤＶＤの「ＳＴＯＰ体罰」、これはぜひ質問しようと思っていたら、今お答えがあったのですけれど、子どもたちにとっても、これは体罰なのだよ、これは嫌だと言っていいのだよということが、含まれている内容と理解したのですけれど、それを見る機会を、たしか７月、８月ですか、ですけれど、もし調査を１２月１日から１２月１８日までの間に実施するとしたら、これは東京都の教育委員会の調査ですけれど。","respondent":"工藤指導課長","answer":"早い時期に何が認められるのか、認められないのかという把握も必要だと思いますので、そういった意味では、ご指摘いただいたようにＤＶＤの活用についてはときを選ばず、また、区としても１２月実施の時期も含めながら。","voiceIndex":34,"id":"exchange-009"},{"speaker":"吉田委員","kind":"質問","question":"目安箱のことについてはそういう声があるので、見解を伺いたいと思います。現にそういうことを目撃したという保護者の方とか、生徒の声は聞いております。ただ、公式的なところで質問すると、いや、そういう事例はないというふうになるので、その辺のギャップを埋めるような工夫がどこかでされるべきだと思うのですけれど、その辺についてはいかがでしょうか。","respondent":"矢部教育総合支援センター長、工藤指導課長","answer":"そのほか、目安箱以外にもスクールカウンセラーとの話の中で、先生との対応について話が出ることもありますので、そのような様々な窓口の中で解決いくものと考えております。ですので、例えば保護者の声があったとき、私ども学校も含めて調査するときには、どんな状況だったかということの把握に努め、その上で判断をするですので、襟首をつかんで連れ出しただけで。","voiceIndex":36,"id":"exchange-010"},{"speaker":"吉田委員","kind":"質問・要望","question":"それはもう当然だと思います。だから、その事象だけ見ても判断はつかないというのは承知しております。その辺については、ぜひ適切な、それぞれの判断、配慮をしていただければと思います。子どもの意見表明権とともに、その子どもの意見表明権を後押しするというか、そういうような制度も、私たちとしては求めているのですけれども、その辺、教育委員会では何かご見解があれば伺いたいと思います。","respondent":"矢部教育総合支援センター長","answer":"現状では、学級活動や市民科の学習を通して、自信を持って自身の意見を話すという活動がありますので、様々な情報を取り入れながら、子どもたちにとって自分の考えが言えるような場を設定していきたいと考えております。","voiceIndex":39,"id":"exchange-011"},{"speaker":"吉田委員","kind":"質問・要望","question":"言うまでもなく、東京都にこども基本条例ができましたし、その中では、今後は意見表明権とともに、それを補完するというか後押しするアドボケイトの制度も、おいおい検討されていくべきだと思います。それは別にこの体罰調査だけではないのですけれども、こういう調査の中にも今後取り入れていただければと思います。これは要望にとどめておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-012"},{"speaker":"松澤委員","kind":"質問・要望","question":"という感じですと、私だったらやはり校長先生には言いづらいと思ってしまったりするので、やり方というのもまた、いろいろ品川区で独自に考えていただけたらということは、要望で終わります。でも、寝ている子の身体を起こすとそれは体罰になってしまうのですかね。そういったところはどうでしょうか。","respondent":"工藤指導課長","answer":"もちろん、指導がやりにくくならないようにというのを前提にしながら、指導に当たっていきたいと考えています。","voiceIndex":43,"id":"exchange-013"},{"speaker":"松澤委員","kind":"質問","question":"そうですよね。これが今の時代では間違いかもしれない。おっしゃるように、体罰というのは本当に絶対駄目なことですよね。体罰が駄目ということはもう十分分かっている中で、体罰をなくすには正当化しない、信頼を築く、怒りをコントロールする、こうしていろいろ言われている中で、信頼を築く一つに、今、あだ名を言ってはいけないというのですか。そういった部分で何か考えていることはあるのですか。","respondent":"工藤指導課長","answer":"ご指摘いただいた例えばアンガーマネジメントとかは、明記してございませんけれども、３ページの取組にある、（１）学校への指導の、具体的な指導の実施、この内容にはアンガーマネジメントであるとか、当然含まれるのですが、これまで不適切な指導で上がっている内容でいうと。","voiceIndex":45,"id":"exchange-014"},{"speaker":"松澤委員","kind":"質問・要望","question":"これは、実は児童虐待と同じようなメカニズムであるとされています。おっしゃるとおり体罰という行為は悪いのですけれど、してしまった原因、品川区はなかったけれど、何でしてしまったのだろうという、してしまった原因というのも大切になるのかなと思いますので、私も含めて、議会も、教育委員会も含めて、先生たちのそういう環境がさらに深まるよう要望して、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-015"},{"speaker":"つる委員","kind":"確認","question":"各委員の質疑で確認させていただいたこともありますので、そこは除きます。平成２４年から調査がスタートして、報告は平成２５年からこの文教委員会でも、品川区としてあると思うのですが。最初の平成２４年に実施したものは、平成２５年の４月の委員会で、実態把握について報告をされていたのですけれど、この年度によって報告の時期のずれというのは、何か意味があるのでしょうか。","respondent":"工藤指導課長","answer":"ですので、通常であれば１２月の時期に調査が行われ、６月末までには報告があり、その後、教育委員会の報告を経て文教委員会ということですから、おおむね７月ないしは８月には報告できるものというのが通常の流れということで、認識しています。","voiceIndex":49,"id":"exchange-016"},{"speaker":"つる委員","kind":"質問・要望","question":"これはいい意味なのですけれど。体罰の根絶というのは、私も平成２５年の委員会のとき、当時の指導課長に伺って、大人のする行為なのだと、だから根絶できるのだと、もう明確に宣言されていらっしゃったのですよね。これは一つ思うところであります。こういう事例というのは、報告の分類でいくと何になるのですか。これというのは、どういう分類になるのですか。明らかに体罰ですよね。一般論でいいです。","respondent":"工藤指導課長","answer":"仮定に対してお答えするのはなかなかあれですけれども、様々な状況がある中でも、今お聞きしたところでいえば、間違いなく体罰に該当する案件だと認識いたします。","voiceIndex":53,"id":"exchange-017"},{"speaker":"つる委員","kind":"質問","question":"これ、実は８年前に、この文教委員会で私が伺っているのです。私の実体験ですけれどと。８年前の質疑で、まさに１回目のこの報告をしていただいたときに、自分のことなのですけれどということでお伝えした案件です。ですが、８年前の質疑の中でも、当然それはよくないことですよねと。物すごく印象に残っているので。これ、８年前に言っていますから、別に特出しして言っているわけではないですけれど。","respondent":"工藤指導課長","answer":"実際に、にらむということ、あるいは無視をすることが、教育的な意義があって一時的に教員がどういうことで行っているのかというのを把握しないと、なかなか難しいところですが、あくまでもやはり児童・生徒指導というのは、公平、公正に行う必要があり。","voiceIndex":55,"id":"exchange-018"},{"speaker":"つる委員","kind":"質問・要望","question":"ありがとうございました。本当にこの課題は非常に難しいというところで、日常、保護者の立場でいろいろ見聞きすること、また、今回は文教委員会に、私も所属していますけれど、いわゆる区民の代表者として伺う部分と、様々種々あるのです。そういうのを伺う中では、学校の先生たちというのは、現場で本当に必死になって、児童・生徒に関わっていただいているというのは、すごく強く感じているところなのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-019"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"先日、１６日の四者協議で、学校連携観戦を可能とする方針が決められたのですが、品川区教育委員会としては、７月１３日の教育委員会に諮るなどして、学校連携観戦については、パラリンピックを含めて実施しないと決めたわけですが、この方針に変わりはないということでよろしいのか、確認させていただきたいと思います。","respondent":"工藤指導課長","answer":"パラリンピックにつきましても、委員ご指摘いただいたとおり、先だって中止したというところから変わりはございません。パラリンピック観戦も行わないというのは、既に決定したとおりです。","voiceIndex":60,"id":"exchange-020"},{"speaker":"安藤委員","kind":"質問","question":"パラリンピックの問題ですけれど、２４日から予定されているのですが、先日、四者協議の中で、学校連携観戦については可能だとする方針が決められたという報道が流れていますけれども、改めてこの間、子ども未来部でも保育園児に対して、一部で連携観戦というのを進めていたと思うのですけれど、それは中止になったと認識しているのですが、改めて今の時点で、保育園児の観戦について。","respondent":"廣田子ども育成課長","answer":"本日、保育の案件がございません関係で所管課長がおりませんので、私の知っている範囲で代わりにお答えします。学校連携観戦に関しましては中止ということで、所管から聞いております。現在も中止です。","voiceIndex":134,"id":"exchange-021"},{"speaker":"安藤委員","kind":"確認","question":"分かりました。子ども未来部としても、進めていた区立保育園と一部の私立保育園の観戦についても、中止になっているということで、確認させていただきました。それで私もいいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":136,"id":"exchange-022"},{"speaker":"安藤委員","kind":"質問","question":"陰性の方であっても、いろいろ判断で、しばらく自宅待機というか、すまいるを利用しないということだと思うのですけれど、すまいるが利用できなくてかなり困るご家庭もあると思うのですけれど、そういった相談というか、どういう相談がどれぐらい来ていて、それに対して区はどのように対応されているのか、１点お伺いしたいのと。改めてお聞かせいただければと思います。","respondent":"廣田子ども育成課長","answer":"６名はばらばらと感染者が出ていたので、その都度保健所とご連絡をとり、濃厚接触者はいませんという形で継続していたのですけれども、今回の検査のお知らせをした段階で、保護者の方からお問合せもいろいろいただきました。","voiceIndex":140,"id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"やはり知らず知らずのうちに、無症状の感染者が感染を広げてしまうという事態を未然に防ぐためにも、特に大勢のお子さんが集まる子どもの施設、すまいるスクールは特にそうだと思うのですけれど、定期的な職員へのＰＣＲ検査というのは、やはり必要なのではないかと思いますし、ぜひそうしたことを検討していかなくてはいけない、実施していかなくてはいけないのではないかと思うのですけれど。","respondent":"廣田子ども育成課長","answer":"今回も２００件以上の検査をしておりますけれど、必要なときには大量であろうと、職員が全部検体をとるのですけれども、やりますし、必要に応じてこれまでも、これからも実施していこうと思っているところです。","voiceIndex":142,"id":"exchange-024"}]},{"id":"topic-03","title":"を改めて聴取いたします。 初めに、(2)児童センターの工事","agenda":"を改めて聴取いたします。 初めに、(2)児童センターの工事","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"南大井のほうですけれども、今回、児童センター部分だけ空調の緊急工事を行ったということですけれど、施設全体の空調改修工事が予定されていたということで、それに対する影響というのは何かあるのですか。","respondent":"廣田子ども育成課長","answer":"その他の施設につきましては、予定どおり次年度に行うのですけれども、一緒にやるよりも若干、今回割高にはなってしまったかなというところは、あるかと思います。","voiceIndex":67,"id":"exchange-025"}]},{"id":"topic-04","title":"要支援家庭を対象とする児童のショートステイ","agenda":"要支援家庭を対象とする児童のショートステイ","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"プレス発表にも載ってはいましたが、今回この事業をつくるに当たって、景徳学園と、いつからどのような意見交換ですとか議論を経て、開設に至ったのか、もう少し伺いたいと思います。それとあわせて、虐待のリスク等が見られる家庭（要支援家庭）ということですが、この選定基準、選定という言い方もあれですけれど、その基準というのはどのようになるのか、伺います。","respondent":"山下子ども家庭支援センター長","answer":"２点目のリスク等の基準というお話ですが、これについては一概に、一定の基準というものを設けているわけではございませんけれども、やはりご家庭の相談を受ける中で、保護者の方に身体的な状況であるとか、精神的な状況であるとか。","voiceIndex":74,"id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"それと、７月から始まったということですが、７月何日が開始日で、開始以降の状況、実績など、分かる範囲で教えていただきたい。施設のショートステイ支援員ですが、この支援員の雇用主はどこになって、雇用形態はどういう形態で、取られている資格等はどういうふうになっているのか、伺います。","respondent":"山下子ども家庭支援センター長","answer":"諸々の届出等々の関係では、事業開始については７月１日付という形にしておりますけれども、実際、この要支援家庭を対象とするショートステイの利用については今、実績はございません。","voiceIndex":76,"id":"exchange-027"},{"speaker":"安藤委員","kind":"質問","question":"登録４名、常勤でという話ですけれど、ちょっとよく分からないのですが、１人に対して４名がつくという感じなのですか。定員が１名ではないですか、それで、これは４名分の人件費という予算なのか、あと、結局どこが雇用するのかということに関しては、もう一度伺わせてください。","respondent":"山下子ども家庭支援センター長","answer":"そこで、しっかりとした身分保障のもとでですけれども、区内唯一の児童養護施設である景徳学園は、そういったところはしっかりしている事業者であると認識しておりまして、今回、こちらの要支援ショートステイ事業を始めたところですので。","voiceIndex":78,"id":"exchange-028"},{"speaker":"安藤委員","kind":"質問","question":"景徳学園において、この事業を実施してもらうということで、区はこの事業に対してどういう責任を負っているのか、よく分からないのですが。区がこの事業を委託しているということなのか、そこら辺がよく分からないので、もう少し教えてもらいたいです。最後に、子ども家庭支援センターは保護者の支援を行うと書いていますけれど、具体的にどういう支援なのか、それもお聞かせください。","respondent":"山下子ども家庭支援センター長","answer":"説明が不足しておりまして申し訳なかったのですけれども、本事業については委託事業という形ですので、私ども品川区のほうで、品川景徳学園に委託していくという形になります。","voiceIndex":80,"id":"exchange-029"},{"speaker":"吉田委員","kind":"質問","question":"すみません。最初に、この制度にアクセスする方法というのでしょうか、まず保護者のほうに自覚があって、このままだと虐待してしまいそうだとかいうような、ご相談から入る場合もあるのかなと思うのですが、例えば、保護者にそういう自覚がないとか、周辺からの客観的な状況から、こういう制度を使ったほうがいいというような判断をするようなことも、あるのでしょうか。教えてください。","respondent":"山下子ども家庭支援センター長","answer":"そのアプローチをしていく流れの中で家庭環境等を把握しているところで、やはりこういったサポート、要支援ショートのような連携が必要であろうというふうな判断に至った場合、まず、そちらのご家族等々にこちらの事業を、リーフレット等を用いて紹介して。","voiceIndex":84,"id":"exchange-030"},{"speaker":"吉田委員","kind":"質問","question":"何か、この１４日間だけで終わるような話ではないような気がするのですけれど、先ほどアクセスのことを伺いましたけれど、その１４日間終了後の、引き続きの支援というのは必要なのではないかと思うのですが、その辺はどういうふうにお考えでしょうか。","respondent":"山下子ども家庭支援センター長","answer":"利用期間については相談しながらということで、１４日以内ということですので、場合によっては例えば７日間程度から始めてみるとか、そういった形も想定しておりますけれども、今、委員ご指摘のあった１４日を超える場合の扱いにつきましては、慎重には考えつつも。","voiceIndex":86,"id":"exchange-031"},{"speaker":"吉田委員","kind":"質問","question":"基本的には、大変必要な制度だと考えております。その辺の、広報というので適切でしょうか、それをどのように考えておられるのか、もう一点伺いたいと思います。","respondent":"山下子ども家庭支援センター長","answer":"周辺の方々に知っていただくという部分につきましても、基本的に広く皆さんにご案内して、周知して利用いただく形態のサービスではありませんので、こちらで景徳学園と情報交換をしながら、必要な方にサービスにつなげていくというような形をとってまいりたいと考えています。","voiceIndex":88,"id":"exchange-032"},{"speaker":"吉田委員","kind":"質問・要望","question":"確かに、広く広報してというものでもないかもしれないですけれど、でもやはり、必要な人にどうやって、これを使っていただくのかというところが、とても気になるところです。それから、この制度を使った後の支援の在り方というのも、やはり必要になってくるのかなというところが、ちょっと懸念事項といいますか、そのように考えております。これ以上は繰り返しになりますので、要望といたします。","respondent":"山下子ども家庭支援センター長","answer":"このサービス単体として利用をされて関係が終わるということではなくて、子ども家庭支援センターの関わりは引き続くという形を考えてあります。","voiceIndex":90,"id":"exchange-033"},{"speaker":"松本委員","kind":"確認","question":"今の吉田委員のお話で、事後のお話はされたので、アクセスのところなのですけれども。ただ、私は、これは広く周知するべきだという立場から、お伺いしたいのですが。既存のショートステイと今回のショートステイの違いの部分、既存のショートステイも、育児疲れというふうな話がある中で、今回のこの事業、明確な違いがあると思うのですけれど、そこを確認のためご答弁いただければと思います。","respondent":"山下子ども家庭支援センター長","answer":"対して、今回の要支援家庭を対象としたショートステイにつきましては、子ども家庭支援センターのほうで利用を勧奨しまして、ご利用いかがですかということで利用につなげていくということで、そこの点に明確な違いがあろうかと思います。","voiceIndex":92,"id":"exchange-034"},{"speaker":"松本委員","kind":"質問","question":"それ以外にも、既存のショートステイの場合は有料で、今回の事業については無料という違いも、結構大きいのかなと思っていまして。そういう中で、メニューとしてそういうものがあるのだと周知しておくというのは、一つ重要ではないかと思うのです。なので、私としては、これはきちっと周知するべきと思うので、これはもうお願いしますと申し上げたいのですけれども、もう一度そこの見解をお願いいたします。","respondent":"山下子ども家庭支援センター長","answer":"その入口でご相談をいただきながら、保護者の状況、お子さんの状況を確認させていただいて、やはり、こういった形が必要だろう、要支援ショートステイのような形が必要だろうというふうな判断ができる場合、利用につなげていくという形で考えてあります。","voiceIndex":94,"id":"exchange-035"},{"speaker":"松澤委員","kind":"質問","question":"予算額約１,７００万円、これは東京都や国からの助成金を活用してやっているのか、品川区が独自で出すのかが１点。これは今年からスタートしていますけれど、今後継続して、こういう無料の形でやっていくのかというのが２点目。３点目に、まず、ここの景徳学園１件でスタートしましたけれど、今後、複数のショートステイ先と契約を考えているのか。この３つを教えてください。","respondent":"山下子ども家庭支援センター長","answer":"２点目の利用料の無料の件ですけれども、今のところ、この要支援家庭対象の児童ショートステイのスキームとしましては、その利用について、こちらのほうで一定判断をした上でご利用につなげるという形は、次年度以降も引き続き事業を続ける考えですので。","voiceIndex":97,"id":"exchange-036"},{"speaker":"松澤委員","kind":"意見","question":"先ほど、他の委員からたしかお話が出ていたのですけれども、助けてほしいという保護者との話合いの中で、保護者の声を聞いて支援を行うのですけれども、個別にどこの部分を、何を助けてほしいのかといいますか、そういうことを具体化するために、やはり保護者との理解の共有がとても大事になってくるのかなと思うのです。","respondent":"山下子ども家庭支援センター長","answer":"児童の目標、また保護者の目標というところで、どういったところを目標において、この最大１４日間過ごしていただくかというところをしっかりと、きめ細かく定めまして、その到達点に達するように支援していくというような形で取り組んでまいりたいと考えています。","voiceIndex":99,"id":"exchange-037"},{"speaker":"松澤委員","kind":"質問","question":"子どもたちは１４日間支援しますよと、そして保護者も一緒に支援していくという話ですよね。そうすると、景徳学園で生活をしている、入所している子どもたちも少なからず、最大２週間いて、ぱっと離れると。その中でも心境の変化もいろいろあるのかなと思うのですけれど、そういうものはどういうふうにお考えですか。","respondent":"山下子ども家庭支援センター長","answer":"委員ご指摘の既に入所されていらっしゃる施設の児童との関係というところにつきましては、今回こちらのショートステイを実施する居室が児童養護施設の建物とは別の棟になっておりまして、基本的な動線としては絡まないような想定で考えてあります。","voiceIndex":101,"id":"exchange-038"},{"speaker":"つる委員","kind":"確認","question":"今、松澤委員から確認があった、品川区の事業としては定員が１人、重なってということはないということですね。Ａさん、Ｂさんがいらっしゃって利用されていたら、その方が何日間かというのはあれですけれど、その方が出たら、またいろいろ予定を組んで次の方にいく、そういうことでいいのでしょうか。","respondent":"山下子ども家庭支援センター長","answer":"例外的なところは一つ、リーフレットにも記載しておりますけれども、兄弟姉妹の方につきましては２人までという形で考えておりまして、委員ご指摘の趣旨としては違うご家庭の児童ということだと思いますので、ご指摘のとおりです。","voiceIndex":105,"id":"exchange-039"},{"speaker":"つる委員","kind":"質問","question":"その２名までにしたというのは、これはいろいろ、景徳学園とのやり取りもあったのかもしれませんけれども、２名までという根拠的な、なぜ２名なのか。年齢が近いとか、いろいろあるのかなと。ケースとしては、そんなに多くないのかどうかあれですけれど、その２名までとしたところを教えてください。","respondent":"山下子ども家庭支援センター長","answer":"就寝されるとしてもお二人ぐらいであろうという物理的な制約が大きいかと思いますけれども、そもそも居室が１つですので、やはり基本的には定員１名ということで考えておりました。","voiceIndex":107,"id":"exchange-040"},{"speaker":"つる委員","kind":"質問・要望","question":"心の準備ですね、心の余裕が生まれる。この景徳学園自体は、歴史が古い、いろいろな変遷で来ているわけですけれど、それを運営する法人が平成２２年に替わられて、１１年ぐらいですか。その後、先ほど目標とありましたけれども、ということを考えると、そこを利用せざるを得ないというのは表現が適切でないと思うのですけれど、利用する際には、どういう状況下で一緒に見に行くような感じになるのですか。","respondent":"山下子ども家庭支援センター長","answer":"基本的にはまず、お子さんの気持ちの面からは、全く行ったことがないところに行くというよりは、一度見たことがある、ここ知っているというところをご利用いただくほうが望ましいかと考えておりますけれども、その辺り、やはり臨機応変に対応していく必要は。","voiceIndex":109,"id":"exchange-041"},{"speaker":"つる委員","kind":"質問・要望","question":"だから、その辺りがどうかなというところです。その辺の関わりを、専門的に養護施設でやっていらっしゃる職員の方のノウハウも含めて、また区で積み上げてきたことも含めて、今後展開する児童相談所等も含めた、結びつくものになっていくのかなというところでは、どういうふうにやっていくのか気になるところなので、その辺りを全体として教えていただきたいということ。これはどのレベルの通院なのか。","respondent":"山下子ども家庭支援センター長","answer":"３点目の利用中の外出につきまして、定期的な通院、例に引いていただいた４日後の通院ということについては難しいかなと考えていますけれども、突発的な受診等につきましては、ショートステイ支援員さんのほうで対応できる限り、実際、健康保険証もお預かりしますので。","voiceIndex":111,"id":"exchange-042"},{"speaker":"つる委員","kind":"確認","question":"ありがとうございました。最後のショートステイの５,０００円、これも人件費なのですか。経費となっていて、お食事代とかお風呂とか入ったりするから、そちらの実費かなと思ったのですけれど。確認したいのと。最後にもう１点。この学園の中での過ごし方、自由時間とかありますけれども、そういうときも基本は１人というか、ついていらっしゃる職員の方とやり取りする、そのような感じでしょうか。","respondent":"山下子ども家庭支援センター長","answer":"２点目の別棟での生活スタイルといいますか、動線としては基本的には混じらない形を考えてありますが、例えばお菓子づくりなどを施設のほうでちょうどやられるとき、一緒にやるのはどうですかというような話が出た場合には、そのお子さんの状況であったり。","voiceIndex":113,"id":"exchange-043"}]},{"id":"topic-05","title":"「子どもの食の支援事業」に対する企業からの寄附","agenda":"「子どもの食の支援事業」に対する企業からの寄附","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"寄附物品は日用品等７品となっていて、「（うち防災備蓄米（アルファ化米）も含む）」というふうになっているのですが、わざわざ防災備蓄米を括弧書きで書いたのは、どういう意味なのでしょうか。教えてください。","respondent":"伊東子育て応援課長","answer":"資料のほうに括弧書きで書いておりますけれども、こちらは区のほうからの防災備蓄米ということで、括弧書きで記載しています。その防災備蓄米、アルファ化米を合わせまして７品目という形でしたので、補足の括弧書きとさせていただきました。","voiceIndex":123,"id":"exchange-044"},{"speaker":"吉田委員","kind":"確認","question":"一応、しあわせ食卓事業ということなのですが、寄附物品としてはカレースープと日用品等の７品の中の１つが、これは入替えのためということですかね、防災備蓄米。これがどういう趣旨で。食の支援を必要とする家庭に対し、食品発送を実施するということなので、その辺の趣旨と、若干ずれるのかなということが懸念されたので、その辺、確認させてください。","respondent":"伊東子育て応援課長","answer":"防災備蓄米に関しましては、有効活用ということでの話が以前からありますので、それと今回のローソンからの物品のボリューム感を考えたとき、これも追加したほうがいいかなということで、追加させていただいたということです。","voiceIndex":125,"id":"exchange-045"},{"speaker":"吉田委員","kind":"確認","question":"少し忘れてしまったので確認ですけれど、しあわせ食卓事業は、こういうことがありますよということで、必要ですというお申出があったところにお配りするというふうに理解していたのですけれど、それを確認させてください。その辺を確認させてください。","respondent":"伊東子育て応援課長","answer":"毎年更新をかけて、募集をかけているところですけれども、今回に関しては昨年、お申込みのあった方に対しての発送という形になります。","voiceIndex":127,"id":"exchange-046"},{"speaker":"吉田委員","kind":"質問","question":"すみません、いろいろ聞いて。こういう一般企業からの申出も大変ありがたいのですけれども、区によってはもう少し社会福祉的な視点の、食の支援事業を行っているところもあるというふうに聞いているのですけれども、品川区として、もう少しその辺の考えというのはないのか、伺いたいと思います。","respondent":"伊東子育て応援課長","answer":"基本的な考えは伝えてありますので、そこは今後の展開といいますか、ローソン自身はまた、第２弾、第３弾もやりたいという話はいただいているところですので、時期も、品物の調達具合も分からない状況ではありますけれども、そういう申出をいただいているところですので。","voiceIndex":129,"id":"exchange-047"},{"speaker":"吉田委員","kind":"質問・要望","question":"分かりました。ぜひ、その辺のもともとの趣旨をぶれさせないで、これからもぜひ継続していただきたいですし、寄附のお申出は大変ありがたいですけれども、そこはきちんと、事業の趣旨を伝えながら一緒に協力して、続けていっていただきたいと思います。これは意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":131,"id":"exchange-048"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5040#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":47285,"voices":145}},{"id":"r03-20210818-5","meetingId":"r03-cm08","date":"2021年8月18日","dateIso":"2021-08-18","committee":"総務委員会","time":"午後 １時００分～午後 ２時３２分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を31件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"冒頭に申し上げたとおり、取り上げる順番を変更し、報告事項(3)から行います。 それでは、(3)三ツ木保育園改築電気設備工事請負契約","agenda":"冒頭に申し上げたとおり、取り上げる順番を変更し、報告事項(3)から行います。 それでは、(3)三ツ木保育園改築電気設備工事請負契約","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"１点だけお聞きします。万が一、首都直下地震、大地震が起きたときに、例えば、停電したときに、このような小さな施設になりますと、非常用電源等はないですよね。品川区全体として、そのような設備は、ほとんど設けていないという考え方でしょうか。学校や区役所の庁舎等、大きいところはありますけれども、実際、その辺についてお聞かせください。","respondent":"小林施設整備課長","answer":"今回の三ツ木保育園につきましては、委員のご指摘のとおり、今、非常用電源は、特別、設置するものではございません。やはり、敷地の形状、施設を避難所としてどう活用するか、そのようなところを総合的に判断していきながら、必要な設備を設置するところです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"田中委員","kind":"意見","question":"防犯カメラの設備についてです。これは外に向けての防犯カメラなのか、それとも、以前、室内の防犯カメラを試験的に設置するようなことがあったと思うのですけれども、今回、三ツ木保育園の中も映すようになるのかなど、分かる範囲でお知らせいただければと思います。","respondent":"小林施設整備課長","answer":"防犯カメラのお話ですが、今回設置しますのは、主に入ってくる方の、いわゆる侵入を監視するといった観点でございまして、施設の出入口、外部の園庭、今回、エレベーターが設置されますので、エレベーターの中に設置するということで、計画は進んでおります。","voiceIndex":7,"id":"exchange-002"},{"speaker":"田中委員","kind":"確認","question":"保育園の防犯カメラの区としての考え方は、今後もこのような形で、入ってくる外部の人間に対しての防犯カメラの整備という考え方なのかというところを確認させていただいてもよろしいですか。","respondent":"小林施設整備課長","answer":"保育の方針ですので、私どもはそこまで把握しているところではございませんが、今まで設計してきた中では、今お話ししましたように、外からの侵入防止を目的に、防犯カメラを設置しているというところは把握している状態です。","voiceIndex":9,"id":"exchange-003"}]},{"id":"topic-02","title":"令和３年７月２６日付 組織改正","agenda":"令和３年７月２６日付 組織改正","exchanges":[{"speaker":"須貝委員","kind":"質問・要望","question":"１点だけお聞かせ願います。接種証明というのは、恐らく、これから日本全体で、それぞれ発行されてきて、そして、それは、海外の映像などを見ていますと、このお店は接種証明を見せてくれとか、要らないとか、そこで人権的に差別みたいなことが出てくると思いますので、総務課でも、人権啓発課でも、しっかりその辺の対応を考えていってほしいと思います。要望ということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":15,"id":"exchange-004"}]},{"id":"topic-03","title":"令和３年度都区財政調整交付金当初算定結果","agenda":"令和３年度都区財政調整交付金当初算定結果","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"言わずもがなですけれども、コロナ禍、本当に第５波が来る中、コロナへの対応が、今のところの最重要課題だと思います。この課題を、財政調整交付金の決定、基準財政需要額の決定、それぞれの決定の中で、どのように考えられてきたのか、その点を伺いたいと思います。","respondent":"黒田財政課長","answer":"令和２年度におきましては、特別交付金において、一定程度算定する。対象とする経費の２分の１を算定するというところで、対応が取られているところですので、令和３年度以降につきましては、また、これから都区協議という中で諮られると考えているところです。","voiceIndex":20,"id":"exchange-005"},{"speaker":"おくの委員","kind":"質問・要望","question":"ざっくりとしたところで、そのようなことだろうと思います。本当に命がかかった課題ですので、繰り返されてきているということで、社会も非常に疲弊してきている、非常に深刻になってきているということですので、決定していく上で、ここら辺を非常に重視していただきたいということを思います。もう一つ、その点、お考えがございましたら。いかがでしょうか。","respondent":"黒田財政課長","answer":"いわゆる新型コロナウイルス感染症対策につきましては、これは、あくまでも財調での算定です。品川区として取るべき対応については、迅速に対応していく。そのために、予算編成や執行の段階で、様々な工夫を図るということになろうかと考えています。","voiceIndex":22,"id":"exchange-006"},{"speaker":"小芝委員","kind":"質問","question":"３ページの都区財政調整（前年度当初算定対比）のところで、先ほど課長からも話がありましたけれども、基準財政収入額Ｂのところの特別区税、軽自動車税、環境性能割が、対前年度比３７.５％の増ということです。この辺を、どのように分析、評価されているのか教えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-007"},{"speaker":"小芝委員","kind":"質問","question":"先ほども話がありました基準財政収入額Ｂの真ん中の株式等譲渡所得割交付金のところで、対前年度比が８５.３％の増というところです。やはり、これも、コロナ禍の影響で、例えば在宅ワークが増えたことで、そのような株式投資をする、資産運用をする方が増えたことで、このような数字になってきたのかどうかということを教えていただけますでしょうか。","respondent":"黒田財政課長","answer":"こちらは過去３年間の平均を交付する、一定の割合において交付するという形になっておりますので、コロナ禍というよりも、これまで株価が上がってきたというところが、いわゆる株の売買取引に反映されて。","voiceIndex":30,"id":"exchange-008"},{"speaker":"須貝委員","kind":"質問","question":"これは、今年だから、こうなのですか。来年度に関しては、また変わってくるような状況なのですか。やはり、東京都内の企業は、ある程度、収益率が高いという企業が集約されているのでしょうか。でも、固定資産税が、これだけの状況でも、これだけの勢いで増えていくならば、その辺を考えるというか、バランス的に東京都に考えていただく余地があると思ったのですが、その辺についてご見解をお聞かせください。","respondent":"黒田財政課長","answer":"この０.１％が、いわゆる児童相談所の開設に当たって、特例的に配分割合を変えたというところで、令和４年度に改めて都区で協議をということになってありますので、いわゆる調整税をどのように配分するかというところは、今後の都区協議の中で。","voiceIndex":32,"id":"exchange-009"},{"speaker":"須貝委員","kind":"意見","question":"意見だけです。やはり、普通、歳入が下がってくれば、各２３区も、それぞれ交付額が下がっても、それは、しようがないと思います。でも、このように、固定資産税だけが、どんどん上がっているということならば、やはり、そこの見直し……。やはり、いろいろないいものが建って、以前は確かに、東京都内の四階建て、または二階建てという状況があったと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":34,"id":"exchange-010"},{"speaker":"渡部委員","kind":"意見","question":"今の説明を聞いていて、この表とにらめっこしたときに、コロナの影響なのか、例えば令和３年度の基準財政需要額の投資的経費を昨年度からぐっと減らしたことは、それぞれこのような状況であるから、２３区でそのようなものを減らしていこうと。ここのパーセンテージが少し動くだけで、相当変わるような気がするのだけれども、その辺の関係性のようなものを少し整理して話してもらえればと思います。","respondent":"黒田財政課長","answer":"ご説明した３ページの下段のところの基準財政需要額の投資的経費が、前年度比で約３４％減になっております。","voiceIndex":35,"id":"exchange-011"},{"speaker":"渡部委員","kind":"質問","question":"僕は、捉え方を誤解しているのかもしれない。やはり、その辺、やるべきことは、しっかりやれるような財政づくりをしていってほしいと思いますので、よろしくお願いします。１点、先ほど小芝委員の質問の中で、これは、僕もよく分からなかったのだけれども、軽自動車税の環境性能割は、要は、古い自動車から、金を余計に取るというものですか。そうですね。それは、うなずいてくれたから、それでいいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":37,"id":"exchange-012"},{"speaker":"たけうち副委員長","kind":"質問","question":"一番最後のページ、４ページ、各区のものが出ています。特に基準財政需要額は、区のほうから、これだけ需要がありますということを出すのだと思うのですけれども、これは当初算定ですが、区のほうで出すものが満額というか、そのまま全部が、これに乗ってくるのか。その辺はどうなのですか。","respondent":"黒田財政課長","answer":"こちらの基準財政需要額の算定方法については、都条例の中で、細かい算定方法が決まっております。いわゆる標準区という３５万人の人口を想定した中で、算定の単価などが定められております。正直申し上げますと、区の需要を丸々見ているというところではございません。","voiceIndex":38,"id":"exchange-013"},{"speaker":"たけうち副委員長","kind":"質問","question":"分かりました。そうすると、あらあら決められたルールの中で、数字を出すので、品川区として単独で、都と、もっとこのような部分があるのだから、このような上乗せをしてほしいなどということの協議みたいなものはなかなかできなくて、２３区なりで統一して、このようなものについては、今までこうだったけれども、来年度以降はこのようにしてくれというような中で変わっていくイメージなのでしょうか。","respondent":"黒田財政課長","answer":"区の特別な需要につきまして、普通算定の中で見込めなかったものについては、特別交付金の中で都と個別のやり取りがあります。ただ、そちらのほうも、いわゆる交付基準がありますから、これは特別交付金として、区のほうから申請する。","voiceIndex":40,"id":"exchange-014"}]},{"id":"topic-04","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"たけうち副委員長","kind":"質問","question":"いろいろな事業をやられてこられたわけですけれども、それぞれによって違うのかもしれませんが、例えばまち歩きのココシル品川や、ここには出ていませんけれども、不動麗子のようなものなど、いろいろ賛否があるのでしょう。どのような流れになっているのか。それともそれぞれによって違うのか、その辺が分かれば教えてください。","respondent":"大澤広報広聴課長","answer":"外に発信する大きな動画を作成する場合は、やはり、専門の事業者に委託をして、一緒に考えて、作成するという流れになってあります。","voiceIndex":46,"id":"exchange-015"},{"speaker":"たけうち副委員長","kind":"質問","question":"非常に区民受けするものと、あれはどうなのかという、本当に賛否両論ある中で、特に職員の方がやられる場合は、非常に怖い面というか、アイデアを出して、採用されて、果たして、あまり評判がよくなかったらどうしようなどということまで思われると、かわいそうだなと我々も思います。外部に投げるものについては、そのような形になるでしょう。そこら辺が分かれば教えてください。","respondent":"大澤広報広聴課長","answer":"アプリを使って、区民の方に発信するという事業に関しましては、やはり、アクセス数やフォロワー数などをずっと追って、一定、評価をしています。","voiceIndex":48,"id":"exchange-016"},{"speaker":"小芝委員","kind":"質問","question":"シティプロモーション事業というところで、平成２７年の事業の立ち上げから、一貫して、ターゲットを区外の若年層の女性、その後、訪日外国人というところです。今後、多分、しばらくは、インバウンドの効果は、なかなか難しいのではないかというところで、今後のターゲットの方向性を教えてもらいたいと思います。","respondent":"大澤広報広聴課長","answer":"今後につきましては、社会状況を見ながらターゲットを絞っていくしかないと、今のところは考えております。ターゲットについては、検討中というところです。","voiceIndex":50,"id":"exchange-017"},{"speaker":"小芝委員","kind":"意見","question":"区外の若年層の女性というと、品川区は、多分、家賃が決して安いわけではないと思います。私の知り合いにも、品川区は高いから諦めたという方もいると聞いていますので、その辺が、なかなか難しいという印象もあります。一方で、やはり、子育て施策が魅力で品川区に来たという方も、当然いるわけですので、もう少し幅を広げていくこともどうかと思います。ご意見だけします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":52,"id":"exchange-018"},{"speaker":"大倉委員","kind":"質問・要望","question":"教えていただければと思うのですが、成果のところで、「住み続けたい」が９０％超えで、品川区は、都内で２位というお話が出たかと思うのですけれども、１位がどこなのかということと、１位も含めて、品川区と比べて、どのような分析をされているかなどということがあれば、教えていただきたい。","respondent":"大澤広報広聴課長","answer":"住みたい町の１位は、資料を探すと出てくると思いますので、後ほどお答えします。今、すぐには出てきません。申し訳ないです。住みたいという方は、生活に便利で、快適であるので住みたいという方が突出して高くなっています。","voiceIndex":53,"id":"exchange-019"},{"speaker":"大倉委員","kind":"質問・要望","question":"これからのシティプロモーションのところで、シビックプライドの向上というところがあり、まさに、これが重要だと私も思っています。これがシビックプライドにすごくつながっていったなどという取組みがあれば、教えていただきたいのと、ほかの自治体等の事例等で、このような取組みがいいなどというものがあったら、教えていただければと思います。","respondent":"大澤広報広聴課長","answer":"地味ですけれども、このような地域の方の活動を紹介するというシティプロモーション事業は、すごく大事なものだと考えております。他自治体の取組みということでは、今のところ、今すぐにご紹介できるような事例はございません。申し訳ないです。","voiceIndex":55,"id":"exchange-020"},{"speaker":"大倉委員","kind":"質問・要望","question":"そのような資源のブラッシュアップというか、地域に知ってもらうというところの取組みは、意外と住み続けている方が認識をしていなくて、新しく住み始めた方から教えてもらうことなどもある。今、そのようなものに特化した交流みたいなことはやられているのでしょうか。なければ、今後、そのようなことも含めてやっていっていただきたいという思いがあるので、教えていただきたいと思います。","respondent":"大澤広報広聴課長","answer":"インスタグラムでは、区民からの「わ！しながわ」メッセージということで、区の魅力をメッセージボードに書いてもらって、インスタグラムに投稿する取組みを、これも投稿数で１,０００件を超えるということなので、このような取組みは今後も継続していきたいと思っています。","voiceIndex":57,"id":"exchange-021"},{"speaker":"大倉委員","kind":"意見","question":"例えば、新しく来た方も含めて、地元の人と、そこは新しい地元ローカルとして捉えてもらう取組みを、シティプロモーションの中でやってもらえると、すごくいいと思っています。ぜひお願いしたい。品川区で既にある事業の中で、これは、実はシティプロモーションなどに活用できる事業というか、そのような制度があって、それをどんどん発信して、交流が生まれるような取組みなどもできるのではないか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":59,"id":"exchange-022"},{"speaker":"渡辺委員長","kind":"質問","question":"分かりました。もう１点、私から伺いたいことは、シティプロモーション事業を、そもそもも含めて、このように、改めて独立してやる価値は、すごく高かったと思っています。多分、想定以上のノウハウが積み上がったり、想定以外の波及効果があったと思うのですが、漠然としていて構わないのですが、その辺の手応えというか、評価をお聞きできればと思います。","respondent":"大澤広報広聴課長","answer":"シティプロモーション事業を始めて、一番感じていることは、職員の意識の変化ということで、やはり、決められた仕事を粛々とやっているのですが、何をしているかを外に発信していくという観点が、薄い部分があったと思うので、広報広聴課が中心になって。","voiceIndex":62,"id":"exchange-023"},{"speaker":"渡部委員","kind":"質問・要望","question":"ですから、そのようなところで、民間人、民間の方にクローズアップしていくことも、すごく面白い。当時、あの地域にいたのです。すごく魅力的な町で、住み続けたいという人がこれだけいてということは、やはり、品川区の施策、地理的な条件もよかったのかもしれないけれども、施策が成功しているからこれだけになっているわけで、やはり、しっかりとこれを継続できる仕組みづくりをやっていただきたい。","respondent":"渡辺委員長","answer":"切り出していただいて、ありがとうあります。先ほど評価というご質問がありましたけれども、やはり、議会も、それがチェックであり、事業評価に値する役割だと思いますので、その点も踏まえて、全委員からご発言いただければと思っています。いかがでしょうか。","voiceIndex":67,"id":"exchange-024"},{"speaker":"須貝委員","kind":"意見","question":"やはり、区の方針や時代の流れもあったのでしょうが、民間と行政がタッグを組んで、まちづくりを推進した。まして、都心に近い。さらに、商業施設もある。今後もシティプロモーションをやっていくのでしょうが、できれば、やはり、まちづくりを官民一体となって、住環境を整えて、多くの方が品川区に定着するような方向に、シティプロモーションも加担して、やっていっていただければありがたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":69,"id":"exchange-025"},{"speaker":"おくの委員","kind":"意見","question":"特にコロナ禍で、生活に非常に困っていらっしゃる方がたくさんいらっしゃって、最近も何人もの方から、そのようなご相談を受けているもので、やはり、このようなことに使うお金があるのなら、そのような方に何とかして回したいと、どうしても思ってしまうもので、私は、そのように思ってしまいます。そのような行動で示せばいいのではないかと、どうしても思ってしまいます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":70,"id":"exchange-026"},{"speaker":"田中委員","kind":"質問・要望","question":"先ほどもあったのですけれども、やはり、最初の事業の立ち上げの頃に作ったＰＲ動画の再生回数などもあるではないですか。今、若い方の親世代の方たちからも、子供に近所に住んでほしいのだけれども、やはり、子供たち家族が、家賃が高くて、区外に行ってしまうといった声が聞かれています。交通手形についてです。区民の方たちの声もきちんと聞いていただきたいということは、強く要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":72,"id":"exchange-027"},{"speaker":"大倉委員","kind":"意見","question":"この資料を見せていただいて、平成２７年から、都内でも初のシティプロモーションサミットを開催したり、都内でも２位になる成績というか、評価がされていて、このようなもの自体が、ここまで、いろいろやってきた歴史としてあります。品川区はこのようにすごく魅力があることをやっているということ自体を、シティプロモーションとして発信しても面白い。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":73,"id":"exchange-028"},{"speaker":"小芝委員","kind":"質問・要望","question":"その一方で、また、新しく芽生えている文化、もしくは、これから芽生えさせることができるような文化も発掘していくことで、それが、これから５年、１０年と、時間がたてば、新しい伝統になってくると思いますので、これ一つというわけではないのですが、もう少し多角的に文化を広めていくという中で、ぜひシティプロモーションを進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-029"},{"speaker":"たけうち副委員長","kind":"質問","question":"これは、ハード面で、多分、そのようなお話も出ているのだと思うのですけれども、間もなく新庁舎に取りかかっていく中で、にぎわいの発信みたいなところで、よく地方都市に行くと、庁舎、もしくは庁舎に連なっている中核になる駅とのスペースに、スタジオみたいなもので、情報発信の場、区民の方が集えるスタジオみたいなものを造って、メディアとなるのでしょうか、そこで区の情報などを流していく。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":75,"id":"exchange-030"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"須貝委員","kind":"意見","question":"今のところ、全く収束するめどが立たない。相手の自治体の方も、そこで応対されるという状況があるので、そこで危険を伴うならば、総務委員会として、今年の視察は中止すべきだと、私は思います。なおかつ、私の今の意見としては、実施されるようでしたら、私は高齢でもありますし、辞退をしたいという意見で考えておりますので、一応、意見だけ申し上げます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":80,"id":"exchange-031"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2206#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":27942,"voices":81}},{"id":"r03-20210819-14","meetingId":"r03-cm08","date":"2021年8月19日","dateIso":"2021-08-19","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ２時２７分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を17件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和３年陳情第３８号、新庁舎整備基本構想に福祉施設の整備を含めるよう品川区に求める陳情","agenda":"令和３年陳情第３８号、新庁舎整備基本構想に福祉施設の整備を含めるよう品川区に求める陳情","exchanges":[{"speaker":"須貝委員","kind":"質問・要望","question":"今の品川区に求める陳情ですが、やはり新庁舎、庁舎ですから、品川区の中枢にあって、それぞれの所管、それぞれの区民生活を主体として全体を見る、また、管理する、それで、事業を行う主たるものです。確かに福祉施設はまだまだ足りないし、まだまだ必要だと思いますが、やはり新庁舎の新設と福祉施設の整備とは別物だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":6,"id":"exchange-001"},{"speaker":"のだて副委員長","kind":"質問","question":"第２回定例会の一般質問でも紹介しましたけれども、区内の特養ホームの待機者は４５０人を超えておりますし、老健施設と合わせた整備率は２３区中２３位、認可保育園の今年４月の不承諾数は約１,０００人、知的障害者のグループホームも、整備率は２２位という状況です。だからこそ区の土地に障害者施設を整備するということが有効だと思いますけれども、いかがでしょうか。","respondent":"東野経理課長","answer":"ただ、基本構想につきましては、先ほども申し上げましたとおり、庁舎そのものについての考え方をまとめるという方向で検討しておりますので、構想の中に入れるということは、今のところ考えているものではございません。","voiceIndex":8,"id":"exchange-002"},{"speaker":"のだて副委員長","kind":"質問","question":"この構想というのが、庁舎そのものの検討だということですが、庁舎の中に福祉施設があったほうがいいと思いますし、第二庁舎のところを今残すということで、そこの行政機能も一か所に集めるという区の考えですから、そこは空くわけです。それを理由に整備が進んでいないということですから、この庁舎建替えに際して、障害者施設含め、福祉施設整備を位置づけるべきだと考えますけれども、いかがでしょうか。","respondent":"東野経理課長","answer":"今検討しております新庁舎につきましては、行政機能を一つの建物に集約しようという考え方で進めているところです。","voiceIndex":10,"id":"exchange-003"},{"speaker":"のだて副委員長","kind":"質問","question":"庁舎の福祉的な視点というのは、どういうことでしょうか。障害者施設など、そういったものが入るということなのでしょうか。","respondent":"東野経理課長","answer":"ソフト的に、多言語対応のデジタルサイネージとか、そういったところも含めて、全ての人が使いやすい庁舎というものを考えている、福祉的な視点を持って考えていきたいというものです。","voiceIndex":12,"id":"exchange-004"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"全ての人が使いやすいということは、庁舎はやはりいろいろな方がいますので、それはある意味、当然のことだと思います。今回求められているのは、福祉施設の整備をしてほしいということですから、ぜひ私はそういったことで検討もしていただきたいし、整備していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"質問","question":"本日結論を出すでお願いしたいと思います。不採択でお願いをします。理由は、先ほど来いろいろお話が出ておりますけれども、新庁舎は、やはり行政機能、また、議会機能も入るわけでありまして、その中で福祉施設を一緒にという形はまた別の話だと私どもは思っておりまして、この陳情については不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-006"},{"speaker":"塚本委員","kind":"質問・要望","question":"理由としては、庁舎は品川区民の方々の関心が高くて、様々な立場の方、考え方の方がご意見、ご要望をお持ちであるという前提の中で、この委員会において、そういった個別の個々の要望、意見というものを上げていくということは、そもそもそぐわない、不適切なものになるのではないかという考えがありますので、当陳情については不採択ということでお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-007"},{"speaker":"高橋（伸）委員","kind":"質問","question":"本日結論を出すということで、不採択でお願いいたします。理由を述べます。やはり新庁舎、これは行政機能の集約、議会機能の集約ということで、この陳情にある障害者施設、これはまた別のところで検討していただいて、今回の陳情は不採択ということでよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-008"},{"speaker":"のだて副委員長","kind":"意見","question":"本日結論を出すということで、採択を主張します。陳情者が言うように、障害者施設が足りないのは確かなことであります。この区の土地に障害者施設を含め福祉施設を整備するということは有効だと考えますので、採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":19,"id":"exchange-009"},{"speaker":"須貝委員","kind":"質問・要望","question":"私も先ほど申し上げましたとおり、新庁舎整備基本構想で、今日まで新庁舎のあり方を検討して、今も継続しているわけです。これはあくまで新庁舎は新庁舎。品川区の機能集約ということもありますが、私はやはりそれはそれできっちり進めていただきたいと思います。先ほど申し上げましたが、確かに福祉施設はまだまだ足りません。本日の陳情に関しては結論を出すということで、不採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-010"},{"speaker":"大倉委員","kind":"質問","question":"本日結論を出すということで、態度については不採択でお願いします。そういったご意見も含めて検討会のほうでもお話が進んでいることと思います。福祉施設の整備については、確かにまだまだこれから進めていっていただくということは大事ですが、これはこれとして、また所管等でしっかりと議論しながら、各委員会等でも議論しながら進めていくべきものと考えますので、不採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-011"}]},{"id":"topic-02","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"最初のところでお伺いをしたいのは、これまで品川区も様々、スタートといえば、再開発もあったり、区民住宅を高橋区長の頃から積極的に建設をしてきたというようなこともあったり、そう考えていくと、これまで区民税は増えてきている部分があって、今度、コロナ禍においても、私はそんなに減っていないと思うのだけれども、そこの現実的な実績的なもので、今年は多分減っていないと思う。","respondent":"黒田財政課長","answer":"ネーミングライツなどのほかにも、何か財源確保できるものということで、制度的には課税自主権というところで、いわゆる法定外税の課税でありますとか、様々手法はあるのですけれども、これらも課題が大きくありまして。","voiceIndex":28,"id":"exchange-012"},{"speaker":"石田（秀）委員","kind":"質問","question":"様々ありがとうあります。間違っていたら教えてください。そこら辺はもう少し突っ込んで教えてもらいたいと思います。調整３税はいいのだけれども、３税が法改正すれば別に増えていっても構わないわけだから、あまりそこにこだわるつもりもないのだけれども、そこは我々もやっていきますし、ぜひ皆さんもそこは強く言っていってほしいと思います。よろしくお願いします。","respondent":"黒田財政課長","answer":"そちらは、ご指摘のとおり、一定所得がありませんと、当然、家賃を支払ったりというところができないという意味では、かなり担税力のある方が転入してきているだろうというところがありまして、例えば、港区は不交付団体でありますが。","voiceIndex":30,"id":"exchange-013"},{"speaker":"石田（秀）委員","kind":"質問","question":"例えば、職員の方々もよく知っているのであれば、若い人たちからいろいろ案を出してもらったりして、そこでそれをいろいろ試しにやってみてしまうとか、何かそういうことをやってもいいような気がするというか、何かそういうことでもしないとなかなか難しいかと思っているのです。この辺のことは、先ほどから言っていた財調も含めて、一般質問でやるつもりでいるので、これでやめておきます。","respondent":"黒田財政課長","answer":"ふるさと納税につきましては、どうしても寄附される区民の方がどのようにこの制度を捉えているかというところもありますし、総務省のほうで指定基準というのを定めまして、地場産品でなければならないとか、返礼品のコストは３割までという中でいうと。","voiceIndex":32,"id":"exchange-014"},{"speaker":"のだて副委員長","kind":"質問","question":"資料の、これも１ページのところに、「住民税は、『地域社会としての会費』」と記載をされていますけれども、住民税を払えない人というのは地域社会の構成員ではないということになってしまうのでしょうかと思ったのです。区はどのように捉えているのか、伺いたいと思います。そうした大本を改善していかなければ改善していかないと思うのですけれども、区のお考えを伺いたいと思います。","respondent":"黒田財政課長","answer":"ただ、税制度の中で、当然、均等割が課税されない非課税の基準というのも制度の中で定められておりますので、均等割があることが、排除の論理を取っているという税制ということではないと認識しています。","voiceIndex":38,"id":"exchange-015"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"最後に意見を言わせていただきたいと思うのですが、先ほど来、ネーミングライツの話とかもありましたが、私は、ネーミングライツなどのそういったところは必要ないと思っていまして、やはりもともと税金として区民から支払っていただいているというものがあるわけですから、それに沿って区のやるべきことはやっていくということだと思いますので、ネーミングライツというのは必要ないと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-016"},{"speaker":"須貝委員","kind":"提案","question":"先ほど渡部委員からもありましたが、２３区もふるさと納税による減収額を地方交付税で一部補填してもらうようなお願いをするべきではないかと思うのです。以前、提案もしましたけれども、ある区では電気製品、もし品川区で作れる場所があれば、それが地産地消でできるのかとか、それからレストランとか、あと、飛行機の模擬運転みたいな、ああいうパイロットのあれもできる。","respondent":"黒田財政課長","answer":"その中では再開発等で、例えば、災害時の安全を確保するでありますとか、交通の便をよくするでありますとか、利便性を高めるというところは必要なところですので、そういった中で取り組んでいくべきものと考えているところです。","voiceIndex":42,"id":"exchange-017"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6114#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":25819,"voices":45}},{"id":"r03-20210820-19","meetingId":"r03-cm08","date":"2021年8月20日","dateIso":"2021-08-20","committee":"災害・環境対策特別委員会","time":"午後 １時００分～午後 ２時４８分","status":"正式会議録","sourceType":"formal","overview":"災害・環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を41件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"二次避難所、福祉避難所関連について伺います。参考資料１の震－７－２２ページにある要配慮者、その中の避難行動要支援者として挙げられている方の人数ですけれども、それぞれ1)から6)まで挙げられていますけれども、そのような方の人数をお教え願えますでしょうか。","respondent":"山本防災課長","answer":"5)の在宅難病患者等につきましては約３０人、6)のその他、こちらについては約９５０人というところで、一部区分が重複されている方もいらっしゃるので、足すと１万２,５００人にはならないのですけれども、合計としては１万２,５００人となっています。","voiceIndex":5,"id":"exchange-001"},{"speaker":"おくの委員","kind":"質問・要望","question":"福祉避難所は１８か所ということですけれども、この１８か所で足りるのか、収容人数が挙げられていないのはどうしてなのか、あるいは収容人数は分かっているのか、そもそも分かっていないということなのでしょうか。そこら辺を教えていただきたいと思います。","respondent":"山本防災課長","answer":"福祉避難所の収容人数のところですが、地域防災計画上、そちらの記載はしておりませんが、こちらについては、改めて、今、算定等も行っているところではありますが、おおよその人数で申し上げますと、大体８００人程度の受け入れが可能というところで計算をしています。","voiceIndex":7,"id":"exchange-002"},{"speaker":"おくの委員","kind":"質問","question":"先ほどの１万２,５００人に対して８００人ということですけれども、大体大丈夫だというようなことなのでしょうか。","respondent":"山本防災課長","answer":"その中で具体的にこの人がこの避難所に行くというようなところも検討する予定になっておりまして、その中で需要数、ニーズ数と受入数というところの調整を行っていきたいというふうに思っているところですので。","voiceIndex":9,"id":"exchange-003"},{"speaker":"おくの委員","kind":"質問","question":"今、個別避難計画を作成中ということで、これから避難行動要支援者も人数の上下があるし、この福祉避難所あるいは二次避難所についても、これから増えていくかもしれないしというような理解でいいのでしょうか。","respondent":"山本防災課長","answer":"福祉避難所等の数ですが、今のところ、こちらの計画の中には１８か所ということで載っているのですけれども、それ以外にも個別で、今、協定等を結ぶための手続きというか、調整をしているところもありますので、そういったところの受入れも増やせるように今後努めてまいります。","voiceIndex":11,"id":"exchange-004"},{"speaker":"おくの委員","kind":"質問","question":"ご存じだと思いますけれども。日程的に個別の計画を急いで定めていかなければいけないというようなことになると思うのですけれども、そこら辺の計画の進め方、要配慮者、要支援者の認定、それから、避難所の認定というか設定、そこら辺は急いでいかなければいけないと思うのですけれども、そこら辺の計画を進めるスピードについては、どのようにお考えでしょうか。","respondent":"山本防災課長","answer":"予算上ですと、今年度、高齢者の部分が約５,０００件で、障害者の部分が３０件を予定していますが、今後どう進めていくかという具体的な部分につきましては、また考えていきたいというふうに思ってあります。","voiceIndex":13,"id":"exchange-005"},{"speaker":"おくの委員","kind":"質問・要望","question":"避難所に決まったところも含めて、いろいろな準備、避難所についての準備もあると思うのですけれども、準備について国のガイドラインがあって、それに基づいて進められていると思うのですけれども、私も古いガイドラインはちらっと目を通したのですけれども、新たなガイドラインが今年になってさらに細かく改訂されているようで、ちょっとそこまで十分には読み込めていないので。","respondent":"山本防災課長","answer":"どういった運営方法をしていくかというところを具体的に検討しながら、また、必要な備蓄資機材にも支出をしていく予定ですので、こちらの検討会の中で具体的な動きをやっていきたいというふうに考えてあります。","voiceIndex":15,"id":"exchange-006"},{"speaker":"おくの委員","kind":"質問","question":"今のご説明の中にちらっと出てきたと思うのですけれども、従来、原則は、まず一般の避難所に避難をして、そこから二次避難所や福祉避難所に移動するときには、地方自治体の判断とかそういうものがあってから移動するということになっていたと思うのですけれども、新しいガイドラインの下では、二次避難所や、あるいは福祉避難所に。","respondent":"山本防災課長","answer":"ただ、中を見てみますと、個別計画の作成と関連するのですけれども、やはりご本人の意向も大事にしたほうがいいと書いてありました。地域の方、顔なじみの方と一緒に避難するほうが安心できるだろうという配慮かと思いますが、そういったところも記載があるところです。","voiceIndex":17,"id":"exchange-007"},{"speaker":"おくの委員","kind":"質問","question":"どこの避難所にまず避難するのかというのは、どの段階で決められることになるのでしょうか。","respondent":"山本防災課長","answer":"避難する避難所の指定ですが、こちらについて、今考えているのは、個別避難計画作成の段階で、ご本人の意向等も聞きながら、その方が区民避難所の要配慮スペースで足りるのか、二次避難所が適しているのか、また福祉避難所への避難がよろしいのかというところを。","voiceIndex":19,"id":"exchange-008"},{"speaker":"おくの委員","kind":"質問・要望","question":"そうしますと、ますます個別避難計画の策定が非常に重要な位置を占めるということになってきたのだと思いますので、ますますそこら辺を急いでいただきたいと思います。よろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-009"},{"speaker":"吉田委員","kind":"意見","question":"最初に申し上げておきますが、私、年のせいもあって、ちょっと耳が聞こえにくいのか、お答えがちょっと明確でないことがあるので、マイクの向きとか、そういうことかなと思いますので、その辺、ちょっとご配慮いただければと思います。ごめんなさい。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":23,"id":"exchange-010"},{"speaker":"吉田委員","kind":"質問・要望","question":"２点目は、水防法、土砂災害防止法の改正に伴って、要配慮者利用施設の管理者に避難確保計画の作成と避難訓練の実施が義務化されて、これが今年度中ということですか、２０２１年度中もしくは２０２１年内ということなのでしょうか。継続的に必要だと思うのですけれども、その辺は既に実施されているのか。その辺を伺いたいと思います。","respondent":"山本防災課長","answer":"失礼いたしました。１点目の福祉部、高齢者福祉課と障害者福祉課との協議状況ですが、こちらにつきましては、先ほど来申し上げております福祉部の検討委員会の中で避難所の在り方は検討しています。","voiceIndex":25,"id":"exchange-011"},{"speaker":"吉田委員","kind":"質問・要望","question":"進めているということで、分かりました。１つだけ事例を挙げれば、聴覚障害の方は、集団の中で自分だけ耳が聞こえないとか、そういうようなことについて、すごく不安、視覚障害の方も情報弱者ということでは、すごくこういうところでは不安が多いかと思うのですけれども、その辺の配慮とか、それから、そういう障害者団体とのこういう避難のときについてのお話合いというのはあるのでしょうか。","respondent":"山本防災課長","answer":"その辺りにつきましては、各個別の避難所のマニュアル等にも、きちんとそういったそれぞれの要配慮者への配慮というところはうたっておりますので、そういったところを丁寧に対応していきたいというふうに思ってあります。","voiceIndex":27,"id":"exchange-012"},{"speaker":"吉田委員","kind":"質問・要望","question":"いかがでしょうか。","respondent":"山本防災課長","answer":"障害者の方への個別の配慮というところで、先ほどお話のありましたビブスですけれども、こちらは全ての避難所ではございませんが、一部避難所ではそういった準備もしていますので、そういったいい取組みにつきましては、いろいろな避難所につなげていけるよう。","voiceIndex":29,"id":"exchange-013"},{"speaker":"吉田委員","kind":"質問・要望","question":"そういういい事例は、ぜひ防災課が間に入って、例えばこういうものがあるよというようなことは、どんどん生かしていっていただきたいと思います。それぞれ配慮するというのは本当にすごく大変なことですけれども、でも一方で、やっぱり障害のある方とかは、すごく不安に思っていらっしゃることですので、その辺はぜひ配慮しながら進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-014"},{"speaker":"たけうち委員","kind":"確認","question":"資料１のハザードマップですけれども、これも前からいろいろな方が言っていたので答えがあったのかもしれないですけれども、ダブってしまうかもしれませんけれども、例えば、浜川小とか、立会小とか、城南小とか、一応、浸水時に避難所に位置づけられているのですけれども、このハザードマップを見ると、やっぱりそれなりの高さで浸水が想定される区域でして、実際にその辺が浸水していれば。","respondent":"山本防災課長","answer":"進め方ですが、こちらは国の取組指針の中では、優先順位等、その辺りを考えながら５年間をかけて作成すると記載されているところでございまして、今、具体的な優先順位を区は定めておりませんので、今後こちらを具体的にまた検討していきたいというふうに考えております。","voiceIndex":33,"id":"exchange-015"},{"speaker":"たけうち委員","kind":"質問・要望","question":"それで、その避難指示を出す基準になっている雨量、この時間帯、その雨量を超えていたのだけれども、それは市の判断で出さなかったということですけれども、私たちも、この名前とか、レベル幾つというのは分かるのですけれども、雨量の発令基準など、ここの発令基準に雨量は書いていないですけれども、書いてあるのかな、その辺のところが、区として。","respondent":"山本防災課長","answer":"防災区民組織と福祉関係者の連携強化というところで、防災区民組織とケアマネジャー等を構成員として、また検討会みたいなものを今年度進めていく予定になっておりまして、その検討会の中で、今後、避難計画をつくる上で。","voiceIndex":35,"id":"exchange-016"},{"speaker":"たけうち委員","kind":"質問・要望","question":"一番最初、１点目のほうは、ちょっとこちらも勉強しなければいけないなと思ったのですけれども、ここに出ている基準以外でも、さっき言ったように岡谷市の場合の、報道がどこまで正しいか確認しなければいけないですけれども、雨量によっても基準があると、その地域によって違うのかもしれないですけれども、その辺のところがもしあるようであれば、またそういったことを我々にも、今回でなくて結構なので。","respondent":"山本防災課長","answer":"１点だけ訂正というか修正させていただきたいところがございまして、浸水ハザードマップのかかっていないところですけれども、一部、例えば御殿山小学校ですと、土砂災害警戒区域というところで一部かかっている部分があるのですけれども、浸水とは別ですけれども。","voiceIndex":37,"id":"exchange-017"},{"speaker":"松澤委員","kind":"質問","question":"ただ、命令系統が東京消防庁の管轄でできないので、できればそういったところを品川区のほうで少し指示系統を変えて、品川区のほうから消防団の方が、そういう運搬なども、人の送迎などもしてあげてほしい、何かそういうことができればいいかと思うのですけれども、いかがでしょうか。","respondent":"五十嵐災害対策担当課長","answer":"実際に自主避難施設は開設したけれども、さほど災害被害がない。そのような中で、消防団員の方々、多くの方々が参集されているという状況であれば、地域のほうで何を求めているのかということに対応するというのは、１つやり方としてはあるのかなというふうに思います。","voiceIndex":40,"id":"exchange-018"},{"speaker":"松澤委員","kind":"質問","question":"避難所のマニュアルの周知ですけれども、コロナバージョンでこういうマニュアルをお配りされていると思うのですけれども、これは、要は自主避難施設、町会長と、その一部の方だけに配られているのか、避難所にこういうものが置いてあるのか、ちょっと教えてください。","respondent":"平原防災体制整備担当課長","answer":"コロナマニュアルについてですけれども、まず１点目、こちらにつきましては昨年度作成させていただきまして、町会長をはじめとした防災区民組織にお配りさせていただいたところですが、併せて区のホームページでも公表させていただいているものです。","voiceIndex":42,"id":"exchange-019","title":"町会・自治会支援"},{"speaker":"松澤委員","kind":"質問","question":"避難所に置いてあるのはすごくいいことなので、もし可能であれば、こういったマニュアルを、誰が来ても、見て開けたら、一番初めはこうやってやるのだみたいな、そういったマニュアルをもう少し置いていただけると、変な話、町会長や防災区民組織の方が、もし全員避難所に来ることができなくなったら、では、誰が運営するのかと困ることにならないように、そこに行けば誰かが必ず分かるというような。","respondent":"平原防災体制整備担当課長","answer":"さらに分かりやすくするようにということもありますので、先ほどの防災課長からの当初の説明にもありましたとおり、現在、コロナマニュアル、さらに分かりやすく改正も進めているところですので、そういった内容も反映させていけたらというふうに思います。","voiceIndex":44,"id":"exchange-020","title":"町会・自治会支援"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"福祉避難所について伺いたいと思います。今、ケアマネジャーの方を通して計画をつくっているということですけれども、高齢者の方はケアマネジャーだと思うのですけれども、障害者の方の個別計画を策定するということは、計画相談をされる方が中心になって個別計画をつくるという形になるのか、障害者の方の個別計画はどういうシステムでつくられているのかを伺いたいと思います。","respondent":"山本防災課長","answer":"１点目のご質問の障害者の方の個別計画作成の委託先ですが、こちらにつきましては、相談支援専門員の方にお願いする予定です。それから、２点目の福祉避難所の支援の体制等々ですが、こちらにつきましては、まだ需要数を算定するところです。","voiceIndex":47,"id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"高齢者の施設は基本的に高齢者が避難する、障害者の施設は障害者の方が避難するということになっていくのではないかと思うのですけれども、それを考えると、障害者の施設が２か所では、とても足りないのではないかと、本当に障害者の方はそれぞれの方々が、災害のとき、どうしたらいいのかというところで、すごく大きな不安を抱えているということをいつも伺うのですけれども。","respondent":"山本防災課長","answer":"２点目の障害者の施設の２か所ですが、あとは二次避難所のほうに心身障害者福祉会館等も入っていますので、そちらの活用等も含めながら、具体的にどう運用していくかというところは考えていきたいというふうに思ってあります。","voiceIndex":49,"id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それで今年は具体的にケアマネの方からも、そういうことが区のほうからあって、計画を立てるようにということで言われているというお話も伺っているのですけれども、このケアマネジャーの方とか、障害者の計画相談の方とか、そういうところで個別計画を立てるのは、基本的にいつまでという日程でお願いしているということがあるのではないかと思うのですけれども、その点についてはいかがでしょうか。","respondent":"山本防災課長","answer":"２点目の検討委員会の内容ですが、検討委員会としては、四半期に１回程度、福祉部の部課長、それから防災課長と災害対策担当部長というメンバーで、あとは外部のアドバイザーを入れての検討委員会を年４回、それ以外に担当者レベルで福祉部の事務職員、それから係長。","voiceIndex":51,"id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"その課題を乗り越えて、どうやったらつくれるかというところまでいかないと、本当に個別計画をしっかりつくれるのかなという思いをしているのですけれども、そういう点では、例えば、避難誘導の支援者を、この計画書には３人書くようにということで具体的にあるというふうにお聞きしたのですけれども、具体的に支援者が見つからないということはないのか、それから。","respondent":"山本防災課長","answer":"今、ケアマネジャー用の計画を作成するためのマニュアル等もつくっているところですが、そういったところを誰がつくっても同じような判断基準でつくれるかというところの、そういった標準化するための基準づくりも１つ、まだそこは検討しているところもありますけれども。","voiceIndex":53,"id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"本当に様々な課題があると思います。それからもう１つ、新型コロナウイルス感染症に係る避難所運営マニュアルについて伺いたいと思います。これは令和２年７月ということなので、今、デルタ株で、これだけ感染爆発しているというところに対応する、そういうマニュアルに変えることが必要なのではないかと思うのですけれども、そこのところで、どういう見直しがされているのか伺いたいと思います。","respondent":"平原防災体制整備担当課長","answer":"もう１点は、その後に行われました国等の通知の状況を新たに入れるですが、こちらにつきましては、現時点では大きな変更がございませんので、時点修正というようなところのレベルで今考えているところです。現状では、今このように考えてあります。","voiceIndex":55,"id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そしてこのゾーニングのところでは、一般の人と感染者が同じフロアだったりするのですけれども、これで本当に感染拡大されるということにならなくて済むのか、このゾーニングという考え方で大丈夫なのかという思いを１つしているのと、それから、このコロナの特徴は無症状の感染者が自覚することなく感染を広げるということが特徴だと思うのですけれども、災害のときに。","respondent":"平原防災体制整備担当課長","answer":"一方で、実際に避難所におきましてコロナに感染しているような方、こちらはマニュアル上では４つの区分に分けるのですが、１つ目の区分、感染者というような区分に対応する方につきましては、区の職員がこちらの対応をすることとなっておりまして。","voiceIndex":57,"id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"パーティションは、１,２００セットと、これだけコロナの感染が広がっている下でも、パーティションのセット数は増やしていないということなのでしょうか。これから増やす計画については、どうなのでしょうか。そういう点では、もっともっと大量に増やしていくという計画をもって増やしていただきたいと思うのですけれども、その点も伺いたいと思います。","respondent":"平原防災体制整備担当課長","answer":"パーティションの、現状１,２００セットというところは、風水害の避難者の想定から割り出した数で、現状１,２００セットを用意させていただいているところですけれども、今後につきましては、現状、具体的にどのように進めていくというような計画はございませんけれども。","voiceIndex":59,"id":"exchange-027"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"コロナ禍、これだけ感染爆発しているという状況で、こういう感染症に対しての対応は、本当に今こそしっかりとっておくことが必要だと思います。このホテル、旅館の借り上げについても、感染者の方が療養できるような形での対応をぜひお願いしたいと思いますし、テントやパーティションも、風水害だけでなく、コロナの感染防止という観点で、大量に増やしていただくよう要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":61,"id":"exchange-028"},{"speaker":"こんの委員","kind":"質問","question":"１点お聞きいたします。」と思うところと、いわゆる被害状況に応じて区民避難所を開設、ここをもう少し具体的に、要するに、区民避難所も開設するというその目安というのでしょうか、自主避難施設のこの１５か所以外の区民避難所を開設するそのタイミングと状況は、どの程度のことをおっしゃっているのか教えてください。","respondent":"山本防災課長","answer":"自主避難施設、それから区民避難所の開設です。台風等の直撃が予想される場合は、自主避難施設１５か所を開設する、そこに避難をしていただくという運用を考えてあります。","voiceIndex":63,"id":"exchange-029"},{"speaker":"こんの委員","kind":"質問","question":"幸い東京都は、そんなに被害がありませんでしたけれども、地方の広島とか、ああいう被害が、長野だとかで出たことを考えておくと、品川区としても、やっぱり土砂災害の危険性があるところも、川の氾濫というところもあるので、こうしたところをもう少し柔軟に、自主避難施設というところをもう少し柔軟に開設するという考え方が必要ではないかと思いますが、いかがでしょうか。","respondent":"山本防災課長","answer":"今回、４月からこの運用を始めているところですが、それ以外の自主避難施設を実際に開けるかどうかというところですけれども、まず一度この体制でやらせていただいて、また地域の方のご意見等も伺いながら、その距離感とか。","voiceIndex":65,"id":"exchange-030"},{"speaker":"こんの委員","kind":"質問・要望","question":"柔軟に考えていけるような体制をぜひお願いしたいのと、状況に応じて臨機応変に、一応決まっていることをベースにするのですが、柔軟に考えていく体制というのも持っていきながら、今後進めていただければというところで、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":67,"id":"exchange-031"},{"speaker":"たけうち委員","kind":"質問","question":"いわゆる要介護４、５で、施設に入れなくて在宅で介護している方は、特養ホーム、またはショートステイなどにも入るぐらいの方なので駄目と、こういうふうに読み取れてしまうのですけれども、これはどこか、都とか国の規約を持ってこられたのか、それとも、つくられた当時は、もしかすると、今ほど停電時の電源確保ということで、最近は北海道の地震での停電を受けて。","respondent":"山本防災課長","answer":"ただ、今、委員ご案内のとおり、各避難所等、また福祉施設等につきましても、非常用発電機等の整備が進んでいますので、そういったところは改めて今後検討していきたいというふうに考えてあります。","voiceIndex":69,"id":"exchange-032"},{"speaker":"たけうち委員","kind":"質問","question":"すみません。でも、そういう方は、もちろんいらっしゃるとは思うのだけれども、どちらかというと、いわゆる要介護５とか４の方のほうが福祉避難所を必要としているのではないかなと思うのだけれども、何かここら辺がよく分からないので、もし今、急にあれしたので、何かまた、今どうしても分からなければ、また後日教えてもらいたいのだけれども、どうでしょうか。","respondent":"山本防災課長","answer":"表現が分かりにくくて大変申し訳ないのですけれども、こちらの意味合いとしては、「入所するに至らない程度の者」と書いてはあるのですけれども、実際に入所されている方は、そのまま施設にいらっしゃるということなので、入所していない方が。","voiceIndex":73,"id":"exchange-033"},{"speaker":"たけうち委員","kind":"質問・要望","question":"要望ですけれども、そういうことであれば、これはもっと分かりやすくしないと、大変誤解を与えますので、先ほどの停電云々等も含めて、ちょっとここ、この場で言って恐縮ですけれども、若干見直しをしていただければと思うので、要望でとどめておきます。お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":75,"id":"exchange-034"}]},{"id":"topic-02","title":"令和３年度 地区総合防災訓練の実施","agenda":"令和３年度 地区総合防災訓練の実施","exchanges":[{"speaker":"小芝委員","kind":"質問・要望","question":"２点ほど確認させてもらいます。こちら、日程といいますか、今回、総合防災訓練を実施される地区ですけれども、こちらは、各地区のほうから具体的に要望があったという認識でよろしかったでしょうか。","respondent":"五十嵐災害対策担当課長","answer":"地区からのご要望かということですが、そのとおりです。","voiceIndex":80,"id":"exchange-035"},{"speaker":"小芝委員","kind":"確認","question":"それで、ちょっと具体的なことですけれども、例えば大井第三地区の町会単位での安否確認訓練というのは、地域センターの集会所とかそういったところの中で、例えば大井第三地区だと５つの町会があるのですけれども、そこでの安否訓練というのは、在宅しているかどうかということを想定した上でされるものなのかどうか。あまりイメージが湧かないのですが、どのような流れなのか。","respondent":"五十嵐災害対策担当課長","answer":"大井第三地区の安否確認訓練についてですけれども、基本的には、町会の役員の方が、各家庭のほうに物資配布訓練と併せてお尋ねし、さらに、ご家庭の中で身体防護訓練とかもやってもらいつつ、安否を確認する流れというふうに聞いてあります。","voiceIndex":82,"id":"exchange-036"},{"speaker":"小芝委員","kind":"質問・要望","question":"要は、集会所から各家庭に行ってという、そこから外に出てということなのですね。分かりました。ちょっと認識が間違っていましたので、すみませんでした。今こういう状況ですので、外に行っての活動というのはまだ分かるのですけれども、やはり感染防止の徹底をぜひ今後も促していただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":84,"id":"exchange-037"},{"speaker":"松澤委員","kind":"質問","question":"今の小芝委員の話に関連するのですけれども、これ、参加人数は役員を中心に３０名ということは、地区の中で全部、要は、荏原第五だと１０町会ありますけれども、１０町会の中で３０名でよろしいのでしょうか。","respondent":"五十嵐災害対策担当課長","answer":"前後するのですけれども、地区で大体３０名から４０名程度というふうに聞いてあります。","voiceIndex":86,"id":"exchange-038"}]},{"id":"topic-03","title":"令和４年度 東京都・品川区合同総合防災訓練","agenda":"令和４年度 東京都・品川区合同総合防災訓練","exchanges":[{"speaker":"くにば委員","kind":"確認","question":"こちらが実施される例年の実施規模、次のとおりで、その他のところですけれども、平成２８年度から令和２年度まで、それぞれ葛飾区、墨田区であったりとか、直近であると、北区と共同開催されたというところで、今回、令和４年度に品川区が共同開催することになった経緯と、その経緯の部分で、これが東京都のほうから打診があって共同開催に至ったのか。","respondent":"五十嵐災害対策担当課長","answer":"今回、品川区が東京都と合同開催するに至る経緯についてのご質問になりますが、これまで東京都の総合防災訓練は、各自治体と連携するわけですけれども、特別区、多摩地区と交互に、ですので、特別区は隔年で訓練を実施しているという状況です。","voiceIndex":92,"id":"exchange-039"},{"speaker":"くにば委員","kind":"質問","question":"もう１点だけ、すみません。こちらは、品川区と東京都に関して、予算的なところで品川区が支出する経費であるとか、予算というのはどれぐらいの規模なのか教えてください。","respondent":"五十嵐災害対策担当課長","answer":"予算規模についてのお話ですが、今回、会場をご覧いただきましても、区内の１か所に集中して行う訓練ではなくて、区内に分散していろいろなところに会場をつくって行う訓練になります。","voiceIndex":94,"id":"exchange-040"},{"speaker":"くにば委員","kind":"質問","question":"大まかというか、ざっくりというか、例えば、例年の規模であるとか、前回、北区に関しては、区民１,０００名に規制したのでちょっと規模が変わったのかもしれませんけれども、例えば中央区、港区、平成３０年度に開催された７,０００名規模、もしくは、多摩市で１万名規模で実施されたとき、それぞれ例年の規模によって、過去の自治体が。","respondent":"五十嵐災害対策担当課長","answer":"ざっくり今、推計しているところですけれども、三、四百万円というところかと思います。","voiceIndex":96,"id":"exchange-041"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6600#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=19&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":35170,"voices":100}},{"id":"r03-20210823-10","meetingId":"r03-cm08","date":"2021年8月23日","dateIso":"2021-08-23","committee":"議会運営委員会","time":"午後 １時００分～午後 １時２１分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を8件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和４年度予算（議会費）","agenda":"令和４年度予算（議会費）","exchanges":[{"speaker":"芹澤委員","kind":"質問・要望","question":"例年出しているものがまず２点と、新規要望を１つ追加しております。２つ目、課題解決のため必要な勉強会の開催、そしてまた、それに伴って必要な海外調査費の計上を要望しております。この２点が昨年から引き続きになります。３点目、新しいものですが、議場もしくは委員会室で各自の端末からネットアクセス可能なしながわフリーＷｉ－Ｆｉの議会棟への工事費を要望いたしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":3,"id":"exchange-001"},{"speaker":"たけうち委員","kind":"質問","question":"２点目は、これは昨年の引き続きなのですが、昨年は応接室のほうに応接セットの配置をしていただいたのですが、議員控室のほうはまだなので、できれば議員控室の応接セットの更新も、ソファーの買換え等含めてお願いしたいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":4,"id":"exchange-002"},{"speaker":"せお委員","kind":"質問・要望","question":"４点挙げさせていただいています。３番目のペーパータオルの設置も感染症対策になります。４番目、議会図書室の機能強化は、司書を置いたり、あと、検索機能を強化していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":5,"id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"例年同様の要望をさせていただきたいと思います。１点目は海外調査は予算計上しないこと、２点目は本会議場の国旗をはずすこと、３点目は傍聴者に対する控室の整備をすることということです。５点目は、本会議と同じく委員会もインターネット中継ができるように必要な設備を整えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":6,"id":"exchange-004"},{"speaker":"須貝委員","kind":"提案","question":"自民党の２番目に、課題解決のために必要な勉強会開催及び調査研究後に行われる海外調査費とありますが、やはり今の現時点で、コロナの問題、あと、商業振興とか、様々な面を考えますと、現在、こういう海外調査費等という調査費などの提案は、私は今はやめたほうがいいのではないかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":8,"id":"exchange-005"},{"speaker":"芹澤委員","kind":"質問・要望","question":"今のお話の補足をしますが、我々の会派で、今時点で海外調査に行こうというような思いは毛頭なくて、来年度の予算に向けて、このコロナの終息を見込んで、こういったことを検討していきたいという思いで要望しております。もちろんコロナの終息状況によっては、実施の可否について議論はあるかと思いますが、ぜひそういった思いも含めてご検討いただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-006"},{"speaker":"中塚委員","kind":"提案","question":"一言。いずれにしても、海外調査については、これまでの申し合せ確認事項の中身に沿って適切に対応すべきであるというのがこの間の確認でありますし、先ほど須貝委員からもご発言がありましたけれども、私も現状では海外調査は必要ないと申し述べておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":10,"id":"exchange-007"}]},{"id":"topic-02","title":"東京都後期高齢者医療広域連合議会の報告","agenda":"東京都後期高齢者医療広域連合議会の報告","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"すみません。(4)の掲額式の確認なのですけれども、内容とか目的とか、あと、出席メンバーというのはどういった方が出席するのですか。確認させてください。","respondent":"工藤区議会事務局長","answer":"こちらのほうは、慣例として確認されているものです。メンバーにつきましては、正副議長含めて、この議運全てのメンバーが出席していただくという形になってあります。正副議長応接室で、前議長の額を掲げまして、除幕式を行う。そのような内容になってあります。","voiceIndex":21,"id":"exchange-008"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5424#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":6791,"voices":24}},{"id":"r03-20210915-10","meetingId":"r03-cm09","date":"2021年9月15日","dateIso":"2021-09-15","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時２４分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を17件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和３年第３回定例会","agenda":"令和３年第３回定例会","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"委員会への参考送付の件について、１件だけ意見を述べさせていただきたいと思います。資料No.１０の意見書採択を求める陳情でありますが、今の申し合せ確認事項では参考送付という規定にはなっておりますけれども、少なくとも品川区民が、しかも区議会事務局の窓口に直接届ける場合には、意見書の提出を求める陳情も委員会への参考送付ではなく付託とするように変更してもよいというふうに思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":5,"id":"exchange-001"}]},{"id":"topic-02","title":"決算特別委員会","agenda":"決算特別委員会","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"議長から現状のままというお話がありましたが、他の会派の皆さんのご意見も伺えたらと思います。コロナ陽性も濃厚接触も、日頃いろいろ皆さん気をつけていますけれども、ここまで感染が広がってくると、区議会の中でも十分考えられるわけで、その際質問の時間や質問する権利を最大限保証するためにも、こういう場合の質問者の変更は認めるべきだと思いますが、皆様はいかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":12,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"それと併せて、議長の後段のほうの款別の話なのですけれども、もちろん感染症対策をしっかり気をつけて行うということも物すごく大事なことであるという認識ではありますが、その中でも、質疑によっては、款をまたがないとできない質疑は実際にこの間何度かありましたので、例えば、第２委員会室に控室があるわけですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-003"},{"speaker":"大沢委員","kind":"質問・要望","question":"今、共産党から２つともご意見頂きましたけれども、解決しなければいけない課題もあろうかと思いますので、９月２日に理事者候補者会が開催されて、そして正副議長でお話をされて、議長から発言があったということに対しては、それは重く受け止めて、議長の発言どおりに決算特別委員会は進行させていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":15,"id":"exchange-004"},{"speaker":"あくつ委員","kind":"意見","question":"今の議長のお考えのとおりで結構だと思います。その日に何かもらい事故でけがをしてしまった。今まで、私は幸運なことにこの１０年間一度も公務を欠席したことはありませんが、多分不慮のこととか病気はあると思うのですけれども、そういうことはこれからもし議論をするのであればじっくりと議論をすべきであって、今回の件に関しては整合性の面からも、議長のおっしゃるとおりだと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":18,"id":"exchange-005"},{"speaker":"須貝委員","kind":"質問","question":"私も確かにお一人お一人の質問時間、質問の大切さ、重要さはよく分かります。でも今までそれを慣例としてやってきて今日まで来たということと、まだこの場で十分な議論をこれからするならば、私はそれも１つ重要なことだと思いますけれども、今回に関して理事候補者会で決まったこと。議長が今お話ししたことは、このまま粛々と私は進めるべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-006"}]},{"id":"topic-03","title":"令和４年度予算（議会費）","agenda":"令和４年度予算（議会費）","exchanges":[{"speaker":"せお委員","kind":"質問","question":"すみません。大きく２つお聞きしたいのですけれども、１点目が先ほど自民党からの議場や委員会室で各自の端末からネットアクセス可能なしながわフリーＷｉ－Ｆｉということで、この議場や委員会室でというところに、議会図書室は入っているのかをお聞きしたいのですが、まずはそちらをお願いします。","respondent":"工藤区議会事務局長","answer":"特段図書室専用で何かをつけるというところではございませんが、そちらのほうの電波が改善されれば、図書室のほうでも電波状況はよくなるというふうに見込んでいるところです。","voiceIndex":31,"id":"exchange-007"},{"speaker":"せお委員","kind":"提案","question":"私どもから提案させていただきました１番と２番に関してなのですけれども、感染症対策として議会で徹底されているのかなのですけれども、本会議場の換気というのは、一度経理課のほうからもお聞きしましたが、庁舎全体ができているというお話だったのですが、本会議場に限って言いますと、本会議が行われ全員集まった状態で、換気は二酸化炭素濃度を測るのが一番目に見えるというか。","respondent":"工藤区議会事務局長","answer":"私どものほうでも、この要望事項が出てまいったところで、経理課のほうに再び確認をさせていただいたところです。結論から言いますと、ＣＯ２の濃度は適正に保たれているという回答を頂いております。","voiceIndex":33,"id":"exchange-008"},{"speaker":"せお委員","kind":"質問","question":"たびたびすみません。４０％から７０％と言われていると思うのですけれども、そこで加湿がもしできないのであれば、水分補給はできるようにしたいなと思うのですが、品川区議会会議規則には、本会議場で水分補給してはいけないとか、していいとかいけないとかいう明記はないようなのですが、水分は取っていいということなのですか。そこら辺をお願いします。","respondent":"本多議長","answer":"頂いた要望、本当に熟慮しまして、本当に考えまして、基本的に議場の中で水分取るというのは、原則駄目なので、これは本当によく考えましたが、従来どおりということで考えました。","voiceIndex":35,"id":"exchange-009"},{"speaker":"せお委員","kind":"質問","question":"すみません。駄目というのは、規則にあるのでしょうか。","respondent":"本多議長","answer":"必要に応じて、退出自体がいい悪いはもちろんありますけれども、私は必要に応じて取っていただくという判断をいたしました。したがいまして、議場に持ち込むということは可とはしなかったという、そういう判断を私はしました。","voiceIndex":37,"id":"exchange-010"},{"speaker":"せお委員","kind":"質問・要望","question":"長くなってしまい、すみません。では、細かいところを言いますけれども、本会議場で時々２時間ぐらいずっと出られないときがあるのです。だから水分補給も湿度を保つことも、すごく大切なのです。繊毛とかが乾くのは２０分だと言われているのです。規則にもないですし、スポ根みたいに部活で水分が取れないみたいなそういう話だったら、やめていただきたいと思っているのですけれども、ご意見お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-011"},{"speaker":"中塚委員","kind":"確認","question":"それと、話が戻ってしまうのですが、議会棟のしながわフリーＷｉ－Ｆｉは、どういうことを想定されているのか教えていただけたらと思って、１つ質問したいのですけれども、各自の端末とありますが、これは区議会議員限定なのか、傍聴者や議会棟を利用する区民の方も、フリーＷｉ－Ｆｉなので、多分接続できるのかなとは思うのですが、対象だけ確認させていただけたらと思います。","respondent":"工藤区議会事務局長","answer":"しながわフリーＷｉ－Ｆｉに関するお問合せですけれども、対象につきましては、フリーＷｉ－Ｆｉですので、傍聴に来られる方も含んでいるものです。","voiceIndex":40,"id":"exchange-012"},{"speaker":"渡辺委員","kind":"提案","question":"というのは、今誤解なくご説明すると、打合せの段階でも、私たちの考え方として一致したのは、これは議会費への要望だったので、予算には関わらないよねと。否定する話ではないと思っています。これはあくまでも予算の範囲では取り上げづらいよねと。であれば、話せる場は幾らでもあるかなと。この範疇だと予算ということになってしまうので、そういう捉え方をしています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":42,"id":"exchange-013"},{"speaker":"せお委員","kind":"質問・要望","question":"前回、少し簡単にご説明させていただいたのですけれども、この議会費を使うということなので、私は今までの経緯が分からなかったので、もし何かの理由で、例えば機械が壊れてしまうからとかそういう理由があって持ち込めないのであれば、例えば本会議場のすぐ外に給水機などを設置していただくというのもありますという意味で、議会費として要望させていただいたところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-014"},{"speaker":"あくつ委員","kind":"質問","question":"別の場でやっていただくのがいいのかなと。私、国会議員の秘書をやっているときは、やはり持込みは駄目だった。今はマフラーしてきては駄目ですよとか、ネクタイは着用とか、バッジの着用とかルールがありますので、その上で各自が水筒を持ってきていいのですか。コーヒーを持ってきていいのですか。だからそれは議長のほうで、私の私見ですけれども、もう１回各議会でどういう取扱いをしているのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":44,"id":"exchange-015"},{"speaker":"大沢委員","kind":"提案","question":"この件におきましては、今皆さんからのお話聞いたので、私たちの会派のせお議員も、そこのところは矛を収めていいかと考えていますので、会議の時間ももう４５分になっておりますので、この件に関しては、私のほうからは提案をしておいてあれですけれども、十分理解できましたので、この話はこれで打ち切っていただいて結構だと思います。そこは委員長にお願いさせていただきたい。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":46,"id":"exchange-016"},{"speaker":"須貝委員","kind":"質問・要望","question":"１点だけ。個々人がどうしても体を気遣ってということならば、先ほど議長も申し上げていましたけれども、退室されて、それで水を飲んでくるとかそういうこともできますし、今それを何か議場で全部オーケーとするというのは、あまりふさわしくないような、すみません、古い人間なので、少しいかがなものかというふうに思いますので、それは慎重に私は考えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-017"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5426#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":15784,"voices":62}},{"id":"r03-20210917-4","meetingId":"r03-c-settlement","date":"2021年9月17日","dateIso":"2021-09-17","committee":"決算特別委員会","time":"午後 ２時３６分～午後 ２時４６分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"小芝副委員長","kind":"意見","question":"ただいまご推挙いただきました、品川区議会自民党の小芝新です。引き続き、感染拡大防止にご協力をお願いしますとともに、円滑かつ実りある委員会の運営に向けて渡部委員長を支えてまいりますので、よろしくお願いをいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":10,"id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1498#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":1960,"voices":18}}]);
